export function formatCurrency(value) {
  return Number(value || 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

// Formata duração em minutos de forma humana (helper global — evita reimplementar
// em cada tela): 42 → "42min" · 2788 → "46h28min" · 3713 → "61h53min".
export function formatarDuracaoMin(mins) {
  const m = Math.max(0, Math.round(Number(mins) || 0));
  return m >= 60 ? `${Math.floor(m / 60)}h${String(m % 60).padStart(2, "0")}min` : `${m}min`;
}

export function isValidCommand(code) {
  // Aceita qualquer prefixo de 1-5 letras + hífen + 4-8 números (ex: CMD-000001, RST-0001)
  return /^[A-Z]{1,5}-\d{4,8}$/.test(String(code || "").trim().toUpperCase());
}

// Regras do "Modo de uso da empresa" (migration 026: interno | externo | ambos)
// — únicas fontes da verdade para habilitar QR por mesa (recurso local) vs.
// link/pedido externo. Centralizadas aqui para o admin (CardapioExternoAdmin)
// e o cardápio público (CardapioPublico.jsx) nunca duplicarem a condicional;
// o backend replica a mesma regra em public.pub_validar_pedido_mesa
// (migration 065).
export function qrMesaEnabled(modoUso) {
  return modoUso === "interno" || modoUso === "ambos";
}
export function externalOrderingEnabled(modoUso) {
  return modoUso === "externo" || modoUso === "ambos";
}

// Documento (CNPJ/CPF) — utilitários
function soDigitos(s) { return String(s || "").replace(/\D/g, ""); }
function docValido(s) { const d = soDigitos(s); return d.length === 11 || d.length === 14; }
function formatarDoc(s) {
  const d = soDigitos(s).slice(0, 14);
  if (d.length <= 11) {
    return d.replace(/(\d{3})(\d)/, "$1.$2").replace(/(\d{3})(\d)/, "$1.$2").replace(/(\d{3})(\d{1,2})$/, "$1-$2");
  }
  return d.replace(/(\d{2})(\d)/, "$1.$2").replace(/(\d{3})(\d)/, "$1.$2").replace(/(\d{3})(\d)/, "$1/$2").replace(/(\d{4})(\d{1,2})$/, "$1-$2");
}

// ID único do aparelho (persistido no localStorage) — usado no controle de versões
function obterDeviceId() {
  try {
    let id = localStorage.getItem("pp_device_id");
    if (!id) { id = (crypto.randomUUID?.() || String(Date.now()) + Math.random().toString(36).slice(2)); localStorage.setItem("pp_device_id", id); }
    return id;
  } catch { return null; }
}

function createCartItem(product) {
  return { ...product, quantity: 1, observation: "", selectedIngredients: [...(product.ingredients || [])], removedIngredients: [], extraIngredients: [], extraIngredientInput: "" };
}

function orderTotal(order) {
  return order.items.reduce((sum, item) => sum + item.price * item.quantity, 0);
}

// Pedido externo de RETIRADA ou ENTREGA (o cliente leva o produto embora) só
// pode ser liberado para entrega depois do pagamento confirmado no Caixa —
// "Consumo no local" (mesmo vindo do canal externo) não entra aqui, pois o
// pagamento desse tipo é sempre depois, no fechamento da conta. Função pura
// e reutilizada tanto pela trava real (marcarEntregue) quanto pelo aviso
// visual no card da cozinha — uma única fonte de verdade pra essa regra.
function pedidoExigePagamentoAntesDeEntregar(o) {
  const pedidoExterno = o?.table === "Externo" || /^EXT-/.test(o?.command || "");
  return pedidoExterno && /retirada|entrega/i.test(o?.table || "");
}
function pedidoAguardandoPagamento(o) {
  return pedidoExigePagamentoAntesDeEntregar(o) && o?.paymentStatus !== "paid";
}

// Abre janela de impressão no padrão térmico 80mm (automação comercial / não fiscal).
// Recebe o corpo já em HTML; aplica o cabeçalho/estilo padrão e dispara a impressão.
function abrirImpressaoTermica(tituloDoc, corpoHTML) {
  const j = window.open("", "_blank", "width=400,height=680");
  if (!j) return;
  j.document.write(`<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><title>${tituloDoc}</title>
  <style>
    @page { size: 80mm auto; margin: 0; }
    * { box-sizing: border-box; }
    body { width: 80mm; margin: 0 auto; padding: 6mm 5mm; font-family: 'Courier New', monospace; font-size: 12px; color:#000; }
    .c{text-align:center} .b{font-weight:bold} .big{font-size:15px} .sm{font-size:10px} .mut{color:#444}
    .row{display:flex;justify-content:space-between;gap:8px}
    .obs{font-size:10px;color:#333;padding-left:8px}
    .hr{border-top:1px dashed #000;margin:6px 0}
    .hr2{border-top:2px solid #000;margin:6px 0}
  </style></head><body>${corpoHTML}
  <script>window.onload=function(){window.print();}<\/script></body></html>`);
  j.document.close();
}

export function itemDetails(item) {
  return [
    item.removedIngredients?.length ? `Sem: ${item.removedIngredients.join(", ")}` : "",
    item.extraIngredients?.length ? `Adicionar: ${item.extraIngredients.join(", ")}` : "",
    item.observation ? `Obs.: ${item.observation}` : "",
  ].filter(Boolean).join(" • ");
}

function canAccess(user, accessId) {
  return Boolean(user && user.active && user.accessIds.includes(accessId));
}

// IDs reservados de acesso operacional (Central Operacional / Operação Mobile)
const OP_MODULOS = [
  { id: "pedidos", acesso: "op_pedidos", label: "Pedidos", ic: "🧾", desc: "Acompanhar pedidos em aberto, novos pedidos e status de atendimento." },
  { id: "cozinha", acesso: "op_cozinha", label: "Cozinha", ic: "👨‍🍳", desc: "Visualizar pedidos enviados para preparo na cozinha." },
  { id: "bar",     acesso: "op_bar",     label: "Bar",     ic: "🍹", desc: "Visualizar bebidas e itens direcionados ao bar." },
  { id: "caixa",   acesso: "op_caixa",   label: "Caixa",   ic: "💳", desc: "Controlar pagamentos, fechamento de conta e baixas." },
];
// Resolve as permissões operacionais do usuário (compatível com o legado:
// admin/superAdmin = acesso total; sem op_* específico → deriva de kitchen/cashier).
function acessosOperacionais(user) {
  const vazio = { pedidos: false, cozinha: false, bar: false, caixa: false, total: false };
  if (!user || !user.active) return vazio;
  const has = (id) => (user.accessIds || []).includes(id);
  const total = !!user.superAdmin || has("admin") || OP_MODULOS.every((m) => has(m.acesso));
  if (total) return { pedidos: true, cozinha: true, bar: true, caixa: true, total: true };
  // "op_managed" = o admin já configurou os acessos operacionais deste usuário
  // explicitamente (mesmo que todos off) → não usa o fallback legado.
  const temOpEspecifico = has("op_managed") || OP_MODULOS.some((m) => has(m.acesso));
  if (temOpEspecifico) return { pedidos: has("op_pedidos"), cozinha: has("op_cozinha"), bar: has("op_bar"), caixa: has("op_caixa"), total: false };
  // Legado: quem tinha "kitchen" via Pedidos/Cozinha/Bar; "cashier" via Caixa.
  return { pedidos: has("kitchen"), cozinha: has("kitchen"), bar: has("kitchen"), caixa: has("cashier"), total: false };
}
const temAcessoOperacional = (user) => { const p = acessosOperacionais(user); return p.pedidos || p.cozinha || p.bar || p.caixa; };

// Tipo de dispositivo por LARGURA da tela (prioridade sobre user-agent):
// celular ≤767px → "mobile"; 768–1024px → "tablet"; >1024px → "desktop".
function identificarTipoDispositivo() {
  const largura = (typeof window !== "undefined") ? window.innerWidth : 1280;
  if (largura <= 767) return "mobile";
  if (largura <= 1024) return "tablet";
  return "desktop";
}

// Ações configuráveis por módulo (briefing item 23 — migration 032)
const ACOES_MODULO = [
  ["ver", "Visualizar"], ["incluir", "Incluir"], ["alterar", "Alterar"],
  ["excluir", "Excluir"], ["inativar", "Inativar"], ["exportar", "Exportar"],
];
function runSelfTests() {
  const sample = createCartItem(initialProducts[0]);
  console.assert(sample.quantity === 1, "Novo item deve iniciar com quantidade 1");
  console.assert(sample.selectedIngredients.length === initialProducts[0].ingredients.length, "Ingredientes devem ser copiados");
  console.assert(isValidCommand("CMD-000245"), "Comanda válida deve passar");
  console.assert(!isValidCommand("245"), "Comanda inválida deve falhar");
  console.assert(Math.abs(orderTotal(initialOrders[0]) - 72.3) < 0.001, "Total do pedido inicial deve considerar quantidade e preço");
  console.assert(itemDetails({ removedIngredients: ["Cebola"], extraIngredients: ["Bacon"], observation: "Ao ponto" }).includes("Sem: Cebola"), "Detalhes devem incluir ingrediente removido");
  console.assert(canAccess(initialUsers[0], "admin"), "Administrador deve acessar administrativo");
  console.assert(!canAccess(initialUsers[2], "cashier"), "Cozinha não deve acessar caixa");
  console.assert(canAccess(initialUsers[1], "tablet"), "Usuário do tablet deve acessar tablet");
}

if (typeof window !== "undefined") runSelfTests();

