  const itensValidos = menu.flatMap((g) => g.itens).map((i) => i.id);
  const ativo = itensValidos.includes(adminSection) ? adminSection : "dashboard";
  // Drawer de navegação mobile (substitui o menu fixo em telas pequenas)
