// Selo de status da assinatura (sidebar do admin). Some quando não há assinatura.
function TrialBadge({ assinatura }) {
  const st = statusAssinatura(assinatura);
  if (st.status === "none") return null;
  const cores = {
    ok:     "border-emerald-400/30 bg-emerald-500/10 text-emerald-300",
    trial:  "border-gold-400/40 bg-gold-400/10 text-gold-300",
    alerta: "border-amber-400/40 bg-amber-500/10 text-amber-300",
    erro:   "border-red-400/40 bg-red-500/10 text-red-300",
    neutro: "border-white/10 bg-white/[0.06] text-slate-300",
  };
  return (
    <div className={`mx-3 mb-2 rounded-xl border px-3 py-1.5 text-center text-[11px] font-black uppercase tracking-wide ${cores[st.tom] || cores.neutro}`}>
      {st.rotulo}
    </div>
  );
}

const PLANO_WHATS = "5518981465499"; // contato comercial Pedido Prime
function MeuPlanoAdmin({ planoAtual, assinaturaAtual, planos = [], planoModulos = [], lojaInfo, isSuperAdmin = false, lojaAtual, definirAssinatura = async () => {}, assinaturas = [], lojas = [] }) {
  const st = statusAssinatura(assinaturaAtual);
  const permitidos = modulosDoPlano(planoAtual, planoModulos); // null = todos
  const todos = Object.keys(MODULOS_LABEL);
  const liberados = permitidos ? todos.filter((s) => permitidos.includes(s)) : todos;
  const bloqueados = permitidos ? todos.filter((s) => !permitidos.includes(s)) : [];
  const tomBadge = { ok: "text-emerald-300", trial: "text-gold-300", alerta: "text-amber-300", erro: "text-red-300", neutro: "text-slate-300" }[st.tom] || "text-slate-300";
  function falar(msg) { window.open(`https://wa.me/${PLANO_WHATS}?text=${encodeURIComponent(msg)}`, "_blank"); }

  // Edição (somente super admin)
  const [form, setForm] = useState({
    planoId: assinaturaAtual?.planoId ?? "", status: assinaturaAtual?.status ?? "active",
    dataFim: assinaturaAtual?.dataFim ?? "", dataTrialFim: assinaturaAtual?.dataTrialFim ?? "", precoMensal: assinaturaAtual?.precoMensal ?? "", observacoes: assinaturaAtual?.observacoes ?? "",
  });
  useEffect(() => { setForm({ planoId: assinaturaAtual?.planoId ?? "", status: assinaturaAtual?.status ?? "active", dataFim: assinaturaAtual?.dataFim ?? "", dataTrialFim: assinaturaAtual?.dataTrialFim ?? "", precoMensal: assinaturaAtual?.precoMensal ?? "", observacoes: assinaturaAtual?.observacoes ?? "" }); }, [assinaturaAtual?.id, lojaAtual]);
  const [erroForm, setErroForm] = useState("");
  // ── Grade analítica de clientes (assinaturas) — filtro por data de vencimento ──
  const [gFiltroIni, setGFiltroIni] = useState("");
  const [gFiltroFim, setGFiltroFim] = useState("");
  const STATUS_PT = { active: "Ativa", trial: "Período de teste", overdue: "Em atraso", blocked: "Bloqueada", canceled: "Cancelada" };
  const nomeLojaDe = (id) => lojas.find((l) => l.id === id)?.nome || `Empresa #${id}`;
  const nomePlanoDe = (id) => planos.find((p) => p.id === id)?.nome || "—";
  const permanenciaTxt = (inicio) => {
    if (!inicio) return "—";
    const d = new Date(inicio); const hoje = new Date();
    const dias = Math.floor((hoje - d) / 86400000); if (dias < 0) return "—";
    if (dias < 30) return `${dias} dia(s)`;
    const meses = (hoje.getFullYear() - d.getFullYear()) * 12 + (hoje.getMonth() - d.getMonth());
    const anos = Math.floor(meses / 12); const m = meses % 12;
    return anos > 0 ? `${anos} ano(s)${m ? ` ${m} mês(es)` : ""}` : `${meses} mês(es)`;
  };
  const linhasGrade = assinaturas
    .map((a) => ({ ...a, inicio: a.dataInicio || a.atualizadoEm || null }))
    .filter((a) => { if (gFiltroIni && (!a.dataFim || a.dataFim < gFiltroIni)) return false; if (gFiltroFim && (!a.dataFim || a.dataFim > gFiltroFim)) return false; return true; })
    .sort((x, y) => new Date(x.inicio || 0) - new Date(y.inicio || 0));
  const gAtivos = linhasGrade.filter((a) => a.status === "active" || a.status === "trial").length;
  const gMrr = linhasGrade.filter((a) => a.status === "active").reduce((s, a) => s + (a.precoMensal || 0), 0);
  // Plano selecionado → o Valor Mensal vem dele (somente leitura).
  const planoSel = planos.find((p) => p.id === form.planoId) || null;
  const valorPlano = planoSel?.precoBase ?? null;
  // Data (YYYY-MM-DD) hoje + N meses — usada para preencher o fim do trial automaticamente.
  const emMeses = (n) => { const d = new Date(); d.setMonth(d.getMonth() + n); return d.toISOString().slice(0, 10); };
  // Ao escolher "Período de teste", preenche o fim do trial com 3 meses (se vazio) — editável.
  const mudarStatus = (novo) => setForm((f) => ({ ...f, status: novo, dataTrialFim: (novo === "trial" && !f.dataTrialFim) ? emMeses(3) : f.dataTrialFim }));
  // Dias restantes com base na data atual e no fim do trial informado no formulário.
  const diasFormTrial = (() => { if (form.status !== "trial" || !form.dataTrialFim) return null; const hoje = new Date(); hoje.setHours(0, 0, 0, 0); const fim = new Date(form.dataTrialFim); fim.setHours(0, 0, 0, 0); return Math.round((fim - hoje) / 86400000); })();
  // Bloqueio: data em que a assinatura ficou "blocked" (atualizadoEm) e há quantos dias.
  const bloqueadoDesde = (assinaturaAtual?.status === "blocked" && assinaturaAtual?.atualizadoEm) ? new Date(assinaturaAtual.atualizadoEm) : null;
  const diasBloqueado = bloqueadoDesde ? Math.max(0, Math.floor((Date.now() - bloqueadoDesde.getTime()) / 86400000)) : null;
  function salvar() {
    if (!form.planoId) { setErroForm("Selecione um plano antes de salvar."); return; }
    if (form.status === "trial" && !form.dataTrialFim) { setErroForm("Informe a data de fim do período de teste (Trial)."); return; }
    if (form.status === "active") {
      if (!form.dataFim) { setErroForm("Informe a data de vencimento."); return; }
      const hoje = new Date(); hoje.setHours(0, 0, 0, 0);
      const venc = new Date(form.dataFim); venc.setHours(0, 0, 0, 0);
      if (venc <= hoje) { setErroForm("A data de vencimento deve ser maior que a data atual."); return; }
    }
    setErroForm("");
    definirAssinatura(lojaAtual, {
      planoId: form.planoId || null,
      status: form.status,
      // No modo Trial, o vencimento segue o fim do trial; nos demais, mantém o campo.
      dataFim: form.status === "trial" ? (form.dataTrialFim || null) : (form.dataFim || null),
      dataTrialFim: form.dataTrialFim || null,
      precoMensal: valorPlano, // valor mensal = preço do plano (somente leitura)
      observacoes: form.observacoes || "",
    });
  }
  const inp = "w-full rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-3 text-white outline-none focus:border-gold-400/60 transition";
  const lbl = "mb-1 block text-xs font-bold uppercase tracking-widest text-slate-500";

  return (
    <main className="space-y-5">
      <PageHeader icone={<IconLicencas />} titulo="Meu Plano" descricao="Plano contratado, status da assinatura e módulos liberados para a sua empresa." />

      {/* Cards principais */}
      <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <div className="rounded-[1.5rem] border border-gold-400/30 bg-gold-400/[0.07] p-5">
          <p className="text-[11px] font-bold uppercase tracking-widest text-gold-400/80">Plano atual</p>
          <p className="page-title mt-2 text-xl font-bold text-white">{planoAtual ? planoAtual.nome : "Não configurado"}</p>
          <p className="mt-0.5 text-sm font-black text-gold-400">{planoAtual?.precoBase != null ? `A partir de ${formatCurrency(planoAtual.precoBase)}/mês` : (planoAtual?.isPersonalizado ? "Sob consulta" : "Acesso completo")}</p>
        </div>
        <CardMetrica titulo="Status da assinatura" valor={st.rotulo} cor={tomBadge} />
        <CardMetrica titulo="Validade" valor={assinaturaAtual?.dataFim ? new Date(assinaturaAtual.dataFim).toLocaleDateString("pt-BR") : "—"} sub={st.diasTrial != null ? `Trial: ${Math.max(0, st.diasTrial)} dia(s)` : ""} cor="text-white" />
        <CardMetrica titulo="Valor contratado" valor={assinaturaAtual?.precoMensal != null ? formatCurrency(assinaturaAtual.precoMensal) : (planoAtual?.precoBase != null ? formatCurrency(planoAtual.precoBase) : "—")} sub="por mês" cor="text-gold-400" />
      </div>

      {!planoAtual && (
        <div className="rounded-2xl border border-white/10 bg-white/[0.03] px-5 py-4 text-sm text-slate-300">
          Sua empresa ainda não tem um plano vinculado — o acesso está <b className="text-emerald-300">completo</b>. Fale com a gente para enquadrar no plano ideal.
        </div>
      )}

      {/* Módulos liberados / bloqueados */}
      <div className="grid gap-4 lg:grid-cols-2">
        <div className="rounded-[2rem] border border-white/10 bg-white/[0.04] p-5">
          <h3 className="page-title text-sm font-bold uppercase tracking-wider text-emerald-300">✓ Módulos liberados</h3>
          <div className="mt-3 flex flex-wrap gap-2">
            {liberados.map((s) => <span key={s} className="rounded-full border border-emerald-400/25 bg-emerald-500/10 px-3 py-1.5 text-xs font-bold text-emerald-200">{MODULOS_LABEL[s]}</span>)}
          </div>
        </div>
        <div className="rounded-[2rem] border border-white/10 bg-white/[0.04] p-5">
          <h3 className="page-title text-sm font-bold uppercase tracking-wider text-slate-400">Disponíveis em outro plano</h3>
          <div className="mt-3 flex flex-wrap gap-2">
            {bloqueados.length === 0 && <p className="text-xs text-slate-500">Todos os módulos estão liberados.</p>}
            {bloqueados.map((s) => <span key={s} className="rounded-full border border-white/10 bg-white/[0.04] px-3 py-1.5 text-xs font-bold text-slate-500">{MODULOS_LABEL[s]}</span>)}
          </div>
        </div>
      </div>

      {/* Ações comerciais */}
      <div className="flex flex-wrap gap-3">
        <button onClick={() => falar(`Olá! Sou da empresa ${lojaInfo?.nome || ""} e quero fazer upgrade do meu plano no Pedido Prime.`)}
          className="font-display rounded-2xl bg-gold-400 px-5 py-3 text-sm font-bold text-blue-950 hover:bg-gold-300 transition active:scale-95 shadow-lg shadow-gold-900/30">⬆ Solicitar upgrade</button>
        <button onClick={() => falar(`Olá! Sou da empresa ${lojaInfo?.nome || ""} e preciso de suporte com o Pedido Prime.`)}
          className="rounded-2xl border border-gold-400/40 bg-gold-400/10 px-5 py-3 text-sm font-black text-gold-200 hover:bg-gold-400/20 transition">Falar com suporte</button>
      </div>

      {/* Painel do super admin: define o plano/assinatura da empresa em foco */}
      {isSuperAdmin && (
        <div className="rounded-[2rem] border border-gold-400/20 bg-gold-400/[0.04] p-6">
          <h3 className="page-title text-base font-bold tracking-tight text-white">Gerenciar assinatura (administrador geral)</h3>
          <p className="mt-1 text-sm text-slate-400">{lojaInfo ? <>Empresa em foco: <b className="text-gold-300">{lojaInfo.nome}</b></> : "Selecione a empresa em foco no menu lateral."}</p>
          <div className="mt-4 grid gap-4 sm:grid-cols-2">
            <div>
              <span className={lbl}>Plano</span>
              <select value={form.planoId} onChange={(e) => setForm({ ...form, planoId: e.target.value ? Number(e.target.value) : "" })} className={inp}>
                <option value="">— Sem plano (acesso completo) —</option>
                {planos.map((p) => <option key={p.id} value={p.id}>{p.nome}{p.precoBase != null ? ` · ${formatCurrency(p.precoBase)}/mês` : ""}</option>)}
              </select>
            </div>
            <div>
              <span className={lbl}>Status</span>
              <select value={form.status} onChange={(e) => mudarStatus(e.target.value)} className={inp}>
                {[["active", "Ativa"], ["trial", "Período de teste"], ["overdue", "Em atraso"], ["blocked", "Bloqueada"], ["canceled", "Cancelada"]].map(([s, l]) => <option key={s} value={s}>{l}</option>)}
              </select>
            </div>
            <div>
              <span className={lbl}>Fim do trial {form.status === "trial" && <span className="text-red-300">*</span>}</span>
              <input type="date" disabled={form.status !== "trial"} value={form.dataTrialFim || ""} onChange={(e) => setForm({ ...form, dataTrialFim: e.target.value })} className={`${inp} ${form.status !== "trial" ? "cursor-not-allowed opacity-60" : ""}`} />
              {diasFormTrial != null && <p className={`mt-1 text-[11px] font-bold ${diasFormTrial < 0 ? "text-red-300" : diasFormTrial <= 7 ? "text-amber-300" : "text-emerald-300"}`}>{diasFormTrial < 0 ? `Trial vencido há ${Math.abs(diasFormTrial)} dia(s) — acesso bloqueado` : `Faltam ${diasFormTrial} dia(s) para o vencimento`}</p>}
            </div>
            <div>
              <span className={lbl}>Vencimento {form.status === "active" && <span className="text-red-300">*</span>}{form.status === "trial" && <span className="text-[10px] font-bold text-slate-500">(= fim do trial)</span>}</span>
              <input type="date" disabled={form.status === "trial"} value={(form.status === "trial" ? form.dataTrialFim : form.dataFim) || ""} onChange={(e) => setForm({ ...form, dataFim: e.target.value })} className={`${inp} ${form.status === "trial" ? "cursor-not-allowed opacity-60" : ""}`} />
            </div>
            <div>
              <span className={lbl}>Valor mensal (R$) <span className="text-[10px] font-bold text-slate-500">(do plano)</span></span>
              <input type="text" readOnly disabled value={valorPlano != null ? formatCurrency(valorPlano) : "—"} className={`${inp} cursor-not-allowed opacity-70`} />
            </div>
            {form.status === "blocked" && (
              <>
                <div>
                  <span className={lbl}>Data de bloqueio</span>
                  <input type="text" readOnly disabled value={bloqueadoDesde ? bloqueadoDesde.toLocaleDateString("pt-BR") : "Registrada ao salvar"} className={`${inp} cursor-not-allowed opacity-70`} />
                </div>
                <div>
                  <span className={lbl}>Dias bloqueado</span>
                  <input type="text" readOnly disabled value={diasBloqueado != null ? `${diasBloqueado} dia(s)` : "—"} className={`${inp} cursor-not-allowed opacity-70`} />
                </div>
              </>
            )}
          </div>
          <div className="mt-4">
            <span className={lbl}>Observação {(form.status === "overdue" || form.status === "blocked") && <span className="text-[10px] font-bold text-slate-500">(motivo do bloqueio)</span>}</span>
            <textarea rows={2} value={form.observacoes || ""} onChange={(e) => setForm({ ...form, observacoes: e.target.value })} placeholder="Descreva o motivo do bloqueio / pagamento pendente (visível ao cliente na mensagem)." className={`${inp} resize-none`} />
          </div>
          {form.status === "overdue" && <p className="mt-2 text-[11px] font-bold text-amber-300">⏳ Ao salvar como "Em atraso", a empresa terá <b className="text-white">7 dias</b> com aviso aos usuários; após esse prazo o acesso é bloqueado automaticamente.</p>}
          {erroForm && <p className="mt-3 rounded-2xl border border-red-400/30 bg-red-500/10 px-4 py-2.5 text-sm font-bold text-red-200">⚠ {erroForm}</p>}
          <div className="mt-4">
            <PrimeButton onClick={salvar}>Salvar assinatura</PrimeButton>
          </div>
        </div>
      )}

      {/* Análise gerencial dos clientes (assinaturas) — só super admin */}
      {isSuperAdmin && (
        <div className="rounded-[2rem] border border-white/10 bg-white/[0.04] p-6">
          <div className="flex flex-wrap items-end justify-between gap-3">
            <div>
              <h3 className="page-title text-base font-bold tracking-tight text-white">Recorrência e permanência dos clientes</h3>
              <p className="mt-1 text-sm text-slate-400">Desde quando cada empresa usa o sistema, recorrência e próximo vencimento — filtre por data de pagamento (vencimento).</p>
            </div>
            <div className="flex items-end gap-2">
              <label className="text-left"><span className="mb-1 block text-[10px] font-bold uppercase tracking-widest text-slate-500">Vencimento de</span>
                <input type="date" value={gFiltroIni} onChange={(e) => setGFiltroIni(e.target.value)} className={inp} /></label>
              <label className="text-left"><span className="mb-1 block text-[10px] font-bold uppercase tracking-widest text-slate-500">até</span>
                <input type="date" value={gFiltroFim} onChange={(e) => setGFiltroFim(e.target.value)} className={inp} /></label>
              {(gFiltroIni || gFiltroFim) && <button onClick={() => { setGFiltroIni(""); setGFiltroFim(""); }} className="rounded-2xl border border-white/10 bg-white/[0.06] px-3 py-2.5 text-xs font-bold text-slate-300 hover:bg-white/10">Limpar</button>}
            </div>
          </div>

          <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4">
            {[["Clientes", linhasGrade.length, "text-white"], ["Ativos / Trial", gAtivos, "text-emerald-300"], ["Receita mensal (ativos)", formatCurrency(gMrr), "text-gold-400"], ["Recorrência", "Mensal", "text-blue-300"]].map(([l, v, c]) => (
              <div key={l} className="rounded-2xl border border-white/10 bg-slate-950/40 px-3 py-2.5"><p className={`page-title text-xl font-bold ${c}`}>{v}</p><p className="text-[11px] text-slate-500">{l}</p></div>
            ))}
          </div>

          <div className="mt-4 overflow-x-auto rounded-2xl border border-white/10">
            <table className="w-full min-w-[760px] text-left text-sm">
              <thead className="bg-white/[0.04] text-[11px] font-bold uppercase tracking-wider text-slate-400">
                <tr>
                  <th className="px-4 py-3">Empresa</th><th className="px-4 py-3">Plano</th><th className="px-4 py-3">Status</th>
                  <th className="px-4 py-3">Cliente desde</th><th className="px-4 py-3">Permanência</th><th className="px-4 py-3">Recorrência</th>
                  <th className="px-4 py-3 text-right">Valor/mês</th><th className="px-4 py-3">Próx. vencimento</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/5">
                {linhasGrade.length === 0 && <tr><td colSpan={8} className="px-4 py-8 text-center text-slate-500">Nenhuma assinatura no período selecionado.</td></tr>}
                {linhasGrade.map((a) => {
                  const tom = a.status === "active" ? "text-emerald-300" : a.status === "trial" ? "text-gold-300" : a.status === "overdue" ? "text-amber-300" : "text-red-300";
                  return (
                    <tr key={a.id} className="text-slate-200 hover:bg-white/[0.02]">
                      <td className="px-4 py-3 font-bold text-white">{nomeLojaDe(a.lojaId)}</td>
                      <td className="px-4 py-3">{nomePlanoDe(a.planoId)}</td>
                      <td className={`px-4 py-3 font-bold ${tom}`}>{STATUS_PT[a.status] || a.status}</td>
                      <td className="px-4 py-3">{a.inicio ? new Date(a.inicio).toLocaleDateString("pt-BR") : "—"}</td>
                      <td className="px-4 py-3 font-bold text-white">{permanenciaTxt(a.inicio)}</td>
                      <td className="px-4 py-3">Mensal</td>
                      <td className="px-4 py-3 text-right font-bold text-gold-300">{a.precoMensal != null ? formatCurrency(a.precoMensal) : "—"}</td>
                      <td className="px-4 py-3">{a.dataFim ? new Date(a.dataFim).toLocaleDateString("pt-BR") : "—"}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </main>
  );
}

// ════════════════════════════════════════════════════════════
//  Admin — Promoções (migration 039)
// ════════════════════════════════════════════════════════════
const PROMO_TIPOS = [
  { id: "percentual", label: "Percentual", icon: "％" },
  { id: "valor", label: "Valor fixo", icon: "R$" },
  { id: "combo", label: "Combo", icon: "🍔" },
  { id: "destaque", label: "Destaque", icon: "⭐" },
  { id: "horario", label: "Por horário", icon: "⏰" },
];
const PROMO_DIAS = ["Dom", "Seg", "Ter", "Qua", "Qui", "Sex", "Sáb"];
function promoLabelTipo(t) { return PROMO_TIPOS.find((x) => x.id === t)?.label || t; }
export function promoResumoDesconto(p) {
  if (p.tipo === "percentual" && p.descontoPercent) return `${p.descontoPercent}% OFF`;
  if (p.tipo === "valor" && p.descontoValor) return `− ${formatCurrency(p.descontoValor)}`;
  if (p.tipo === "combo" && p.descontoValor) return `Combo ${formatCurrency(p.descontoValor)}`;
  return promoLabelTipo(p.tipo);
}
// Promoção está vigente agora? (data + horário + dia da semana)
export function promocaoVigente(p, agora = new Date()) {
  if (!p || p.ativo === false) return false;
  const hojeISO = agora.toISOString().slice(0, 10);
  if (p.dataInicio && hojeISO < p.dataInicio) return false;
  if (p.dataFim && hojeISO > p.dataFim) return false;
  if (Array.isArray(p.diasSemana) && p.diasSemana.length > 0 && !p.diasSemana.includes(agora.getDay())) return false;
  if (p.horaInicio || p.horaFim) {
    const hm = agora.toTimeString().slice(0, 5);
    if (p.horaInicio && hm < p.horaInicio.slice(0, 5)) return false;
    if (p.horaFim && hm > p.horaFim.slice(0, 5)) return false;
  }
  return true;
}

/**
 * Cupons de desconto por loja (migration 075). A quantidade cadastrada aqui é
 * o estoque do cupom: o caixa só consegue aplicar enquanto houver saldo, e o
 * consumo é conferido de novo no banco na hora de fechar a conta.
 */
function CuponsAdmin({ cupons = [], addCupom, editarCupom, toggleCupom, removerCupom }) {
  const VAZIO = {
    codigo: "", descricao: "", tipo: "percentual", valor: "", minimoCompra: "",
    quantidadeTotal: "", inicioEm: "", fimEm: "", horaInicio: "", horaFim: "",
    canal: "ambos", ativo: true,
  };
  const [form, setForm] = useState(VAZIO);
  const [editandoId, setEditandoId] = useState(null);
  const [salvando, setSalvando] = useState(false);
  // Feedback na própria tela — o toast global do hub fica atrás do Admin fullscreen.
  const [feedback, setFeedback] = useState(null); // { tipo: 'ok'|'erro', texto }

  const emEdicao = editandoId != null;
  const valorNum = Number(String(form.valor).replace(/\./g, "").replace(",", ".")) || Number(String(form.valor).replace(",", ".")) || 0;
  const podeSalvar = String(form.codigo).trim().length >= 3 && valorNum > 0 && !salvando;

  function iniciarEdicao(c) {
    setFeedback(null);
    setEditandoId(c.id);
    setForm({
      codigo: c.codigo, descricao: c.descricao || "", tipo: c.tipo, valor: String(c.valor),
      minimoCompra: c.minimoCompra ? String(c.minimoCompra) : "",
      quantidadeTotal: c.quantidadeTotal == null ? "" : String(c.quantidadeTotal),
      inicioEm: c.inicioEm ? String(c.inicioEm).slice(0, 10) : "",
      fimEm: c.fimEm ? String(c.fimEm).slice(0, 10) : "",
      horaInicio: c.horaInicio || "",
      horaFim: c.horaFim || "",
      canal: c.canal || "ambos",
      ativo: c.ativo,
    });
  }

  async function salvar() {
    if (!podeSalvar) {
      setFeedback({ tipo: "erro", texto: "Preencha o código (mín. 3 letras) e o valor do desconto." });
      return;
    }
    if (form.inicioEm && form.fimEm && form.fimEm < form.inicioEm) {
      setFeedback({ tipo: "erro", texto: "A data final não pode ser anterior à data inicial." });
      return;
    }
    setSalvando(true);
    setFeedback(null);
    try {
      const dados = {
        ...form,
        codigo: String(form.codigo).trim().toUpperCase(),
        canal: form.canal || "ambos",
        horaInicio: form.horaInicio || "",
        horaFim: form.horaFim || "",
        inicioEm: form.inicioEm ? `${form.inicioEm}T00:00:00` : null,
        fimEm: form.fimEm ? `${form.fimEm}T23:59:59` : null,
      };
      const r = emEdicao ? await editarCupom(editandoId, dados) : await addCupom(dados);
      // Compatível com retorno antigo (true) e novo ({ ok, erro }).
      const ok = r === true || r?.ok === true;
      if (ok) {
        setForm(VAZIO);
        setEditandoId(null);
        setFeedback({
          tipo: "ok",
          texto: emEdicao
            ? "Cupom atualizado no banco."
            : r?.local
              ? `Cupom ${dados.codigo} criado em modo local.`
              : `Cupom ${dados.codigo} criado e gravado no banco.`,
        });
      } else {
        setFeedback({ tipo: "erro", texto: r?.erro || "Não foi possível salvar o cupom. Tente de novo." });
      }
    } catch (e) {
      setFeedback({ tipo: "erro", texto: "Erro inesperado: " + (e?.message || e) });
    } finally {
      setSalvando(false);
    }
  }

  async function aoRemover(id) {
    const r = await removerCupom(id);
    if (r && r.ok === false) setFeedback({ tipo: "erro", texto: r.erro || "Falha ao excluir." });
    else setFeedback({ tipo: "ok", texto: "Cupom excluído." });
  }

  return (
    <main className="space-y-5">
      <PageHeader icone={<IconPromocao />} titulo="Cupons" descricao="Códigos de desconto da loja — canal (interno/externo/ambos), vigência por data e horário, quantidade e aplicação no PDV." />

      <div className="rounded-[1.5rem] border border-white/10 bg-white/[0.03] p-5">
        <h3 className="mb-3 text-sm font-black text-white">{emEdicao ? "Editar cupom" : "Novo cupom"}</h3>
        <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
          <CampoCupom label="Código" valor={form.codigo} onChange={(v) => setForm({ ...form, codigo: v.toUpperCase().replace(/\s/g, "") })} placeholder="PRIME10" />
          <div>
            <label className="mb-1 block text-[11px] font-bold text-slate-400">Tipo de desconto</label>
            <select value={form.tipo} onChange={(e) => setForm({ ...form, tipo: e.target.value })} className="w-full rounded-xl border border-white/10 bg-slate-950/70 px-3 py-2 text-sm text-white outline-none focus:border-gold-400/60">
              <option value="percentual">Percentual (%)</option>
              <option value="valor">Valor fixo (R$)</option>
            </select>
          </div>
          <CampoCupom label={form.tipo === "valor" ? "Desconto (R$)" : "Desconto (%)"} valor={form.valor} onChange={(v) => setForm({ ...form, valor: v })} placeholder={form.tipo === "valor" ? "10,00" : "10"} />
          <CampoCupom label="Consumo mínimo (R$)" valor={form.minimoCompra} onChange={(v) => setForm({ ...form, minimoCompra: v })} placeholder="0,00" />
          <CampoCupom label="Quantidade disponível" valor={form.quantidadeTotal} onChange={(v) => setForm({ ...form, quantidadeTotal: v.replace(/\D/g, "") })} placeholder="vazio = ilimitado" />
          <div>
            <label className="mb-1 block text-[11px] font-bold text-slate-400">Utilização</label>
            <select value={form.canal} onChange={(e) => setForm({ ...form, canal: e.target.value })} className="w-full rounded-xl border border-white/10 bg-slate-950/70 px-3 py-2 text-sm text-white outline-none focus:border-gold-400/60">
              <option value="ambos">Interno e externo</option>
              <option value="interno">Somente interno (mesa)</option>
              <option value="externo">Somente externo (delivery)</option>
            </select>
          </div>
          <CampoCupom label="Válido de" tipo="date" valor={form.inicioEm} onChange={(v) => setForm({ ...form, inicioEm: v })} />
          <CampoCupom label="Válido até" tipo="date" valor={form.fimEm} onChange={(v) => setForm({ ...form, fimEm: v })} />
          <CampoCupom label="Horário inicial" tipo="time" valor={form.horaInicio} onChange={(v) => setForm({ ...form, horaInicio: v })} />
          <CampoCupom label="Horário final" tipo="time" valor={form.horaFim} onChange={(v) => setForm({ ...form, horaFim: v })} />
          <CampoCupom label="Descrição" valor={form.descricao} onChange={(v) => setForm({ ...form, descricao: v })} placeholder="Campanha Pedido Prime" />
        </div>
        {feedback && (
          <p
            role="status"
            className={`mt-3 rounded-xl border px-3 py-2 text-sm font-semibold ${
              feedback.tipo === "ok"
                ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-700"
                : "border-rose-500/30 bg-rose-500/10 text-rose-700"
            }`}
          >
            {feedback.texto}
          </p>
        )}
        <div className="mt-4 flex flex-wrap items-center gap-2">
          <button
            type="button"
            disabled={!podeSalvar}
            onClick={salvar}
            className="btn-laranja inline-flex min-h-11 items-center justify-center rounded-2xl px-5 text-sm font-black text-white disabled:cursor-not-allowed disabled:opacity-45"
          >
            {salvando ? "Salvando…" : emEdicao ? "Salvar cupom" : "Criar cupom"}
          </button>
          {emEdicao && (
            <button
              type="button"
              onClick={() => { setEditandoId(null); setForm(VAZIO); setFeedback(null); }}
              className="rounded-xl border border-white/10 px-4 py-2 text-sm font-bold text-slate-300"
            >
              Cancelar
            </button>
          )}
        </div>
        <p className="mt-2 text-[11px] text-slate-500">Código em maiúsculas. O PDV valida canal, data, horário, mínimo e quantidade ao aplicar e de novo no fechamento. Horário vazio = qualquer hora do dia.</p>
      </div>

      {cupons.length === 0 ? (
        <div className="rounded-[2rem] border border-white/10 bg-white/[0.03] py-14 text-center">
          <p className="font-black text-white">Nenhum cupom cadastrado.</p>
          <p className="text-sm text-slate-500">Crie um código para o caixa aplicar no fechamento da conta.</p>
        </div>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
          {cupons.map((c) => {
            const restantes = c.quantidadeTotal == null ? null : Math.max(0, c.quantidadeTotal - (c.quantidadeUsada || 0));
            const esgotado = restantes != null && restantes <= 0;
            const canalLabel = c.canal === "interno" ? "Interno (mesa)" : c.canal === "externo" ? "Externo (delivery)" : "Interno e externo";
            return (
              <div key={c.id} className={`flex flex-col rounded-[1.5rem] border p-5 ${c.ativo && !esgotado ? "border-gold-400/30 bg-gold-400/[0.05]" : "border-white/10 bg-white/[0.03] opacity-70"}`}>
                <div className="flex items-start justify-between gap-2">
                  <div className="min-w-0">
                    <p className="truncate font-black text-white">{c.codigo}</p>
                    <p className="truncate text-xs text-slate-400">{c.descricao || "Sem descrição"}</p>
                  </div>
                  <span className="shrink-0 rounded-lg bg-white/10 px-2 py-1 text-xs font-black text-white">
                    {c.tipo === "valor" ? formatCurrency(c.valor) : `${c.valor}%`}
                  </span>
                </div>
                <ul className="mt-3 space-y-1 text-xs text-slate-400">
                  <li>Utilização: <strong className="text-white">{canalLabel}</strong></li>
                  <li>Usados: <strong className="text-white">{c.quantidadeUsada || 0}</strong>{c.quantidadeTotal != null ? ` de ${c.quantidadeTotal}` : " (ilimitado)"}</li>
                  {restantes != null && <li className={esgotado ? "text-rose-400" : ""}>Disponíveis: <strong>{restantes}</strong></li>}
                  {c.minimoCompra > 0 && <li>Mínimo: {formatCurrency(c.minimoCompra)}</li>}
                  {(c.inicioEm || c.fimEm) && (
                    <li>
                      Vigência: {c.inicioEm ? new Date(c.inicioEm).toLocaleDateString("pt-BR") : "—"}
                      {" → "}
                      {c.fimEm ? new Date(c.fimEm).toLocaleDateString("pt-BR") : "—"}
                    </li>
                  )}
                  {(c.horaInicio || c.horaFim) && (
                    <li>
                      Horário: {c.horaInicio || "00:00"} → {c.horaFim || "23:59"}
                    </li>
                  )}
                </ul>
                <div className="mt-4 flex flex-wrap gap-2">
                  <button type="button" onClick={() => iniciarEdicao(c)} className="rounded-lg border border-white/10 px-3 py-1.5 text-xs font-bold text-slate-200">Editar</button>
                  <button type="button" onClick={() => toggleCupom(c.id)} className="rounded-lg border border-white/10 px-3 py-1.5 text-xs font-bold text-slate-200">{c.ativo ? "Desativar" : "Ativar"}</button>
                  <button type="button" onClick={() => aoRemover(c.id)} className="rounded-lg border border-rose-500/30 px-3 py-1.5 text-xs font-bold text-rose-300">Excluir</button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </main>
  );
}

function CampoCupom({ label, valor, onChange, placeholder = "", tipo = "text" }) {
  return (
    <div>
      <label className="mb-1 block text-[11px] font-bold text-slate-400">{label}</label>
      <input
        type={tipo}
        value={valor}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        className="w-full rounded-xl border border-white/10 bg-slate-950/70 px-3 py-2 text-sm text-white outline-none focus:border-gold-400/60"
      />
    </div>
  );
}

function PromocoesAdmin({ promocoes = [], produtos = [], categoriasDb = [], addPromocao, editarPromocao, togglePromocao, removerPromocao }) {
  const [fStatus, setFStatus] = useState("todas"); // todas | ativas | inativas
  const [fTipo, setFTipo] = useState("todos");
  const [editando, setEditando] = useState(null);  // promo | "novo"
  const [confirmar, setConfirmar] = useState(null); // promo a excluir

  const lista = promocoes.filter((p) =>
    (fStatus === "todas" || (fStatus === "ativas" ? p.ativo : !p.ativo)) &&
    (fTipo === "todos" || p.tipo === fTipo)
  );
  const nomeProduto = (id) => produtos.find((x) => x.id === id)?.name || null;
  const nomeCategoria = (id) => categoriasDb.find((x) => x.id === id)?.nome || null;

  return (
    <main className="space-y-5">
      <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
        <PageHeader icone={<IconPromocao />} titulo="Promoções" descricao="Crie campanhas para aumentar as vendas — exibidas no cardápio e no tablet." />
        <PrimeButton onClick={() => setEditando("novo")}><span className="text-lg leading-none">+</span> Nova promoção</PrimeButton>
      </div>

      {/* Filtros */}
      <div className="flex flex-wrap items-center gap-2">
        {[["todas", "Todas"], ["ativas", "Ativas"], ["inativas", "Inativas"]].map(([v, t]) => (
          <FilterChip key={v} size="sm" selected={fStatus === v} label={t} onClick={() => setFStatus(v)} />
        ))}
        <span className="mx-1 h-5 w-px bg-white/10" />
        <select value={fTipo} onChange={(e) => setFTipo(e.target.value)} className="rounded-xl border border-white/10 bg-slate-950/70 px-3 py-2 text-xs text-white outline-none focus:border-gold-400/60">
          <option value="todos">Todos os tipos</option>
          {PROMO_TIPOS.map((t) => <option key={t.id} value={t.id}>{t.label}</option>)}
        </select>
      </div>

      {/* Lista */}
      {lista.length === 0 ? (
        <div className="rounded-[2rem] border border-white/10 bg-white/[0.03] py-14 text-center">
          <span className="text-4xl">🏷️</span>
          <p className="mt-2 font-black text-white">Nenhuma promoção {fStatus !== "todas" ? "neste filtro" : "cadastrada"}.</p>
          <p className="text-sm text-slate-500">Crie sua primeira campanha para destacar ofertas no cardápio.</p>
        </div>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
          {lista.map((p) => (
            <div key={p.id} className={`flex flex-col rounded-[1.5rem] border p-5 transition ${p.ativo ? "border-gold-400/30 bg-gold-400/[0.05]" : "border-white/10 bg-white/[0.03] opacity-70"}`}>
              <div className="flex items-start justify-between gap-2">
                <span className="rounded-full border border-gold-400/30 bg-gold-400/10 px-2.5 py-1 text-[10px] font-black uppercase tracking-wider text-gold-300">{promoLabelTipo(p.tipo)}</span>
                <span className={`rounded-full px-2.5 py-1 text-[10px] font-black uppercase tracking-wider ${p.ativo ? "bg-emerald-500/15 text-emerald-300" : "bg-slate-700/40 text-slate-400"}`}>{p.ativo ? "Ativa" : "Inativa"}</span>
              </div>
              <h3 className="page-title mt-3 text-lg font-bold tracking-tight text-white">{p.nome}</h3>
              <p className="mt-1 text-2xl font-black text-gold-400">{promoResumoDesconto(p)}</p>
              {p.descricao && <p className="mt-1 line-clamp-2 text-xs text-slate-400">{p.descricao}</p>}
              <div className="mt-3 space-y-1 text-[11px] text-slate-400">
                {(p.dataInicio || p.dataFim) && <p>📅 {p.dataInicio ? new Date(p.dataInicio).toLocaleDateString("pt-BR") : "—"} → {p.dataFim ? new Date(p.dataFim).toLocaleDateString("pt-BR") : "—"}</p>}
                {(p.horaInicio || p.horaFim) && <p>⏰ {p.horaInicio || "—"} às {p.horaFim || "—"}</p>}
                {Array.isArray(p.diasSemana) && p.diasSemana.length > 0 && p.diasSemana.length < 7 && <p>🗓️ {p.diasSemana.map((d) => PROMO_DIAS[d]).join(", ")}</p>}
                {(Array.isArray(p.produtoIds) && p.produtoIds.length ? p.produtoIds : (p.produtoId ? [p.produtoId] : [])).map((id) => nomeProduto(id)).filter(Boolean).length > 0 &&
                  <p>🍽️ {(Array.isArray(p.produtoIds) && p.produtoIds.length ? p.produtoIds : [p.produtoId]).map((id) => nomeProduto(id)).filter(Boolean).join(", ")}</p>}
                {nomeCategoria(p.categoriaId) && <p>📂 {nomeCategoria(p.categoriaId)}</p>}
                <p className="text-slate-500">{[p.mostrarCardapio && "Cardápio", p.mostrarTablet && "Tablet"].filter(Boolean).join(" · ") || "Oculta"}</p>
              </div>
              <div className="mt-4 flex gap-2 border-t border-white/10 pt-3">
                <button onClick={() => togglePromocao(p.id)} className="flex-1 rounded-xl border border-white/10 bg-white/[0.05] py-2 text-xs font-black text-slate-300 hover:bg-white/10 transition">{p.ativo ? "Pausar" : "Ativar"}</button>
                <button onClick={() => setEditando(p)} className="flex-1 rounded-xl border border-gold-400/30 bg-gold-400/10 py-2 text-xs font-black text-gold-200 hover:bg-gold-400/20 transition">Editar</button>
                <button onClick={() => setConfirmar(p)} className="rounded-xl border border-red-400/20 bg-red-500/10 px-3 py-2 text-xs font-black text-red-300 hover:bg-red-500/20 transition">🗑️</button>
              </div>
            </div>
          ))}
        </div>
      )}

      {editando && (
        <PromocaoModal promocao={editando === "novo" ? null : editando} produtos={produtos} categoriasDb={categoriasDb}
          onFechar={() => setEditando(null)}
          onSalvar={async (dados) => { const ok = editando === "novo" ? await addPromocao(dados) : await editarPromocao(editando.id, dados); if (ok) setEditando(null); }} />
      )}
      {confirmar && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm" onClick={() => setConfirmar(null)}>
          <div onClick={(e) => e.stopPropagation()} className="w-full max-w-sm rounded-[2rem] border border-red-400/20 bg-slate-900 p-6 text-center shadow-2xl">
            <span className="text-4xl">🗑️</span>
            <h3 className="mt-2 text-lg font-black text-white">Excluir promoção?</h3>
            <p className="mt-1 text-sm text-slate-400">“{confirmar.nome}” será removida permanentemente.</p>
            <div className="mt-5 flex gap-3">
              <button onClick={() => setConfirmar(null)} className="flex-1 rounded-2xl border border-white/10 bg-white/[0.06] py-3 text-sm font-black text-slate-300 hover:bg-white/10">Cancelar</button>
              <button onClick={() => { removerPromocao(confirmar.id); setConfirmar(null); }} className="flex-1 rounded-2xl bg-red-500 py-3 text-sm font-black text-white hover:bg-red-400 transition active:scale-95">Excluir</button>
            </div>
          </div>
        </div>
      )}
    </main>
  );
}

function PromocaoModal({ promocao, produtos = [], categoriasDb = [], onSalvar, onFechar }) {
  const [f, setF] = useState({
    nome: promocao?.nome || "", descricao: promocao?.descricao || "", tipo: promocao?.tipo || "percentual",
    descontoPercent: promocao?.descontoPercent ?? "", descontoValor: promocao?.descontoValor ?? "",
    produtoIds: Array.isArray(promocao?.produtoIds) && promocao.produtoIds.length ? promocao.produtoIds : (promocao?.produtoId ? [promocao.produtoId] : []),
    categoriaId: promocao?.categoriaId || "",
    dataInicio: promocao?.dataInicio || "", dataFim: promocao?.dataFim || "", horaInicio: promocao?.horaInicio || "", horaFim: promocao?.horaFim || "",
    diasSemana: Array.isArray(promocao?.diasSemana) ? promocao.diasSemana : [],
    mostrarCardapio: promocao?.mostrarCardapio !== false, mostrarTablet: promocao?.mostrarTablet !== false, ativo: promocao?.ativo !== false,
  });
  const [addProd, setAddProd] = useState(""); // select temporário p/ adicionar produto
  const inp = "w-full rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-3 text-white outline-none focus:border-gold-400/60 transition";
  const lbl = "mb-1 block text-xs font-bold uppercase tracking-widest text-slate-500";
  const hojeISO = new Date().toISOString().slice(0, 10);
  const horaAgora = new Date().toTimeString().slice(0, 5);
  const dataInvalida = f.dataInicio && f.dataFim && f.dataFim < f.dataInicio;
  const horaInvalida = f.horaInicio && f.horaFim && f.horaFim < f.horaInicio;
  // Não permite início retroativo (data/hora no passado). Ao EDITAR, mantém o início original (grandfather).
  const inicioRetroativo = f.dataInicio && f.dataInicio < hojeISO && f.dataInicio !== (promocao?.dataInicio || "");
  const horaRetroativa = !inicioRetroativo && f.dataInicio === hojeISO && f.horaInicio && f.horaInicio < horaAgora && f.horaInicio !== (promocao?.horaInicio || "");
  const valido = f.nome.trim() && !dataInvalida && !horaInvalida && !inicioRetroativo && !horaRetroativa;
  const toggleDia = (d) => setF((s) => ({ ...s, diasSemana: s.diasSemana.includes(d) ? s.diasSemana.filter((x) => x !== d) : [...s.diasSemana, d].sort() }));
  const adicionarProduto = (id) => { const pid = Number(id); if (!pid || f.produtoIds.includes(pid)) return; setF((s) => ({ ...s, produtoIds: [...s.produtoIds, pid] })); };
  const removerProduto = (id) => setF((s) => ({ ...s, produtoIds: s.produtoIds.filter((x) => x !== id) }));
  const nomeProd = (id) => produtos.find((p) => p.id === id)?.name || `#${id}`;
  const produtosDisponiveis = produtos.filter((p) => !f.produtoIds.includes(p.id));

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/75 backdrop-blur-sm p-4" onClick={onFechar}>
      <div onClick={(e) => e.stopPropagation()} className="flex w-full max-w-3xl flex-col overflow-hidden rounded-[2rem] border border-white/10 bg-slate-900 shadow-2xl max-h-[92vh]">
        <div className="flex items-center justify-between border-b border-white/10 px-6 py-4">
          <div className="flex items-center gap-2.5">
            <span className="flex h-9 w-9 items-center justify-center rounded-2xl bg-gold-400/15 text-gold-300"><IconPromocao /></span>
            <h2 className="page-title text-lg font-bold tracking-tight text-white">{promocao ? "Editar promoção" : "Nova promoção"}</h2>
          </div>
          <button onClick={onFechar} className="rounded-2xl border border-white/10 bg-white/[0.08] px-4 py-2 text-sm font-black text-slate-300 hover:bg-white/20">✕</button>
        </div>

        <div className="flex-1 overflow-y-auto px-6 py-5 space-y-4">
          <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
            <div>
              <span className={lbl}>Nome da promoção *</span>
              <input autoFocus value={f.nome} onChange={(e) => setF({ ...f, nome: e.target.value })} placeholder="Ex.: Terça do Hambúrguer" className={inp} />
            </div>
            <div>
              <span className={lbl}>Descrição</span>
              <input value={f.descricao} onChange={(e) => setF({ ...f, descricao: e.target.value })} placeholder="Detalhes da oferta" className={inp} />
            </div>
          </div>
          <div>
            <span className={lbl}>Tipo de promoção</span>
            <div className="grid grid-cols-3 gap-2 sm:grid-cols-5">
              {PROMO_TIPOS.map((t) => (
                <button key={t.id} type="button" onClick={() => setF({ ...f, tipo: t.id })}
                  className={`rounded-xl border px-2 py-2.5 text-center transition ${f.tipo === t.id ? "border-gold-400/60 bg-gold-400/10" : "border-white/10 bg-slate-950/40 hover:bg-white/[0.06]"}`}>
                  <p className="text-base leading-none">{t.icon}</p>
                  <p className={`mt-1 text-[10px] font-black ${f.tipo === t.id ? "text-gold-300" : "text-slate-400"}`}>{t.label}</p>
                </button>
              ))}
            </div>
          </div>
          {(f.tipo === "percentual" || f.tipo === "valor") && (
            <div className="grid grid-cols-2 gap-3">
              {f.tipo === "percentual" ? (
                <div><span className={lbl}>Desconto (%)</span><input inputMode="numeric" value={f.descontoPercent} onChange={(e) => setF({ ...f, descontoPercent: e.target.value.replace(/[^\d.]/g, "") })} placeholder="10" className={inp} /></div>
              ) : (
                <div><span className={lbl}>Desconto (R$)</span><input inputMode="decimal" value={f.descontoValor} onChange={(e) => setF({ ...f, descontoValor: e.target.value.replace(/[^\d.,]/g, "") })} placeholder="5,00" className={inp} /></div>
              )}
            </div>
          )}
          {f.tipo === "combo" && (
            <div>
              <span className={lbl}>Preço do combo (R$) *</span>
              <input inputMode="decimal" value={f.descontoValor} onChange={(e) => setF({ ...f, descontoValor: e.target.value.replace(/[^\d.,]/g, "") })} placeholder="49,90" className={inp} />
              <p className="mt-1 text-[11px] text-slate-500">Preço fechado do combo. Selecione abaixo os <b className="text-slate-300">produtos que compõem o combo</b> — o cliente adiciona todos de uma vez por este valor.</p>
            </div>
          )}
          <div>
            <span className={lbl}>Produtos da oferta (opcional)</span>
            <div className="flex gap-2">
              <select value={addProd} onChange={(e) => { adicionarProduto(e.target.value); setAddProd(""); }} className={inp}>
                <option value="">{produtosDisponiveis.length ? "+ Adicionar produto…" : "Todos os produtos já adicionados"}</option>
                {produtosDisponiveis.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
              </select>
            </div>
            {f.produtoIds.length > 0 ? (
              <div className="mt-2 flex flex-wrap gap-1.5">
                {f.produtoIds.map((id) => (
                  <span key={id} className="inline-flex items-center gap-1.5 rounded-full border border-gold-400/30 bg-gold-400/10 px-3 py-1 text-xs font-bold text-gold-100">🍽️ {nomeProd(id)}
                    <button type="button" onClick={() => removerProduto(id)} className="text-red-300 hover:text-red-200">✕</button></span>
                ))}
                <button type="button" onClick={() => setF({ ...f, produtoIds: [] })} className="rounded-full px-2 py-1 text-[11px] font-bold text-slate-400 underline hover:text-slate-200">limpar</button>
              </div>
            ) : <p className="mt-1.5 text-[11px] text-slate-500">Selecione um ou mais produtos. Deixe vazio para a oferta valer no geral.</p>}
          </div>
          <div>
            <span className={lbl}>Categoria vinculada (opcional)</span>
            <select value={f.categoriaId} onChange={(e) => setF({ ...f, categoriaId: e.target.value ? Number(e.target.value) : "" })} className={inp}>
              <option value="">— Nenhuma —</option>
              {categoriasDb.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div><span className={lbl}>Início</span><input type="date" min={promocao ? undefined : hojeISO} value={f.dataInicio || ""} onChange={(e) => setF({ ...f, dataInicio: e.target.value })} className={`${inp} ${inicioRetroativo ? "!border-red-400/70" : ""}`} /></div>
            <div><span className={lbl}>Fim</span><input type="date" min={f.dataInicio || hojeISO} value={f.dataFim || ""} onChange={(e) => setF({ ...f, dataFim: e.target.value })} className={`${inp} ${dataInvalida ? "!border-red-400/70" : ""}`} /></div>
            <div><span className={lbl}>Hora início</span><input type="time" value={f.horaInicio || ""} onChange={(e) => setF({ ...f, horaInicio: e.target.value })} className={`${inp} ${horaRetroativa ? "!border-red-400/70" : ""}`} /></div>
            <div><span className={lbl}>Hora fim</span><input type="time" value={f.horaFim || ""} onChange={(e) => setF({ ...f, horaFim: e.target.value })} className={`${inp} ${horaInvalida ? "!border-red-400/70" : ""}`} /></div>
          </div>
          {inicioRetroativo && <p className="rounded-xl border border-red-400/30 bg-red-500/10 px-3 py-2 text-xs font-bold text-red-200">⚠ A data de <b>Início</b> não pode ser retroativa. Use a data de hoje ({new Date(hojeISO + "T00:00").toLocaleDateString("pt-BR")}) ou futura.</p>}
          {horaRetroativa && <p className="rounded-xl border border-red-400/30 bg-red-500/10 px-3 py-2 text-xs font-bold text-red-200">⚠ Como o início é hoje, a <b>Hora início</b> não pode ser anterior ao horário atual ({horaAgora}).</p>}
          {dataInvalida && <p className="rounded-xl border border-red-400/30 bg-red-500/10 px-3 py-2 text-xs font-bold text-red-200">⚠ A data <b>Fim</b> é anterior à data <b>Início</b>. Assim a promoção nunca fica vigente — ajuste para salvar.</p>}
          {horaInvalida && <p className="rounded-xl border border-red-400/30 bg-red-500/10 px-3 py-2 text-xs font-bold text-red-200">⚠ A <b>Hora fim</b> é anterior à <b>Hora início</b>. Para promoção que vira a madrugada, deixe a hora fim em branco.</p>}
          <div>
            <span className={lbl}>Dias da semana válidos</span>
            <div className="flex flex-wrap gap-2">
              {PROMO_DIAS.map((d, i) => (
                <button key={i} type="button" onClick={() => toggleDia(i)}
                  className={`h-10 w-12 rounded-xl border text-xs font-black transition ${f.diasSemana.includes(i) ? "border-gold-400 bg-gold-400 text-blue-950" : "border-white/10 bg-white/[0.04] text-slate-400 hover:bg-white/10"}`}>{d}</button>
              ))}
            </div>
            <p className="mt-1 text-[11px] text-slate-500">Nenhum selecionado = todos os dias.</p>
          </div>
          <div className="flex flex-wrap gap-2">
            {[["mostrarCardapio", "📱 Exibir no cardápio externo"], ["mostrarTablet", "📲 Exibir no tablet"]].map(([k, t]) => (
              <button key={k} type="button" onClick={() => setF({ ...f, [k]: !f[k] })}
                className={`rounded-xl border px-3 py-2 text-xs font-bold transition ${f[k] ? "border-gold-400/60 bg-gold-400/10 text-gold-200" : "border-white/10 bg-white/[0.03] text-slate-500"}`}>
                <span className={`mr-1.5 ${f[k] ? "" : "opacity-40"}`}>{f[k] ? "✓" : "○"}</span>{t}
              </button>
            ))}
          </div>
        </div>

        <div className="shrink-0 border-t border-white/10 px-6 py-4 flex gap-3">
          <button onClick={onFechar} className="flex-1 rounded-2xl border border-white/10 bg-white/[0.06] py-3.5 text-sm font-black text-slate-300 hover:bg-white/10">Cancelar</button>
          <button onClick={() => valido && onSalvar(f)} disabled={!valido}
            className="font-display flex-[2] rounded-2xl bg-gold-400 py-3.5 text-sm font-bold text-blue-950 hover:bg-gold-300 transition active:scale-95 shadow-lg shadow-gold-900/30 disabled:opacity-50">
            {promocao ? "Salvar alterações" : "+ Criar promoção"}
          </button>
        </div>
      </div>
    </div>
  );
}

// ════════════════════════════════════════════════════════════
//  Admin — Adicionais e Variações de um produto (migration 040)
// ════════════════════════════════════════════════════════════
function GruposOpcoesModal({ produto, api, onFechar }) {
  const grupos = (api.grupos || []).filter((g) => g.produtoId === produto.id).sort((a, b) => (a.ordem ?? 0) - (b.ordem ?? 0));
  const [novoGrupo, setNovoGrupo] = useState({ nome: "", minSelect: 0, maxSelect: 1, obrigatorio: false });
  const [novaOpcao, setNovaOpcao] = useState({}); // { [grupoId]: { nome, precoDelta } }
  const inp = "w-full rounded-xl border border-white/10 bg-slate-950/70 px-3 py-2 text-sm text-white outline-none focus:border-gold-400/60 transition";

  async function criarGrupo() {
    if (!novoGrupo.nome.trim()) return;
    await api.addGrupo(produto.id, { ...novoGrupo, ordem: grupos.length });
    setNovoGrupo({ nome: "", minSelect: 0, maxSelect: 1, obrigatorio: false });
  }
  async function criarOpcao(grupoId) {
    const d = novaOpcao[grupoId];
    if (!d?.nome?.trim()) return;
    await api.addOpcao(grupoId, { nome: d.nome.trim(), precoDelta: Number(String(d.precoDelta || "0").replace(",", ".")) || 0 });
    setNovaOpcao((c) => ({ ...c, [grupoId]: { nome: "", precoDelta: "" } }));
  }

  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/75 backdrop-blur-sm p-4" onClick={onFechar}>
      <div onClick={(e) => e.stopPropagation()} className="flex w-full max-w-2xl flex-col overflow-hidden rounded-[2rem] border border-white/10 bg-slate-900 shadow-2xl max-h-[92vh]">
        <div className="flex items-center justify-between border-b border-white/10 px-6 py-4">
          <div className="flex items-center gap-2.5">
            <span className="flex h-9 w-9 items-center justify-center rounded-2xl bg-gold-400/15 text-gold-300"><IconProdutos /></span>
            <div>
              <h2 className="page-title text-lg font-bold tracking-tight text-white">Adicionais e Variações</h2>
              <p className="text-xs text-slate-500">{produto.name}</p>
            </div>
          </div>
          <button onClick={onFechar} className="rounded-2xl border border-white/10 bg-white/[0.08] px-4 py-2 text-sm font-black text-slate-300 hover:bg-white/20">✕</button>
        </div>

        <div className="flex-1 overflow-y-auto px-6 py-4 space-y-4">
          {grupos.length === 0 && <p className="rounded-2xl border border-white/10 bg-white/[0.03] px-4 py-3 text-sm text-slate-400">Nenhum grupo ainda. Crie grupos como “Tamanho”, “Ponto da carne”, “Adicionais” ou “Escolha a bebida”.</p>}

          {grupos.map((g) => {
            const ops = (api.opcoes || []).filter((o) => o.grupoId === g.id).sort((a, b) => (a.ordem ?? 0) - (b.ordem ?? 0));
            const nd = novaOpcao[g.id] || { nome: "", precoDelta: "" };
            return (
              <div key={g.id} className="rounded-2xl border border-white/10 bg-white/[0.03] p-4">
                <div className="flex flex-wrap items-end gap-2">
                  <div className="min-w-[140px] flex-1">
                    <span className="mb-1 block text-[10px] font-bold uppercase tracking-widest text-slate-500">Grupo</span>
                    <input value={g.nome} onChange={(e) => api.editarGrupo(g.id, { nome: e.target.value })} className={inp} />
                  </div>
                  <div className="w-16"><span className="mb-1 block text-[10px] font-bold uppercase tracking-widest text-slate-500">Mín</span><input inputMode="numeric" value={g.minSelect} onChange={(e) => api.editarGrupo(g.id, { minSelect: Number(e.target.value.replace(/\D/g, "")) || 0 })} className={inp} /></div>
                  <div className="w-16"><span className="mb-1 block text-[10px] font-bold uppercase tracking-widest text-slate-500">Máx</span><input inputMode="numeric" value={g.maxSelect} onChange={(e) => api.editarGrupo(g.id, { maxSelect: Number(e.target.value.replace(/\D/g, "")) || 1 })} className={inp} /></div>
                  <button onClick={() => api.editarGrupo(g.id, { obrigatorio: !g.obrigatorio })} className={`rounded-xl border px-3 py-2 text-xs font-black transition ${g.obrigatorio ? "border-gold-400/60 bg-gold-400/10 text-gold-200" : "border-white/10 bg-white/[0.03] text-slate-400"}`}>{g.obrigatorio ? "Obrigatório" : "Opcional"}</button>
                  <button onClick={() => api.removerGrupo(g.id)} className="rounded-xl border border-red-400/20 bg-red-500/10 px-3 py-2 text-xs font-black text-red-300 hover:bg-red-500/20">🗑️</button>
                </div>

                {/* Opções do grupo */}
                <div className="mt-3 space-y-1.5">
                  {ops.map((o) => (
                    <div key={o.id} className="flex items-center gap-2 rounded-xl border border-white/5 bg-white/[0.02] px-3 py-2">
                      <span className="flex-1 truncate text-sm text-white">{o.nome}</span>
                      <span className="text-xs font-black text-gold-400">{o.precoDelta > 0 ? `+ ${formatCurrency(o.precoDelta)}` : (o.precoDelta < 0 ? formatCurrency(o.precoDelta) : "Grátis")}</span>
                      <button onClick={() => api.removerOpcao(o.id)} className="rounded-lg p-1 text-slate-500 hover:text-red-300">🗑️</button>
                    </div>
                  ))}
                </div>
                {/* Nova opção */}
                <div className="mt-2 flex gap-2">
                  <input value={nd.nome} onChange={(e) => setNovaOpcao((c) => ({ ...c, [g.id]: { ...nd, nome: e.target.value } }))} placeholder="Nova opção (ex.: Bacon)" className={`${inp} flex-1`} onKeyDown={(e) => e.key === "Enter" && criarOpcao(g.id)} />
                  <input value={nd.precoDelta} onChange={(e) => setNovaOpcao((c) => ({ ...c, [g.id]: { ...nd, precoDelta: e.target.value.replace(/[^\d.,-]/g, "") } }))} placeholder="+ R$" className={`${inp} w-24`} onKeyDown={(e) => e.key === "Enter" && criarOpcao(g.id)} />
                  <button onClick={() => criarOpcao(g.id)} className="rounded-xl bg-gold-400 px-4 text-sm font-black text-blue-950 hover:bg-gold-300 transition">+</button>
                </div>
              </div>
            );
          })}

          {/* Novo grupo */}
          <div className="rounded-2xl border border-gold-400/25 bg-gold-400/[0.04] p-4">
            <p className="mb-2 text-xs font-black uppercase tracking-widest text-gold-300">+ Novo grupo</p>
            <div className="flex flex-wrap items-end gap-2">
              <div className="min-w-[140px] flex-1"><span className="mb-1 block text-[10px] font-bold uppercase tracking-widest text-slate-500">Nome</span><input value={novoGrupo.nome} onChange={(e) => setNovoGrupo({ ...novoGrupo, nome: e.target.value })} placeholder="Ex.: Tamanho, Ponto da carne…" className={inp} onKeyDown={(e) => e.key === "Enter" && criarGrupo()} /></div>
              <div className="w-16"><span className="mb-1 block text-[10px] font-bold uppercase tracking-widest text-slate-500">Mín</span><input inputMode="numeric" value={novoGrupo.minSelect} onChange={(e) => setNovoGrupo({ ...novoGrupo, minSelect: Number(e.target.value.replace(/\D/g, "")) || 0 })} className={inp} /></div>
              <div className="w-16"><span className="mb-1 block text-[10px] font-bold uppercase tracking-widest text-slate-500">Máx</span><input inputMode="numeric" value={novoGrupo.maxSelect} onChange={(e) => setNovoGrupo({ ...novoGrupo, maxSelect: Number(e.target.value.replace(/\D/g, "")) || 1 })} className={inp} /></div>
              <button onClick={() => setNovoGrupo({ ...novoGrupo, obrigatorio: !novoGrupo.obrigatorio })} className={`rounded-xl border px-3 py-2 text-xs font-black transition ${novoGrupo.obrigatorio ? "border-gold-400/60 bg-gold-400/10 text-gold-200" : "border-white/10 bg-white/[0.03] text-slate-400"}`}>{novoGrupo.obrigatorio ? "Obrigatório" : "Opcional"}</button>
              <button onClick={criarGrupo} className="rounded-xl bg-gold-400 px-4 py-2 text-sm font-black text-blue-950 hover:bg-gold-300 transition">Criar</button>
            </div>
          </div>
        </div>
        <div className="shrink-0 border-t border-white/10 px-6 py-4">
          <button onClick={onFechar} className="w-full rounded-2xl bg-gold-400 py-3.5 text-sm font-black text-blue-950 hover:bg-gold-300 transition">Concluído</button>
        </div>
      </div>
    </div>
  );
}

// ════════════════════════════════════════════════════════════
//  Admin — Setores de Cozinha (migration 041)
// ════════════════════════════════════════════════════════════
// ════════════════════════════════════════════════════════════
//  Admin — Setores de Cozinha (tab_setores_cozinha + produtos.setor_id)
//  Cadastro, gestão e controle das áreas de preparo da cozinha.
// ════════════════════════════════════════════════════════════
const svSet = { viewBox: "0 0 24 24", fill: "none", stroke: "currentColor", strokeWidth: 1.7, strokeLinecap: "round", strokeLinejoin: "round", "aria-hidden": true };
const IcoChef    = (p) => (<svg {...svSet} {...p}><path d="M7 21h10M6 11a4 4 0 0 1 1-7.5 4 4 0 0 1 10 0A4 4 0 0 1 18 11" /><path d="M6 11h12v6a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2v-6Z" /></svg>);
const IcoLayers  = (p) => (<svg {...svSet} {...p}><path d="m12 3 9 5-9 5-9-5 9-5Z" /><path d="m3 12 9 5 9-5M3 16l9 5 9-5" /></svg>);
const IcoBox     = (p) => (<svg {...svSet} {...p}><path d="M21 8 12 3 3 8v8l9 5 9-5V8Z" /><path d="m3 8 9 5 9-5M12 13v8" /></svg>);
const IcoFogo    = (p) => (<svg {...svSet} {...p}><path d="M12 3c1 3.5-2 4.5-2 7a2 2 0 0 0 4 0c0-.7-.2-1.2-.4-1.7C16 10 17 12.5 17 15a5 5 0 0 1-10 0c0-3.5 3-6 5-12Z" /></svg>);
const IcoBulb    = (p) => (<svg {...svSet} {...p}><path d="M9 18h6M10 21h4" /><path d="M12 3a6 6 0 0 0-3.5 10.9c.5.4.5.9.5 1.6h6c0-.7 0-1.2.5-1.6A6 6 0 0 0 12 3Z" /></svg>);
const IcoEditSet = (p) => (<svg {...svSet} {...p}><path d="M12 20h9" /><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4 12.5-12.5Z" /></svg>);
const IcoLinkSet = (p) => (<svg {...svSet} {...p}><path d="M10 13a5 5 0 0 0 7 0l2-2a5 5 0 0 0-7-7l-1 1" /><path d="M14 11a5 5 0 0 0-7 0l-2 2a5 5 0 0 0 7 7l1-1" /></svg>);
const IcoFiltro  = (p) => (<svg {...svSet} {...p}><path d="M3 5h18l-7 8v6l-4-2v-4L3 5Z" /></svg>);
const IcoPower   = (p) => (<svg {...svSet} {...p}><path d="M12 4v8" /><path d="M6.3 7.3a8 8 0 1 0 11.4 0" /></svg>);
const IcoFechaSet= (p) => (<svg {...svSet} {...p}><path d="m6 6 12 12M18 6 6 18" /></svg>);

function brl(v) { return `R$ ${(Number(v) || 0).toFixed(2).replace(".", ",")}`; }

function SetoresCozinhaAdmin({ setores = [], produtos = [], orders = [], api, vincularProduto = async () => {}, irParaCozinha = () => {} }) {
  // Formulário de novo setor
  const [nome, setNome] = useState("");
  const [descricao, setDescricao] = useState("");
  const [ativoNovo, setAtivoNovo] = useState(true);
  const [salvando, setSalvando] = useState(false);
  const [msg, setMsg] = useState(null); // { tipo, texto }
  const nomeRef = useRef(null);
  // Busca + modais
  const [busca, setBusca] = useState("");
  const [editando, setEditando] = useState(null);   // setor em edição (modal)
  const [confirmar, setConfirmar] = useState(null);  // setor a inativar (modal)
  const [vinculando, setVinculando] = useState(null);// setor p/ vincular produtos (modal)

  const aviso = (tipo, texto) => { setMsg({ tipo, texto }); setTimeout(() => setMsg(null), 3500); };

  // Mapa nome do produto → setorId (itens de pedido referenciam por nome)
  const setorPorNome = useMemo(() => { const m = {}; produtos.forEach((p) => { if (p.setorId) m[p.name] = p.setorId; }); return m; }, [produtos]);
  const contarProdutos = (sid) => produtos.filter((p) => p.setorId === sid).length;
  const pedidosEmPreparo = (sid) => orders.filter((o) => o.status === "preparing" && (o.items || []).some((it) => setorPorNome[it.name] === sid)).length;

  // Indicadores gerenciais
  const totalSetores = setores.length;
  const setoresAtivos = setores.filter((s) => s.ativo !== false).length;
  const pctAtivos = totalSetores ? Math.round((setoresAtivos / totalSetores) * 100) : 0;
  const produtosVinculados = produtos.filter((p) => p.setorId).length;
  const pedidosPreparoTotal = orders.filter((o) => o.status === "preparing").length;

  // Duplicidade (case-insensitive, por estabelecimento já filtrado em `setores`)
  const nomeDuplicado = (n, exceto = null) => setores.some((s) => s.id !== exceto && (s.nome || "").trim().toLowerCase() === n.trim().toLowerCase());

  const lista = [...setores].sort((a, b) => (a.ordem ?? 0) - (b.ordem ?? 0));
  const termo = busca.trim().toLowerCase();
  const filtrados = termo ? lista.filter((s) => `${s.nome} ${s.descricao || ""}`.toLowerCase().includes(termo)) : lista;

  async function criar() {
    const n = nome.trim();
    if (!n) { aviso("erro", "Informe o nome do setor."); nomeRef.current?.focus(); return; }
    if (nomeDuplicado(n)) { aviso("erro", "Já existe um setor com esse nome."); return; }
    setSalvando(true);
    try {
      await api?.add({ nome: n, descricao: descricao.trim(), ativo: ativoNovo, ordem: setores.length });
      setNome(""); setDescricao(""); setAtivoNovo(true);
      aviso("ok", "Setor criado com sucesso.");
    } catch { aviso("erro", "Não foi possível criar o setor."); }
    finally { setSalvando(false); }
  }
  function limpar() { setNome(""); setDescricao(""); setAtivoNovo(true); setMsg(null); }
  function focarNome() { nomeRef.current?.focus(); nomeRef.current?.scrollIntoView({ behavior: "smooth", block: "center" }); }

  async function salvarEdicao() {
    const n = (editando.nome || "").trim();
    if (!n) { aviso("erro", "O nome do setor não pode ficar vazio."); return; }
    if (nomeDuplicado(n, editando.id)) { aviso("erro", "Já existe um setor com esse nome."); return; }
    try {
      await api?.editar(editando.id, { nome: n, descricao: (editando.descricao || "").trim(), ativo: editando.ativo !== false, ordem: editando.ordem ?? 0 });
      setEditando(null); aviso("ok", "Setor atualizado.");
    } catch { aviso("erro", "Não foi possível salvar o setor."); }
  }
  async function alternarAtivo(s, ativo) {
    try { await api?.editar(s.id, { nome: s.nome, descricao: s.descricao || "", ativo, ordem: s.ordem ?? 0 }); aviso("ok", ativo ? "Setor reativado." : "Setor inativado."); }
    catch { aviso("erro", "Não foi possível alterar o status."); }
    setConfirmar(null);
  }

  const inp = "w-full rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-3 text-white outline-none focus:border-gold-400/60 transition placeholder:text-slate-600";

  return (
    <main className="space-y-5">
      {/* Toast de feedback */}
      {msg && (
        <div className={`fixed right-5 top-5 z-[60] rounded-2xl border px-4 py-3 text-sm font-bold shadow-xl ${msg.tipo === "ok" ? "border-emerald-400/30 bg-emerald-500/15 text-emerald-200" : "border-red-400/30 bg-red-500/15 text-red-200"}`}>{msg.texto}</div>
      )}

      {/* ── Cabeçalho ─────────────────────────────────────── */}
      <div className="relative overflow-hidden rounded-[2rem] border border-gold-400/25 bg-gradient-to-br from-white to-[#EDF3FB] p-6">
        <span className="pointer-events-none absolute -right-6 -top-6 text-gold-400/10 [&>svg]:h-44 [&>svg]:w-44"><IcoChef /></span>
        <div className="relative flex items-start gap-4">
          <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl border border-gold-400/40 bg-gold-400/10 text-gold-300 [&>svg]:h-6 [&>svg]:w-6"><IcoChef /></span>
          <div className="min-w-0">
            <h3 className="page-title text-xl font-bold tracking-tight text-white sm:text-2xl">Setores de Cozinha</h3>
            <p className="mt-1 max-w-2xl text-sm leading-6 text-slate-400">Organize o preparo dos pedidos por área e direcione cada produto para o setor responsável.</p>
          </div>
        </div>
      </div>

      {/* ── Cards de resumo ───────────────────────────────── */}
      <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
        {[
          { rotulo: "Total de setores", valor: totalSetores, sub: "Setores cadastrados", icone: <IcoLayers />, tom: "gold" },
          { rotulo: "Setores ativos", valor: setoresAtivos, sub: `${pctAtivos}% dos setores ativos`, icone: <IcoChef />, tom: "emerald" },
          { rotulo: "Produtos vinculados", valor: produtosVinculados, sub: "Em todos os setores", icone: <IcoBox />, tom: "blue" },
          { rotulo: "Pedidos em preparo", valor: pedidosPreparoTotal, sub: "Agora na cozinha", icone: <IcoFogo />, tom: "orange" },
        ].map((c) => (
          <div key={c.rotulo} className="rounded-2xl border border-white/[0.07] bg-white/[0.03] p-4 shadow-lg shadow-black/20">
            <div className="flex items-start justify-between gap-3">
              <p className="text-[10px] font-bold uppercase tracking-widest text-slate-500">{c.rotulo}</p>
              <span className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-full border [&>svg]:h-5 [&>svg]:w-5 ${c.tom === "emerald" ? "border-emerald-400/30 bg-emerald-500/10 text-emerald-300" : c.tom === "blue" ? "border-blue-400/30 bg-blue-500/10 text-blue-200" : c.tom === "orange" ? "border-orange-400/30 bg-orange-500/10 text-orange-300" : "border-gold-400/30 bg-gold-400/10 text-gold-300"}`}>{c.icone}</span>
            </div>
            <p className="page-title mt-2 text-2xl font-bold text-white">{c.valor}</p>
            <p className="mt-1 text-[11px] text-slate-500">{c.sub}</p>
          </div>
        ))}
      </div>

      <div className="grid gap-5 lg:grid-cols-[360px_1fr]">
        {/* ── Coluna esquerda: novo setor + dicas ─────────── */}
        <div className="space-y-4">
          <div className="rounded-[2rem] border border-white/10 bg-white/[0.04] p-5">
            <h4 className="page-title text-base font-bold text-white">Novo setor</h4>
            <p className="mt-0.5 text-xs text-slate-500">Crie um novo setor para organizar sua cozinha.</p>
            <div className="mt-4 space-y-3">
              <div>
                <label className="mb-1.5 block text-[11px] font-bold uppercase tracking-widest text-slate-500">Nome do setor</label>
                <input ref={nomeRef} value={nome} onChange={(e) => setNome(e.target.value)} placeholder="Ex.: Pizzaria, Chapa, Bar..." className={inp} onKeyDown={(e) => { if (e.key === "Enter") criar(); }} />
              </div>
              <div>
                <label className="mb-1.5 block text-[11px] font-bold uppercase tracking-widest text-slate-500">Descrição do setor</label>
                <textarea value={descricao} maxLength={120} onChange={(e) => setDescricao(e.target.value)} rows={3} placeholder="Descreva a função ou os tipos de preparo deste setor..." className={`${inp} resize-none`} />
                <p className="mt-1 text-right text-[10px] text-slate-600">{descricao.length}/120</p>
              </div>
              <div className="flex items-center justify-between rounded-2xl border border-white/10 bg-slate-950/40 px-4 py-3">
                <span className="text-sm font-semibold text-slate-300">Status</span>
                <button type="button" onClick={() => setAtivoNovo((v) => !v)} className={`relative h-6 w-11 rounded-full transition ${ativoNovo ? "bg-emerald-500" : "bg-slate-600"}`}>
                  <span className={`absolute top-0.5 h-5 w-5 rounded-full bg-white transition-all ${ativoNovo ? "left-[22px]" : "left-0.5"}`} />
                </button>
                <span className={`w-14 text-right text-xs font-bold ${ativoNovo ? "text-emerald-300" : "text-slate-400"}`}>{ativoNovo ? "Ativo" : "Inativo"}</span>
              </div>
              <div className="flex gap-2 pt-1">
                <PrimeButton onClick={criar} disabled={salvando} className="flex-1"><span className="text-lg leading-none">+</span> {salvando ? "Criando…" : "Criar setor"}</PrimeButton>
                <button onClick={limpar} className="rounded-2xl border border-white/10 bg-white/[0.06] px-4 py-3 text-sm font-bold text-slate-300 transition hover:bg-white/10">Limpar campos</button>
              </div>
            </div>
          </div>

          <div className="rounded-[2rem] border border-gold-400/25 bg-gold-400/[0.05] p-5">
            <div className="flex items-center gap-2 text-gold-300">
              <span className="[&>svg]:h-5 [&>svg]:w-5"><IcoBulb /></span>
              <h4 className="page-title text-sm font-bold">Dicas de uso</h4>
            </div>
            <p className="mt-2 text-xs leading-5 text-slate-300">Crie setores de acordo com as áreas da sua cozinha, como Bar, Pizzaria, Chapa, Cozinha e Sobremesas. Depois, vincule os produtos corretamente para otimizar o fluxo de preparo.</p>
            <p className="mt-2 text-xs leading-5 text-slate-400">Isso ajuda a organizar os pedidos e melhorar o tempo de produção.</p>
          </div>
        </div>

        {/* ── Coluna direita: listagem ────────────────────── */}
        <div className="rounded-[2rem] border border-white/10 bg-white/[0.04] p-5">
          <div className="flex flex-col gap-1 sm:flex-row sm:items-center sm:justify-between">
            <div>
              <h4 className="page-title text-base font-bold text-white">Setores cadastrados</h4>
              <p className="text-xs text-slate-500">Gerencie os setores da sua cozinha.</p>
            </div>
            <span className="text-xs font-semibold text-slate-400">{filtrados.length} de {totalSetores} setor(es)</span>
          </div>

          <div className="relative mt-4">
            <span className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-slate-500"><IconBusca /></span>
            <input value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar setor..." className={`${inp} pl-11`} />
          </div>

          {lista.length === 0 ? (
            <div className="mt-4 rounded-2xl border border-dashed border-white/15 bg-white/[0.02] py-12 text-center">
              <span className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl border border-gold-400/30 bg-gold-400/10 text-gold-300 [&>svg]:h-7 [&>svg]:w-7"><IcoChef /></span>
              <p className="mt-3 font-bold text-white">Nenhum setor cadastrado ainda.</p>
              <p className="mx-auto mt-1 max-w-md text-sm text-slate-500">Crie setores para organizar o preparo dos pedidos e facilitar o controle da cozinha.</p>
              <p className="mt-1 text-xs text-slate-600">Exemplos: Bar, Pizzaria, Chapa, Cozinha, Sobremesas e Bebidas.</p>
              <button onClick={focarNome} className="mt-4 rounded-2xl bg-gold-400 px-5 py-2.5 text-sm font-bold text-blue-950 transition hover:bg-gold-300">Criar primeiro setor</button>
            </div>
          ) : filtrados.length === 0 ? (
            <p className="mt-6 py-8 text-center text-sm text-slate-500">Nenhum setor encontrado para "{busca}".</p>
          ) : (
            <div className="mt-4 space-y-3">
              {filtrados.map((s) => {
                const ativo = s.ativo !== false;
                return (
                  <div key={s.id} className={`rounded-2xl border p-4 transition ${ativo ? "border-white/10 bg-slate-950/40 hover:bg-slate-950/60" : "border-white/10 bg-white/[0.02] opacity-75"}`}>
                    <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
                      <div className="flex min-w-0 items-start gap-3">
                        <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl border border-gold-400/25 bg-gold-400/10 text-gold-300 [&>svg]:h-5 [&>svg]:w-5"><IcoChef /></span>
                        <div className="min-w-0">
                          <div className="flex items-center gap-2">
                            <p className="page-title truncate text-base font-bold text-white">{s.nome}</p>
                            <span className={`inline-flex shrink-0 items-center gap-1 rounded-full border px-2 py-0.5 text-[10px] font-bold ${ativo ? "border-emerald-400/30 bg-emerald-500/10 text-emerald-300" : "border-white/15 bg-white/[0.06] text-slate-400"}`}>{ativo ? "Ativo" : "Inativo"}</span>
                          </div>
                          <p className="mt-0.5 line-clamp-2 text-xs text-slate-400">{s.descricao || "Sem descrição."}</p>
                          <div className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-[11px] text-slate-500">
                            <span><b className="text-slate-300">{contarProdutos(s.id)}</b> produto(s) vinculado(s)</span>
                            <span><b className="text-orange-300">{pedidosEmPreparo(s.id)}</b> pedido(s) em preparo</span>
                          </div>
                        </div>
                      </div>
                      <div className="flex shrink-0 flex-wrap gap-1.5">
                        <button onClick={() => setEditando({ ...s })} className="inline-flex items-center gap-1.5 rounded-xl border border-white/10 bg-white/[0.06] px-3 py-1.5 text-xs font-bold text-slate-200 transition hover:bg-white/10 [&>svg]:h-3.5 [&>svg]:w-3.5"><IcoEditSet /> Editar</button>
                        <button onClick={() => setVinculando(s)} className="inline-flex items-center gap-1.5 rounded-xl border border-white/10 bg-white/[0.06] px-3 py-1.5 text-xs font-bold text-slate-200 transition hover:bg-white/10 [&>svg]:h-3.5 [&>svg]:w-3.5"><IcoLinkSet /> Vincular produtos</button>
                        <button onClick={() => irParaCozinha(s.id)} className="inline-flex items-center gap-1.5 rounded-xl border border-white/10 bg-white/[0.06] px-3 py-1.5 text-xs font-bold text-slate-200 transition hover:bg-white/10 [&>svg]:h-3.5 [&>svg]:w-3.5"><IcoFiltro /> Filtrar cozinha</button>
                        {ativo
                          ? <button onClick={() => setConfirmar(s)} className="inline-flex items-center gap-1.5 rounded-xl border border-red-400/25 bg-red-500/10 px-3 py-1.5 text-xs font-bold text-red-300 transition hover:bg-red-500/20 [&>svg]:h-3.5 [&>svg]:w-3.5"><IcoPower /> Inativar</button>
                          : <button onClick={() => alternarAtivo(s, true)} className="inline-flex items-center gap-1.5 rounded-xl border border-emerald-400/25 bg-emerald-500/10 px-3 py-1.5 text-xs font-bold text-emerald-300 transition hover:bg-emerald-500/20 [&>svg]:h-3.5 [&>svg]:w-3.5"><IcoPower /> Ativar</button>}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>

      {/* ── Modal: editar setor ───────────────────────────── */}
      {editando && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <button aria-label="Fechar" onClick={() => setEditando(null)} className="absolute inset-0 bg-black/60 backdrop-blur-sm" />
          <div className="relative w-full max-w-md rounded-[2rem] border border-white/10 bg-blue-950 p-6 shadow-2xl">
            <div className="flex items-center justify-between">
              <h4 className="page-title text-lg font-bold text-white">Editar setor</h4>
              <button onClick={() => setEditando(null)} className="flex h-9 w-9 items-center justify-center rounded-full border border-white/10 bg-white/[0.06] text-slate-300 hover:bg-white/10 [&>svg]:h-4 [&>svg]:w-4"><IcoFechaSet /></button>
            </div>
            <div className="mt-4 space-y-3">
              <div>
                <label className="mb-1.5 block text-[11px] font-bold uppercase tracking-widest text-slate-500">Nome do setor</label>
                <input value={editando.nome} onChange={(e) => setEditando({ ...editando, nome: e.target.value })} className={inp} autoFocus />
              </div>
              <div>
                <label className="mb-1.5 block text-[11px] font-bold uppercase tracking-widest text-slate-500">Descrição</label>
                <textarea value={editando.descricao || ""} maxLength={120} rows={3} onChange={(e) => setEditando({ ...editando, descricao: e.target.value })} className={`${inp} resize-none`} />
              </div>
              <div className="flex items-center justify-between rounded-2xl border border-white/10 bg-slate-950/40 px-4 py-3">
                <span className="text-sm font-semibold text-slate-300">Status</span>
                <button type="button" onClick={() => setEditando({ ...editando, ativo: editando.ativo === false })} className={`relative h-6 w-11 rounded-full transition ${editando.ativo !== false ? "bg-emerald-500" : "bg-slate-600"}`}>
                  <span className={`absolute top-0.5 h-5 w-5 rounded-full bg-white transition-all ${editando.ativo !== false ? "left-[22px]" : "left-0.5"}`} />
                </button>
                <span className={`w-14 text-right text-xs font-bold ${editando.ativo !== false ? "text-emerald-300" : "text-slate-400"}`}>{editando.ativo !== false ? "Ativo" : "Inativo"}</span>
              </div>
            </div>
            <div className="mt-5 flex gap-2">
              <button onClick={salvarEdicao} className="flex-1 rounded-2xl bg-gold-400 px-4 py-2.5 text-sm font-bold text-blue-950 transition hover:bg-gold-300">Salvar alterações</button>
              <button onClick={() => setEditando(null)} className="rounded-2xl border border-white/10 bg-white/[0.06] px-4 py-2.5 text-sm font-bold text-slate-300 transition hover:bg-white/10">Cancelar</button>
            </div>
          </div>
        </div>
      )}

      {/* ── Modal: confirmar inativação ───────────────────── */}
      {confirmar && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <button aria-label="Fechar" onClick={() => setConfirmar(null)} className="absolute inset-0 bg-black/60 backdrop-blur-sm" />
          <div className="relative w-full max-w-md rounded-[2rem] border border-white/10 bg-blue-950 p-6 shadow-2xl">
            <h4 className="page-title text-lg font-bold text-white">Deseja realmente inativar este setor?</h4>
            <p className="mt-2 text-sm leading-6 text-slate-400">Setores inativos não aparecerão como opção principal no painel da cozinha, mas permanecerão no histórico do sistema.</p>
            <p className="mt-3 rounded-xl border border-white/10 bg-white/[0.04] px-3 py-2 text-sm font-bold text-white">{confirmar.nome}</p>
            <div className="mt-5 flex gap-2">
              <button onClick={() => alternarAtivo(confirmar, false)} className="flex-1 rounded-2xl border border-red-400/30 bg-red-500/15 px-4 py-2.5 text-sm font-bold text-red-200 transition hover:bg-red-500/25">Confirmar inativação</button>
              <button onClick={() => setConfirmar(null)} className="rounded-2xl border border-white/10 bg-white/[0.06] px-4 py-2.5 text-sm font-bold text-slate-300 transition hover:bg-white/10">Cancelar</button>
            </div>
          </div>
        </div>
      )}

      {/* ── Modal: vincular produtos ──────────────────────── */}
      {vinculando && (
        <VincularProdutosModal setor={vinculando} produtos={produtos} setores={setores} onFechar={() => setVinculando(null)}
          onSalvar={async (alteracoes) => {
            try { for (const [pid, sid] of alteracoes) await vincularProduto(pid, sid); aviso("ok", "Vínculos atualizados."); }
            catch { aviso("erro", "Não foi possível salvar os vínculos."); }
            setVinculando(null);
          }} />
      )}
    </main>
  );
}

// Modal de vínculo produto → setor de cozinha
function VincularProdutosModal({ setor, produtos = [], setores = [], onFechar, onSalvar }) {
  useScrollLock(); // trava a rolagem do fundo enquanto o modal está aberto
  const [busca, setBusca] = useState("");
  const [sel, setSel] = useState(() => new Set(produtos.filter((p) => p.setorId === setor.id).map((p) => p.id)));
  const [salvando, setSalvando] = useState(false);
  const termo = busca.trim().toLowerCase();
  const nomeSetor = (sid) => setores.find((s) => s.id === sid)?.nome || "Outro setor";
  // Regra: 1 produto = 1 setor. Mostra só produtos sem vínculo (ou já deste setor);
  // os que já pertencem a outro setor ficam fora da lista de seleção.
  const disponiveis = produtos.filter((p) => !p.setorId || p.setorId === setor.id);
  const lista = termo ? disponiveis.filter((p) => `${p.name} ${p.category || ""}`.toLowerCase().includes(termo)) : disponiveis;
  const toggle = (id) => setSel((s) => { const n = new Set(s); n.has(id) ? n.delete(id) : n.add(id); return n; });
  async function salvar() {
    // Calcula só os produtos que mudaram de vínculo em relação a ESTE setor
    const alteracoes = [];
    produtos.forEach((p) => {
      const marcado = sel.has(p.id);
      // Validação interna: nunca revincular um produto já preso a OUTRO setor
      if (marcado && p.setorId && p.setorId !== setor.id) return;
      if (marcado && p.setorId !== setor.id) alteracoes.push([p.id, setor.id]);
      else if (!marcado && p.setorId === setor.id) alteracoes.push([p.id, null]);
    });
    setSalvando(true);
    await onSalvar(alteracoes);
    setSalvando(false);
  }
  const inp = "w-full rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-3 text-white outline-none focus:border-gold-400/60";
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <button aria-label="Fechar" onClick={onFechar} className="absolute inset-0 bg-black/60 backdrop-blur-sm" />
      <div className="relative flex max-h-[85vh] w-full max-w-lg flex-col rounded-[2rem] border border-white/10 bg-blue-950 shadow-2xl">
        <div className="border-b border-white/10 px-6 py-4">
          <div className="flex items-center justify-between">
            <h4 className="page-title text-lg font-bold text-white">Vincular produtos ao setor</h4>
            <button onClick={onFechar} className="flex h-9 w-9 items-center justify-center rounded-full border border-white/10 bg-white/[0.06] text-slate-300 hover:bg-white/10 [&>svg]:h-4 [&>svg]:w-4"><IcoFechaSet /></button>
          </div>
          <p className="mt-0.5 text-xs text-slate-500">Selecione os produtos que devem ser preparados em <b className="text-gold-300">{setor.nome}</b>.</p>
          <div className="relative mt-3">
            <span className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-slate-500"><IconBusca /></span>
            <input value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar produto..." className={`${inp} pl-11`} />
          </div>
        </div>
        <div className="flex-1 overflow-y-auto px-6 py-3">
          {lista.length === 0 ? (
            <p className="py-8 text-center text-sm text-slate-500">{termo ? "Nenhum produto encontrado." : "Nenhum produto disponível — os demais já estão vinculados a outros setores."}</p>
          ) : lista.map((p) => {
            const marcado = sel.has(p.id);
            const vinculado = p.setorId === setor.id;
            return (
              <button key={p.id} onClick={() => toggle(p.id)} className={`flex w-full items-center gap-3 border-b border-white/5 py-2.5 text-left transition hover:bg-white/[0.03]`}>
                <span className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-md border ${marcado ? "border-gold-400 bg-gold-400 text-blue-950" : "border-white/20"}`}>{marcado && <span className="text-[11px] font-black">✓</span>}</span>
                <span className="min-w-0 flex-1">
                  <span className="block truncate text-sm font-semibold text-white">{p.name}</span>
                  <span className="block truncate text-[11px] text-slate-500">{p.category || "Sem categoria"} · {brl(p.price)}</span>
                </span>
                <span className="flex shrink-0 flex-col items-end gap-1">
                  {vinculado && <span className="rounded-full bg-gold-400/15 px-2 py-0.5 text-[10px] font-bold text-gold-300">{nomeSetor(p.setorId)}</span>}
                  <span className={`rounded-full px-2 py-0.5 text-[10px] font-bold ${p.active !== false ? "bg-emerald-500/10 text-emerald-300" : "bg-white/[0.06] text-slate-400"}`}>{p.active !== false ? "Ativo" : "Inativo"}</span>
                </span>
              </button>
            );
          })}
        </div>
        <div className="flex items-center justify-between gap-2 border-t border-white/10 px-6 py-4">
          <span className="text-xs text-slate-400"><b className="text-white">{sel.size}</b> selecionado(s)</span>
          <div className="flex gap-2">
            <button onClick={onFechar} className="rounded-2xl border border-white/10 bg-white/[0.06] px-4 py-2.5 text-sm font-bold text-slate-300 transition hover:bg-white/10">Cancelar</button>
            <button onClick={salvar} disabled={salvando} className="rounded-2xl bg-gold-400 px-5 py-2.5 text-sm font-bold text-blue-950 transition hover:bg-gold-300 disabled:opacity-50">{salvando ? "Salvando…" : "Salvar vínculos"}</button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ════════════════════════════════════════════════════════════
//  Admin — Fechamento de Caixa (migration 042)
// ════════════════════════════════════════════════════════════
function CaixaSessaoAdmin({ caixaAberto, caixas = [], api }) {
  const [movs, setMovs] = useState([]);
  const [abrindo, setAbrindo] = useState("");      // valor de abertura (string moeda)
  const [opTipo, setOpTipo] = useState(null);      // 'suprimento' | 'sangria'
  const [opValor, setOpValor] = useState("");
  const [opDesc, setOpDesc] = useState("");
  const [fechando, setFechando] = useState(false);
  const [contado, setContado] = useState("");
  const num = (s) => Number(String(s).replace(/\./g, "").replace(",", ".").replace(/[^\d.]/g, "")) || 0;

  // Carrega as movimentações do caixa aberto
  useEffect(() => {
    let vivo = true;
    if (caixaAberto && api?.fetchMovimentos) { api.fetchMovimentos(caixaAberto.id).then((m) => { if (vivo) setMovs(m || []); }).catch(() => {}); }
    else setMovs([]);
    return () => { vivo = false; };
  }, [caixaAberto?.id]);

  const soma = (tipo) => movs.filter((m) => m.tipo === tipo).reduce((s, m) => s + m.valor, 0);
  const suprimentos = soma("suprimento");
  const sangrias = soma("sangria");
  const vendas = soma("venda");
  const formaDe = (m) => (m.descricao || "").replace(/^Venda\s*/i, "").split(" · ")[0] || "—";
  const vendasPorForma = (() => { const r = {}; movs.filter((m) => m.tipo === "venda").forEach((m) => { const f = formaDe(m); r[f] = (r[f] || 0) + m.valor; }); return r; })();
  const vendasDinheiro = movs.filter((m) => m.tipo === "venda" && /dinheiro/i.test(formaDe(m))).reduce((s, m) => s + m.valor, 0);
  const abertura = caixaAberto?.valorAbertura || 0;
  const esperadoDinheiro = abertura + suprimentos - sangrias + vendasDinheiro;
  const fechados = caixas.filter((c) => c.status === "fechado");

  async function recarregar() { if (caixaAberto && api?.fetchMovimentos) setMovs(await api.fetchMovimentos(caixaAberto.id).catch(() => [])); }
  async function confirmarOp() {
    const ok = await api.movimentar(opTipo, num(opValor), opDesc);
    if (ok) { setOpTipo(null); setOpValor(""); setOpDesc(""); await recarregar(); }
  }
  async function confirmarFechamento() {
    const c = num(contado);
    const ok = await api.fechar(c, esperadoDinheiro, c - esperadoDinheiro);
    if (ok) { setFechando(false); setContado(""); }
  }

  return (
    <main className="space-y-5">
      <PageHeader icone={<IconPagamento />} titulo="Fechamento de Caixa" descricao="Abra o caixa, registre suprimentos e sangrias, e feche com a conferência de valores." />

      {!caixaAberto ? (
        <div className="mx-auto max-w-md rounded-[2rem] border border-gold-400/30 bg-gold-400/[0.05] p-6 text-center">
          <span className="text-4xl">🔓</span>
          <h3 className="page-title mt-2 text-lg font-bold text-white">Caixa fechado</h3>
          <p className="mt-1 text-sm text-slate-400">Informe o valor inicial (fundo de troco) para abrir o caixa.</p>
          <input inputMode="decimal" value={abrindo} onChange={(e) => setAbrindo(e.target.value)} placeholder="R$ 0,00" className="mt-4 w-full rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-3 text-center text-lg font-black text-white outline-none focus:border-gold-400/60" />
          <button onClick={() => api.abrir(num(abrindo))} className="font-display mt-4 w-full rounded-2xl bg-gold-400 py-3.5 text-sm font-bold text-blue-950 hover:bg-gold-300 transition active:scale-95 shadow-lg shadow-gold-900/30">Abrir caixa</button>
        </div>
      ) : (
        <>
          <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
            <CardMetrica titulo="Aberto em" valor={caixaAberto.abertoEmISO ? new Date(caixaAberto.abertoEmISO).toLocaleString("pt-BR", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" }) : "—"} sub="sessão atual" cor="text-white" />
            <CardMetrica titulo="Total vendido" valor={formatCurrency(vendas)} sub={`${movs.filter((m) => m.tipo === "venda").length} venda(s)`} cor="text-emerald-400" />
            <CardMetrica titulo="Suprimentos − Sangrias" valor={formatCurrency(suprimentos - sangrias)} sub={`+${formatCurrency(suprimentos)} / −${formatCurrency(sangrias)}`} cor="text-white" />
            <CardMetrica titulo="Esperado em dinheiro" valor={formatCurrency(esperadoDinheiro)} sub="abertura + dinheiro − sangria" cor="text-gold-400" />
          </div>

          <div className="flex flex-wrap gap-2">
            <button onClick={() => { setOpTipo("suprimento"); setOpValor(""); setOpDesc(""); }} className="rounded-2xl border border-emerald-400/30 bg-emerald-500/10 px-4 py-2.5 text-sm font-black text-emerald-300 hover:bg-emerald-500/20 transition">+ Suprimento</button>
            <button onClick={() => { setOpTipo("sangria"); setOpValor(""); setOpDesc(""); }} className="rounded-2xl border border-amber-400/30 bg-amber-500/10 px-4 py-2.5 text-sm font-black text-amber-300 hover:bg-amber-500/20 transition">− Sangria</button>
            <button onClick={() => setFechando(true)} className="ml-auto rounded-2xl bg-gold-400 px-5 py-2.5 text-sm font-black text-blue-950 hover:bg-gold-300 transition active:scale-95">🔒 Fechar caixa</button>
          </div>

          {/* Vendas por forma de pagamento */}
          <div className="rounded-[2rem] border border-white/10 bg-white/[0.04] p-5">
            <h3 className="page-title text-sm font-bold uppercase tracking-wider text-white">Vendas por forma de pagamento</h3>
            <div className="mt-3 grid gap-2 sm:grid-cols-2">
              {Object.keys(vendasPorForma).length === 0 && <p className="text-sm text-slate-500">Nenhuma venda registrada nesta sessão.</p>}
              {Object.entries(vendasPorForma).map(([f, v]) => (
                <div key={f} className="flex items-center justify-between rounded-xl border border-white/10 bg-white/[0.03] px-4 py-2.5">
                  <span className="text-sm font-bold text-slate-200">{f}</span><span className="font-black text-gold-400">{formatCurrency(v)}</span>
                </div>
              ))}
            </div>
          </div>

          {/* Movimentações */}
          {movs.length > 0 && (
            <div className="overflow-hidden rounded-[2rem] border border-white/10 bg-white/[0.04]">
              <div className="border-b border-gold-400/15 px-5 py-3"><h3 className="page-title text-sm font-bold uppercase tracking-wider text-white">Movimentações</h3></div>
              <div className="max-h-64 overflow-y-auto">
                {[...movs].reverse().map((m) => (
                  <div key={m.id} className="flex items-center justify-between gap-2 border-t border-white/5 px-5 py-2.5 text-sm">
                    <span className={`rounded-full px-2 py-0.5 text-[10px] font-black uppercase tracking-wider ${m.tipo === "venda" ? "bg-emerald-500/15 text-emerald-300" : m.tipo === "suprimento" ? "bg-blue-500/15 text-blue-300" : m.tipo === "sangria" ? "bg-amber-500/15 text-amber-300" : "bg-white/[0.06] text-slate-400"}`}>{m.tipo}</span>
                    <span className="min-w-0 flex-1 truncate text-slate-400">{m.descricao || "—"}</span>
                    <span className={`font-black ${m.tipo === "sangria" ? "text-amber-300" : "text-white"}`}>{m.tipo === "sangria" ? "−" : "+"}{formatCurrency(m.valor)}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </>
      )}

      {/* Histórico de caixas fechados */}
      {fechados.length > 0 && (
        <div className="overflow-hidden rounded-[2rem] border border-white/10 bg-white/[0.04]">
          <div className="border-b border-gold-400/15 px-5 py-3"><h3 className="page-title text-sm font-bold uppercase tracking-wider text-white">Caixas fechados</h3></div>
          <div className="hidden grid-cols-[1.4fr_1fr_1fr_1fr] bg-white/[0.03] px-5 py-2 text-[11px] font-bold uppercase tracking-widest text-gold-400/70 sm:grid"><span>Período</span><span className="text-right">Esperado</span><span className="text-right">Contado</span><span className="text-right">Diferença</span></div>
          {fechados.map((c) => (
            <div key={c.id} className="grid grid-cols-2 gap-1 border-t border-white/5 px-5 py-3 text-sm sm:grid-cols-[1.4fr_1fr_1fr_1fr]">
              <span className="text-slate-300">{c.abertoEmISO ? new Date(c.abertoEmISO).toLocaleDateString("pt-BR") : "—"} {c.fechadoEmISO ? `· fechou ${new Date(c.fechadoEmISO).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" })}` : ""}</span>
              <span className="text-right font-mono text-slate-300">{c.valorEsperado != null ? formatCurrency(c.valorEsperado) : "—"}</span>
              <span className="text-right font-mono text-slate-300">{c.valorFechamento != null ? formatCurrency(c.valorFechamento) : "—"}</span>
              <span className={`text-right font-mono font-black ${(c.diferenca ?? 0) < 0 ? "text-red-400" : (c.diferenca ?? 0) > 0 ? "text-amber-300" : "text-emerald-400"}`}>{c.diferenca != null ? formatCurrency(c.diferenca) : "—"}</span>
            </div>
          ))}
        </div>
      )}

      {/* Modal suprimento/sangria */}
      {opTipo && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm" onClick={() => setOpTipo(null)}>
          <div onClick={(e) => e.stopPropagation()} className="w-full max-w-sm rounded-[2rem] border border-white/10 bg-slate-900 p-6 shadow-2xl">
            <h3 className="page-title text-lg font-bold text-white">{opTipo === "suprimento" ? "Suprimento (entrada)" : "Sangria (retirada)"}</h3>
            <input autoFocus inputMode="decimal" value={opValor} onChange={(e) => setOpValor(e.target.value)} placeholder="R$ 0,00" className="mt-4 w-full rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-3 text-center text-lg font-black text-white outline-none focus:border-gold-400/60" />
            <input value={opDesc} onChange={(e) => setOpDesc(e.target.value)} placeholder="Descrição (opcional)" className="mt-2 w-full rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-3 text-sm text-white outline-none focus:border-gold-400/60" />
            <div className="mt-4 flex gap-3">
              <button onClick={() => setOpTipo(null)} className="flex-1 rounded-2xl border border-white/10 bg-white/[0.06] py-3 text-sm font-black text-slate-300 hover:bg-white/10">Cancelar</button>
              <button onClick={confirmarOp} className="flex-1 rounded-2xl bg-gold-400 py-3 text-sm font-black text-blue-950 hover:bg-gold-300 transition">Registrar</button>
            </div>
          </div>
        </div>
      )}

      {/* Modal fechar caixa */}
      {fechando && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm" onClick={() => setFechando(false)}>
          <div onClick={(e) => e.stopPropagation()} className="w-full max-w-sm rounded-[2rem] border border-gold-400/30 bg-slate-900 p-6 shadow-2xl">
            <h3 className="page-title text-lg font-bold text-white">Fechar caixa</h3>
            <div className="mt-3 space-y-1 text-sm">
              <div className="flex justify-between text-slate-400"><span>Esperado em dinheiro</span><span className="font-black text-white">{formatCurrency(esperadoDinheiro)}</span></div>
            </div>
            <label className="mt-4 block text-xs font-bold uppercase tracking-widest text-slate-500">Valor contado (dinheiro na gaveta)</label>
            <input autoFocus inputMode="decimal" value={contado} onChange={(e) => setContado(e.target.value)} placeholder="R$ 0,00" className="mt-1 w-full rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-3 text-center text-lg font-black text-white outline-none focus:border-gold-400/60" />
            {contado !== "" && (
              <p className={`mt-2 text-center text-sm font-black ${(num(contado) - esperadoDinheiro) < 0 ? "text-red-400" : (num(contado) - esperadoDinheiro) > 0 ? "text-amber-300" : "text-emerald-400"}`}>Diferença: {formatCurrency(num(contado) - esperadoDinheiro)}</p>
            )}
            <div className="mt-4 flex gap-3">
              <button onClick={() => setFechando(false)} className="flex-1 rounded-2xl border border-white/10 bg-white/[0.06] py-3 text-sm font-black text-slate-300 hover:bg-white/10">Cancelar</button>
              <button onClick={confirmarFechamento} className="flex-1 rounded-2xl bg-gold-400 py-3 text-sm font-black text-blue-950 hover:bg-gold-300 transition">Confirmar fechamento</button>
            </div>
          </div>
        </div>
      )}
    </main>
  );
}

// ════════════════════════════════════════════════════════════
//  Fidelidade — painel do cliente (no CRM) + tela admin
// ════════════════════════════════════════════════════════════
function FidelidadePainelCliente({ cliente, pontos, recompensas = [], lancarPontos }) {
  const [valor, setValor] = useState("");
  const n = Number(String(valor).replace(/\D/g, "")) || 0;
  return (
    <div className="rounded-2xl border border-gold-400/25 bg-gold-400/[0.05] p-3">
      <div className="flex flex-wrap items-center gap-2">
        <span className="flex items-center gap-1.5 text-sm font-black text-gold-300">⭐ {pontos} ponto(s)</span>
        <div className="ml-auto flex items-center gap-1.5">
          <input inputMode="numeric" value={valor} onChange={(e) => setValor(e.target.value.replace(/\D/g, ""))} placeholder="qtd" className="w-16 rounded-lg border border-white/10 bg-slate-950/70 px-2 py-1.5 text-center text-xs text-white outline-none focus:border-gold-400/60" />
          <button onClick={() => { if (n > 0) { lancarPontos(cliente.id, n, "adjust", "Ajuste manual"); setValor(""); } }} className="rounded-lg border border-emerald-400/30 bg-emerald-500/10 px-2.5 py-1.5 text-xs font-black text-emerald-300 hover:bg-emerald-500/20">+ Lançar</button>
          <button onClick={() => { if (n > 0 && n <= pontos) { lancarPontos(cliente.id, -n, "redeem", "Resgate manual"); setValor(""); } }} disabled={n <= 0 || n > pontos} className="rounded-lg border border-amber-400/30 bg-amber-500/10 px-2.5 py-1.5 text-xs font-black text-amber-300 hover:bg-amber-500/20 disabled:opacity-40">− Resgatar</button>
        </div>
      </div>
      {recompensas.filter((r) => r.ativo !== false).length > 0 && (
        <div className="mt-2 flex flex-wrap gap-1.5">
          {recompensas.filter((r) => r.ativo !== false).map((r) => {
            const pode = pontos >= r.pontosNecessarios;
            return (
              <button key={r.id} disabled={!pode} onClick={() => lancarPontos(cliente.id, -r.pontosNecessarios, "redeem", `Resgate: ${r.nome}`)}
                className={`rounded-full border px-3 py-1 text-[11px] font-black transition ${pode ? "border-gold-400/50 bg-gold-400/10 text-gold-200 hover:bg-gold-400/20" : "border-white/10 bg-white/[0.03] text-slate-600"}`}>
                🎁 {r.nome} · {r.pontosNecessarios}pts
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ── Ícones inline (tema claro) para o Programa de Fidelidade ──
const FidIco = {
  pessoas: (p) => <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" {...p}><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" /><circle cx="9" cy="7" r="4" /><path d="M23 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75" /></svg>,
  estrela: (p) => <svg viewBox="0 0 24 24" fill="currentColor" {...p}><path d="M12 2l2.9 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77 5.82 21l1.18-6.88-5-4.87 7.1-1.01z" /></svg>,
  presente: (p) => <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" {...p}><rect x="3" y="8" width="18" height="4" rx="1" /><path d="M12 8v13M19 12v7a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2v-7" /><path d="M7.5 8a2.5 2.5 0 0 1 0-5C11 3 12 8 12 8s1-5 4.5-5a2.5 2.5 0 0 1 0 5" /></svg>,
  dinheiro: (p) => <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" {...p}><circle cx="12" cy="12" r="9" /><path d="M14.5 9a2.5 2 0 0 0-2.5-1.5c-1.4 0-2.5.7-2.5 1.8 0 2.4 5 1.2 5 3.6 0 1.1-1.1 1.8-2.5 1.8A2.5 2 0 0 1 9.5 15M12 6.5v11" /></svg>,
  config: (p) => <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" {...p}><circle cx="12" cy="12" r="3" /><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z" /></svg>,
  info: (p) => <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" {...p}><circle cx="12" cy="12" r="10" /><path d="M12 16v-4M12 8h.01" /></svg>,
  download: (p) => <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" {...p}><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M7 10l5 5 5-5M12 15V3" /></svg>,
  lapis: (p) => <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" {...p}><path d="M12 20h9M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4z" /></svg>,
  lixo: (p) => <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" {...p}><path d="M3 6h18M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2m3 0v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6" /></svg>,
  mais: (p) => <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" {...p}><path d="M12 5v14M5 12h14" /></svg>,
  check: (p) => <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" {...p}><path d="M20 6L9 17l-5-5" /></svg>,
  seta: (p) => <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" {...p}><path d="M5 12h14M12 5l7 7-7 7" /></svg>,
};
const fmtInt = (n) => Number(n || 0).toLocaleString("pt-BR");
// Variação mês a mês de uma métrica (soma no mês atual vs. anterior)
function deltaMesFid(atual, anterior) {
  if (anterior > 0) { const pct = Math.round(((atual - anterior) / anterior) * 100); return { txt: `${pct >= 0 ? "+" : ""}${pct}% este mês`, cor: pct >= 0 ? "#3F6021" : "#B91C1C" }; }
  if (atual > 0) return { txt: `${fmtInt(atual)} este mês`, cor: "#3F6021" };
  return { txt: "sem movimento este mês", cor: "var(--pp-text-muted)" };
}

function FidelidadeAdmin({ regra, recompensas = [], transacoes = [], clientes = [], orders = [], api, onVerClientes }) {
  const [valorPorPonto, setValorPorPonto] = useState(regra?.valorPorPonto ?? 1);
  const [pontosPorReal, setPontosPorReal] = useState(regra?.pontosPorReal ?? 100); // resgate: pts que valem R$1
  const [configAberto, setConfigAberto] = useState(false);
  const [modalRec, setModalRec] = useState(null); // null | {} (nova) | recompensa (editar)
  const [confirmarExcluir, setConfirmarExcluir] = useState(null);
  const [verTodasRec, setVerTodasRec] = useState(false);
  const regraRef = useRef(null);
  useEffect(() => { setValorPorPonto(regra?.valorPorPonto ?? 1); setPontosPorReal(regra?.pontosPorReal ?? 100); }, [regra?.id]);

  const programaAtivo = regra?.ativo !== false && !!regra;
  const vpp = Number(String(regra?.valorPorPonto ?? valorPorPonto).replace(",", ".")) || 1;
  // Valores DIGITADOS ao vivo (antes de salvar) — alimentam os textos-exemplo e a
  // descrição de funcionamento, que atualizam a cada tecla para facilitar a leitura.
  const vppLive = Number(String(valorPorPonto).replace(",", ".")) || 1;   // R$ para ganhar 1 ponto
  const pprLive = Number(String(pontosPorReal).replace(",", ".")) || 100;  // pts que valem R$ 1,00
  const ptsEmCem = Math.floor(100 / vppLive);                              // pontos numa compra de R$ 100
  const creditoCem = ptsEmCem / pprLive;                                   // R$ que esses pontos resgatam

  // ── Métricas 100% reais ──
  const saldo = useMemo(() => { const m = {}; transacoes.forEach((t) => { if (t.clienteId != null) m[t.clienteId] = (m[t.clienteId] || 0) + t.pontos; }); return m; }, [transacoes]);
  const now = new Date();
  const mesAtual = (iso) => { const d = new Date(iso); return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear(); };
  const mesAnterior = (iso) => { const d = new Date(iso); const p = new Date(now.getFullYear(), now.getMonth() - 1, 1); return d.getMonth() === p.getMonth() && d.getFullYear() === p.getFullYear(); };

  const met = useMemo(() => {
    const earn = transacoes.filter((t) => t.tipo === "earn");
    const redeem = transacoes.filter((t) => t.tipo === "redeem");
    const somaPts = (arr, filtro) => arr.reduce((s, t) => s + (filtro && !filtro(t.criadoEmISO) ? 0 : (Number(t.pontos) || 0)), 0);
    const emitidos = somaPts(earn);
    const emitidosMes = somaPts(earn, mesAtual), emitidosAnt = somaPts(earn, mesAnterior);
    const resgatados = Math.abs(somaPts(redeem));
    const resgMes = Math.abs(somaPts(redeem, mesAtual)), resgAnt = Math.abs(somaPts(redeem, mesAnterior));
    const cadMes = clientes.filter((c) => c.criadoEm && mesAtual(c.criadoEm)).length;
    const cadAnt = clientes.filter((c) => c.criadoEm && mesAnterior(c.criadoEm)).length;
    return {
      totalClientes: clientes.length, cadMes, cadAnt,
      emitidos, emitidosMes, emitidosAnt,
      resgatados, resgMes, resgAnt,
      valorGerado: emitidos * vpp, valorMes: emitidosMes * vpp, valorAnt: emitidosAnt * vpp,
    };
  }, [transacoes, clientes, vpp]);

  // Gasto/última compra por cliente (casado pelo telefone, mesmo critério do CRM)
  const gastoPorCliente = useMemo(() => {
    const m = {};
    (clientes || []).forEach((c) => {
      const peds = (orders || []).filter((o) => o.clienteTelefone && o.clienteTelefone === c.telefone && o.status !== "cancelled");
      const total = peds.reduce((s, o) => s + o.items.reduce((a, i) => a + i.price * i.quantity, 0), 0);
      const ultimo = peds.map((o) => o.createdAtISO).filter(Boolean).sort().slice(-1)[0] || null;
      m[c.id] = { total, ultimo };
    });
    return m;
  }, [clientes, orders]);

  const ranking = clientes.map((c) => ({ ...c, pontos: saldo[c.id] || 0, ...(gastoPorCliente[c.id] || { total: 0, ultimo: null }) }))
    .filter((c) => c.pontos > 0).sort((a, b) => b.pontos - a.pontos);
  const recVisiveis = verTodasRec ? recompensas : recompensas.slice(0, 5);

  const KPIS = [
    { rot: "Clientes Cadastrados", val: fmtInt(met.totalClientes), d: deltaMesFid(met.cadMes, met.cadAnt), cor: "#E67E22", Icone: FidIco.pessoas },
    { rot: "Pontos Emitidos", val: fmtInt(met.emitidos), d: deltaMesFid(met.emitidosMes, met.emitidosAnt), cor: "#0F4C5C", Icone: FidIco.estrela },
    { rot: "Pontos Resgatados", val: fmtInt(met.resgatados), d: deltaMesFid(met.resgMes, met.resgAnt), cor: "#5E8C31", Icone: FidIco.presente },
    { rot: "Valor Gerado", val: formatCurrency(met.valorGerado), d: deltaMesFid(met.valorMes, met.valorAnt), cor: "#B45309", Icone: FidIco.dinheiro },
  ];

  // Exportações CSV (dados reais)
  function baixarCsv(nome, linhas) {
    const csv = linhas.map((l) => l.map((c) => `"${String(c ?? "").replace(/"/g, '""')}"`).join(";")).join("\n");
    const url = URL.createObjectURL(new Blob(["﻿" + csv], { type: "text/csv;charset=utf-8" }));
    const a = document.createElement("a"); a.href = url; a.download = nome; a.click(); URL.revokeObjectURL(url);
  }
  function exportarClientes() {
    baixarCsv("fidelidade-clientes.csv", [["Cliente", "Telefone", "Pontos", "Total gasto", "Última compra"],
      ...ranking.map((c) => [c.nome, c.telefone || "", c.pontos, c.total.toFixed(2).replace(".", ","), c.ultimo ? new Date(c.ultimo).toLocaleDateString("pt-BR") : "—"])]);
  }
  function exportarMovimentacoes() {
    const nomeCli = {}; clientes.forEach((c) => (nomeCli[c.id] = c.nome));
    baixarCsv("fidelidade-movimentacoes.csv", [["Data", "Cliente", "Tipo", "Pontos", "Descrição"],
      ...transacoes.map((t) => [t.criadoEmISO ? new Date(t.criadoEmISO).toLocaleString("pt-BR") : "", nomeCli[t.clienteId] || "—", t.tipo === "redeem" ? "Resgate" : "Emissão", t.pontos, t.descricao || ""])]);
  }

  const inpCard = "w-full rounded-xl border border-[var(--pp-border)] bg-white px-3.5 py-2.5 text-sm text-dash-navy outline-none transition focus:border-[#E67E22]";
  const COMO = [
    { n: 1, cor: "#E67E22", Icone: FidIco.dinheiro, t: "Cliente faz compra", d: "A cada real gasto, pontos são acumulados automaticamente." },
    { n: 2, cor: "#0F4C5C", Icone: FidIco.estrela, t: "Pontos acumulam", d: "Os pontos ficam disponíveis na conta do cliente." },
    { n: 3, cor: "#5E8C31", Icone: FidIco.presente, t: "Troca por recompensas", d: "Cliente troca pontos por recompensas incríveis!" },
  ];
  const DICAS = ["Divulgue o programa nas redes sociais", "Informe os clientes no momento do pedido", "Crie recompensas atrativas", "Acompanhe os relatórios regularmente"];

  return (
    <main className="space-y-5">
      {/* Cabeçalho */}
      <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
        <div>
          <h2 className="page-title flex items-center gap-3 text-2xl font-bold tracking-tight text-dash-navy">
            Programa de Fidelidade
            <span className={`rounded-full px-2.5 py-1 text-xs font-black ${programaAtivo ? "bg-[#5E8C31]/15 text-[#3F6021]" : "bg-[var(--pp-border)] text-[var(--pp-text-muted)]"}`}>{programaAtivo ? "Ativo" : "Inativo"}</span>
          </h2>
          <p className="mt-1 text-sm text-[var(--pp-text-muted)]">Gerencie regras de pontuação, recompensas e acompanhe a performance do seu programa.</p>
        </div>
        <div className="relative">
          <button onClick={() => setConfigAberto((v) => !v)} className="inline-flex items-center gap-2 rounded-xl border border-[var(--pp-border)] bg-white px-4 py-2.5 text-sm font-bold text-dash-navy transition hover:bg-[var(--pp-bg)] [&>svg]:h-4 [&>svg]:w-4"><FidIco.config /> Configurações do Programa</button>
          {configAberto && (
            <>
              <div className="fixed inset-0 z-[90]" onClick={() => setConfigAberto(false)} />
              <div className="absolute right-0 z-[95] mt-2 w-64 rounded-2xl border border-[var(--pp-border)] bg-white p-4 shadow-xl">
                <p className="text-sm font-black text-dash-navy">Status do programa</p>
                <p className="mt-0.5 text-xs text-[var(--pp-text-muted)]">Quando inativo, novas compras não creditam pontos.</p>
                <div className="mt-3 flex items-center justify-between">
                  <span className="text-sm font-bold text-dash-navy">{programaAtivo ? "Ativo" : "Inativo"}</span>
                  <button type="button" role="switch" aria-checked={programaAtivo} onClick={() => { api?.salvarRegra({ valorPorPonto: vpp, pontosPorReal: Number(String(pontosPorReal).replace(",", ".")) || 100, ativo: !programaAtivo }); setConfigAberto(false); }}
                    className={`relative inline-flex h-6 w-11 items-center rounded-full transition ${programaAtivo ? "bg-[#5E8C31]" : "bg-[var(--pp-border)]"}`}>
                    <span className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition ${programaAtivo ? "translate-x-5" : "translate-x-0.5"}`} />
                  </button>
                </div>
              </div>
            </>
          )}
        </div>
      </div>

      {/* KPIs */}
      <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">
        {KPIS.map((k) => (
          <div key={k.rot} className="rounded-2xl border border-[var(--pp-border)] bg-white p-4 shadow-[0_2px_8px_rgba(43,35,32,0.04)]">
            <div className="flex items-start gap-3">
              <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl [&>svg]:h-5 [&>svg]:w-5" style={{ background: `${k.cor}1A`, color: k.cor }}><k.Icone /></span>
              <div className="min-w-0">
                <p className="truncate text-xs font-semibold text-[var(--pp-text-muted)]">{k.rot}</p>
                <p className="page-title text-2xl font-black text-dash-navy">{k.val}</p>
                <p className="mt-0.5 text-[11px] font-bold" style={{ color: k.d.cor }}>{k.d.txt}</p>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Corpo: 2/3 (regra + recompensas + ranking) · 1/3 (como funciona + dicas + exportar) */}
      <div className="grid gap-5 lg:grid-cols-3">
        <div className="space-y-5 lg:col-span-2">
          {/* Regra de Pontuação */}
          <section ref={regraRef} className="rounded-2xl border border-[var(--pp-border)] bg-white p-5">
            <h3 className="flex items-center gap-1.5 text-base font-black text-dash-navy">Regra de Pontuação <span className="text-[var(--pp-text-muted)] [&>svg]:h-3.5 [&>svg]:w-3.5" title="A cada R$ gasto o cliente acumula pontos."><FidIco.info /></span></h3>
            <div className="mt-4 grid gap-4 lg:grid-cols-2">
              {/* Ganho */}
              <div>
                <span className="mb-1.5 block text-xs font-bold uppercase tracking-wider text-[var(--pp-text-muted)]">Ganho — valor em R$ para ganhar 1 ponto:</span>
                <div className="flex items-center gap-2">
                  <span className="shrink-0 text-sm font-bold text-[var(--pp-text-muted)]">R$</span>
                  <input inputMode="decimal" value={valorPorPonto} onChange={(e) => setValorPorPonto(e.target.value.replace(/[^\d.,]/g, ""))} className={`${inpCard} font-black`} />
                  <span className="shrink-0 text-sm font-bold text-[var(--pp-text-muted)]">= 1 ponto</span>
                </div>
                <p className="mt-1.5 text-xs text-[var(--pp-text-muted)]">A cada <b className="text-dash-navy">R$ {String(vppLive).replace(".", ",")}</b> em compras o cliente ganha <b className="text-dash-navy">1 ponto</b> · R$ {String(Math.round(vppLive * 50 * 100) / 100).replace(".", ",")} = <b className="text-dash-navy">50 pontos</b></p>
              </div>
              {/* Resgate */}
              <div>
                <span className="mb-1.5 block text-xs font-bold uppercase tracking-wider text-[var(--pp-text-muted)]">Resgate — pontos que valem R$ 1,00:</span>
                <div className="flex items-center gap-2">
                  <input inputMode="numeric" value={pontosPorReal} onChange={(e) => setPontosPorReal(e.target.value.replace(/[^\d]/g, ""))} className={`${inpCard} font-black`} />
                  <span className="shrink-0 text-sm font-bold text-[var(--pp-text-muted)]">pts = R$ 1</span>
                </div>
                <p className="mt-1.5 text-xs text-[var(--pp-text-muted)]">O cliente pode pagar a conta com pontos: <b className="text-dash-navy">{fmtInt(pprLive)} pts = R$ 1,00</b>.</p>
              </div>
            </div>
            {/* Descrição viva de como o programa funciona com a configuração atual */}
            <p className="mt-4 rounded-xl border border-[var(--pp-border)] bg-[var(--pp-bg)] px-4 py-3 text-sm leading-6 text-[var(--pp-text-body)]">
              <b className="text-dash-navy">Como funciona hoje:</b> o cliente ganha <b className="text-dash-navy">1 ponto</b> a cada <b className="text-dash-navy">R$ {String(vppLive).replace(".", ",")}</b> em compras e pode usar <b className="text-dash-navy">{fmtInt(pprLive)} pontos</b> para abater <b className="text-dash-navy">R$ 1,00</b> no pagamento da conta. Exemplo: uma compra de <b className="text-dash-navy">R$ 100,00</b> gera <b className="text-dash-navy">{fmtInt(ptsEmCem)} pontos</b> (≈ <b className="text-dash-navy">{formatCurrency(creditoCem)}</b> em créditos para resgate).
            </p>
            <div className="mt-4 flex justify-end">
              <button onClick={() => api?.salvarRegra({ valorPorPonto: Number(String(valorPorPonto).replace(",", ".")) || 1, pontosPorReal: Number(String(pontosPorReal).replace(",", ".")) || 100, ativo: programaAtivo || !regra })} className="btn-laranja rounded-xl px-5 py-2.5 text-sm font-bold">Salvar Regra</button>
            </div>
          </section>

          {/* Recompensas Disponíveis */}
          <section className="rounded-2xl border border-[var(--pp-border)] bg-white p-5">
            <div className="flex items-center justify-between gap-2">
              <h3 className="text-base font-black text-dash-navy">Recompensas Disponíveis</h3>
              <button onClick={() => setModalRec({})} className="inline-flex items-center gap-1.5 rounded-xl border border-[#E67E22]/40 bg-[#E67E22]/[0.08] px-3.5 py-2 text-sm font-bold text-[#C2410C] transition hover:bg-[#E67E22]/15 [&>svg]:h-4 [&>svg]:w-4"><FidIco.mais /> Nova Recompensa</button>
            </div>
            <div className="mt-4 overflow-x-auto">
              <table className="w-full min-w-[560px] text-sm">
                <thead>
                  <tr className="border-b border-[var(--pp-border)] text-left text-[11px] font-bold uppercase tracking-wider text-[var(--pp-text-muted)]">
                    <th className="pb-2 pr-3">Recompensa</th><th className="pb-2 pr-3">Descrição</th><th className="pb-2 pr-3">Pontos Necessários</th><th className="pb-2 pr-3">Status</th><th className="pb-2 text-right">Ações</th>
                  </tr>
                </thead>
                <tbody>
                  {recompensas.length === 0 && <tr><td colSpan={5} className="py-6 text-center text-[var(--pp-text-muted)]">Nenhuma recompensa cadastrada.</td></tr>}
                  {recVisiveis.map((r) => (
                    <tr key={r.id} className="border-b border-[var(--pp-border)] last:border-0">
                      <td className="py-3 pr-3">
                        <span className="flex items-center gap-2 font-bold text-dash-navy">
                          <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg bg-[#E67E22]/12 text-[#E67E22] [&>svg]:h-4 [&>svg]:w-4"><FidIco.presente /></span>
                          {r.nome}
                        </span>
                      </td>
                      <td className="py-3 pr-3 text-[var(--pp-text-muted)]">{r.descricao || "—"}</td>
                      <td className="py-3 pr-3 font-bold text-dash-navy">{fmtInt(r.pontosNecessarios)} pts</td>
                      <td className="py-3 pr-3">
                        <button onClick={() => api?.editarRecompensa?.(r.id, { ativo: r.ativo === false })} title="Alternar status"
                          className={`rounded-full px-2.5 py-1 text-xs font-black transition ${r.ativo === false ? "bg-[var(--pp-border)] text-[var(--pp-text-muted)]" : "bg-[#5E8C31]/15 text-[#3F6021] hover:bg-[#5E8C31]/25"}`}>
                          {r.ativo === false ? "Inativa" : "Ativa"}
                        </button>
                      </td>
                      <td className="py-3">
                        <div className="flex items-center justify-end gap-1.5">
                          <button onClick={() => setModalRec(r)} title="Editar" className="rounded-lg border border-[var(--pp-border)] bg-white p-1.5 text-[#0F4C5C] transition hover:bg-[var(--pp-bg)] [&>svg]:h-4 [&>svg]:w-4"><FidIco.lapis /></button>
                          <button onClick={() => setConfirmarExcluir(r)} title="Excluir" className="rounded-lg border border-[#DC2626]/25 bg-[#DC2626]/[0.06] p-1.5 text-[#B91C1C] transition hover:bg-[#DC2626]/12 [&>svg]:h-4 [&>svg]:w-4"><FidIco.lixo /></button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            {recompensas.length > 5 && (
              <div className="mt-3 text-center">
                <button onClick={() => setVerTodasRec((v) => !v)} className="text-sm font-bold text-[#C2410C] hover:underline">{verTodasRec ? "Mostrar menos" : `Ver todas as recompensas (${recompensas.length})`}</button>
              </div>
            )}
          </section>

          {/* Clientes com Mais Pontos */}
          <section className="rounded-2xl border border-[var(--pp-border)] bg-white p-5">
            <div className="flex items-center justify-between gap-2">
              <h3 className="text-base font-black text-dash-navy">Clientes com Mais Pontos</h3>
              {onVerClientes && <button onClick={onVerClientes} className="inline-flex items-center gap-1.5 text-sm font-bold text-[#C2410C] hover:underline [&>svg]:h-3.5 [&>svg]:w-3.5">Ver todos os clientes <FidIco.seta /></button>}
            </div>
            <div className="mt-4 overflow-x-auto">
              <table className="w-full min-w-[560px] text-sm">
                <thead>
                  <tr className="border-b border-[var(--pp-border)] text-left text-[11px] font-bold uppercase tracking-wider text-[var(--pp-text-muted)]">
                    <th className="pb-2 pr-3">Posição</th><th className="pb-2 pr-3">Cliente</th><th className="pb-2 pr-3">Pontos</th><th className="pb-2 pr-3">Última Compra</th><th className="pb-2 text-right">Total Gasto</th>
                  </tr>
                </thead>
                <tbody>
                  {ranking.length === 0 && <tr><td colSpan={5} className="py-6 text-center text-[var(--pp-text-muted)]">Nenhum cliente com pontos ainda.</td></tr>}
                  {ranking.slice(0, 5).map((c, i) => {
                    const medalha = ["#E6A817", "#9CA3AF", "#B45309"][i];
                    return (
                      <tr key={c.id} className="border-b border-[var(--pp-border)] last:border-0">
                        <td className="py-3 pr-3">
                          <span className={`flex h-7 w-7 items-center justify-center rounded-full text-xs font-black ${medalha ? "text-white" : "bg-[var(--pp-bg)] text-[var(--pp-text-muted)]"}`} style={medalha ? { background: medalha } : undefined}>{i + 1}</span>
                        </td>
                        <td className="py-3 pr-3 font-bold text-dash-navy">{c.nome}</td>
                        <td className="py-3 pr-3 font-black text-[#C2410C]">{fmtInt(c.pontos)} pts</td>
                        <td className="py-3 pr-3 text-[var(--pp-text-muted)]">{c.ultimo ? new Date(c.ultimo).toLocaleDateString("pt-BR") : "—"}</td>
                        <td className="py-3 text-right font-bold text-dash-navy">{formatCurrency(c.total)}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </section>
        </div>

        {/* Coluna lateral */}
        <div className="space-y-5">
          {/* Como funciona */}
          <section className="rounded-2xl border border-[var(--pp-border)] bg-white p-5">
            <h3 className="text-base font-black text-dash-navy">Como funciona?</h3>
            <div className="mt-4 space-y-4">
              {COMO.map((c, i) => (
                <div key={c.n} className="relative flex gap-3">
                  {i < COMO.length - 1 && <span className="absolute left-[15px] top-9 h-[calc(100%-4px)] w-px bg-[var(--pp-border)]" />}
                  <span className="relative flex h-8 w-8 shrink-0 items-center justify-center rounded-full text-xs font-black text-white" style={{ background: c.cor }}>{c.n}</span>
                  <div className="min-w-0">
                    <p className="flex items-center gap-1.5 text-sm font-black text-dash-navy"><span className="[&>svg]:h-4 [&>svg]:w-4" style={{ color: c.cor }}><c.Icone /></span> {c.t}</p>
                    <p className="mt-0.5 text-xs leading-snug text-[var(--pp-text-muted)]">{c.d}</p>
                  </div>
                </div>
              ))}
            </div>
          </section>

          {/* Dicas */}
          <section className="rounded-2xl border border-[var(--pp-border)] bg-white p-5">
            <h3 className="text-base font-black text-dash-navy">Dicas para engajar mais</h3>
            <ul className="mt-3 space-y-2.5">
              {DICAS.map((d) => (
                <li key={d} className="flex items-start gap-2 text-sm text-dash-navy">
                  <span className="mt-0.5 flex h-4 w-4 shrink-0 items-center justify-center rounded-full bg-[#5E8C31]/15 text-[#3F6021] [&>svg]:h-3 [&>svg]:w-3"><FidIco.check /></span>
                  {d}
                </li>
              ))}
            </ul>
          </section>

          {/* Exportar Relatórios */}
          <section className="rounded-2xl border border-[var(--pp-border)] bg-white p-5">
            <h3 className="text-base font-black text-dash-navy">Exportar Relatórios</h3>
            <p className="mt-0.5 text-xs text-[var(--pp-text-muted)]">Baixe relatórios detalhados do programa.</p>
            <div className="mt-3 grid grid-cols-2 gap-2.5">
              <button onClick={exportarClientes} className="inline-flex items-center justify-center gap-2 rounded-xl border border-[var(--pp-border)] bg-white px-3 py-2.5 text-sm font-bold text-dash-navy transition hover:bg-[var(--pp-bg)] [&>svg]:h-4 [&>svg]:w-4"><FidIco.download /> Clientes</button>
              <button onClick={exportarMovimentacoes} className="inline-flex items-center justify-center gap-2 rounded-xl border border-[var(--pp-border)] bg-white px-3 py-2.5 text-sm font-bold text-dash-navy transition hover:bg-[var(--pp-bg)] [&>svg]:h-4 [&>svg]:w-4"><FidIco.download /> Movimentações</button>
            </div>
          </section>
        </div>
      </div>

      {/* Modal nova/editar recompensa */}
      {modalRec && (
        <RecompensaModal recompensa={modalRec.id ? modalRec : null}
          onFechar={() => setModalRec(null)}
          onSalvar={(dados) => { if (modalRec.id) api?.editarRecompensa?.(modalRec.id, dados); else api?.addRecompensa?.(dados); setModalRec(null); }} />
      )}

      {/* Confirmar exclusão */}
      {confirmarExcluir && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[rgba(33,24,20,0.4)] p-4 backdrop-blur-sm" onClick={() => setConfirmarExcluir(null)}>
          <div onClick={(e) => e.stopPropagation()} className="w-full max-w-sm space-y-4 rounded-2xl border border-[var(--pp-border)] bg-white p-6 shadow-xl">
            <div>
              <h2 className="text-lg font-black text-dash-navy">Excluir recompensa?</h2>
              <p className="mt-1 text-sm text-[var(--pp-text-muted)]">A recompensa <b className="text-dash-navy">{confirmarExcluir.nome}</b> será removida do programa.</p>
            </div>
            <div className="flex gap-3">
              <button onClick={() => setConfirmarExcluir(null)} className="flex-1 rounded-xl border border-[var(--pp-border)] bg-white py-3 text-sm font-bold text-dash-navy transition hover:bg-[var(--pp-bg)]">Cancelar</button>
              <button onClick={() => { api?.removerRecompensa?.(confirmarExcluir.id); setConfirmarExcluir(null); }} className="flex-[1.5] rounded-xl bg-[#DC2626] py-3 text-sm font-black text-white transition hover:opacity-90">Excluir</button>
            </div>
          </div>
        </div>
      )}
    </main>
  );
}

// Modal de cadastro/edição de recompensa (tema claro)
function RecompensaModal({ recompensa, onFechar, onSalvar }) {
  const [f, setF] = useState({ nome: recompensa?.nome || "", descricao: recompensa?.descricao || "", pontosNecessarios: recompensa?.pontosNecessarios != null ? String(recompensa.pontosNecessarios) : "" });
  const inp = "w-full rounded-xl border border-[var(--pp-border)] bg-white px-3.5 py-2.5 text-sm text-dash-navy outline-none transition focus:border-[#E67E22]";
  const lbl = "mb-1.5 block text-xs font-bold uppercase tracking-wider text-[var(--pp-text-muted)]";
  const valido = f.nome.trim().length > 0 && Number(f.pontosNecessarios) > 0;
  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[rgba(33,24,20,0.4)] p-4 backdrop-blur-sm" onClick={onFechar}>
      <div onClick={(e) => e.stopPropagation()} className="w-full max-w-md overflow-hidden rounded-2xl border border-[var(--pp-border)] bg-white shadow-xl">
        <div className="flex items-center justify-between border-b border-[var(--pp-border)] px-6 py-4">
          <h2 className="text-lg font-black text-dash-navy">{recompensa ? "Editar recompensa" : "Nova recompensa"}</h2>
          <button onClick={onFechar} className="rounded-lg border border-[var(--pp-border)] bg-white px-3 py-1.5 text-sm font-bold text-dash-navy hover:bg-[var(--pp-bg)]">✕</button>
        </div>
        <div className="space-y-4 px-6 py-5">
          <div><span className={lbl}>Nome *</span><input value={f.nome} onChange={(e) => setF({ ...f, nome: e.target.value })} placeholder="Ex.: Sobremesa grátis" className={inp} autoFocus /></div>
          <div><span className={lbl}>Descrição</span><input value={f.descricao} onChange={(e) => setF({ ...f, descricao: e.target.value })} placeholder="Opcional (ex.: A escolher)" className={inp} /></div>
          <div><span className={lbl}>Pontos necessários *</span><input inputMode="numeric" value={f.pontosNecessarios} onChange={(e) => setF({ ...f, pontosNecessarios: e.target.value.replace(/\D/g, "") })} placeholder="100" className={inp} /></div>
        </div>
        <div className="flex gap-3 border-t border-[var(--pp-border)] px-6 py-4">
          <button onClick={onFechar} className="flex-1 rounded-xl border border-[var(--pp-border)] bg-white py-3 text-sm font-bold text-dash-navy transition hover:bg-[var(--pp-bg)]">Cancelar</button>
          <button onClick={() => valido && onSalvar({ nome: f.nome.trim(), descricao: f.descricao.trim(), pontosNecessarios: Number(f.pontosNecessarios) || 0 })} disabled={!valido} className="btn-laranja flex-[2] rounded-xl py-3 text-sm font-bold disabled:opacity-50">{recompensa ? "Salvar alterações" : "Criar recompensa"}</button>
        </div>
      </div>
    </div>
  );
}

// ════════════════════════════════════════════════════════════
//  Admin — Painel de Chamados de Mesa (migration 044)
// ════════════════════════════════════════════════════════════
// Tipos de chamado — tema CLARO do painel (paleta oficial): laranja de ação
// (garçom), âmbar (conta), roxo (ajuda) e verde (limpeza).
const CHAMADO_TIPOS = {
  garcom:  { label: "Garçom",  emoji: "🔔", cor: "#E67E22", cls: "border-[#E67E22]/35 bg-[#E67E22]/12 text-[#C2410C]" },
  conta:   { label: "Conta",   emoji: "🧾", cor: "#D97706", cls: "border-[#D97706]/35 bg-[#D97706]/12 text-[#B45309]" },
  ajuda:   { label: "Ajuda",   emoji: "🆘", cor: "#7C3AED", cls: "border-[#7C3AED]/30 bg-[#7C3AED]/10 text-[#6D28D9]" },
  limpeza: { label: "Limpeza", emoji: "🧹", cor: "#059669", cls: "border-[#047857]/30 bg-[#059669]/10 text-[#047857]" },
};
// Prioridade pelo tempo de espera (SLA): crítico ≥ 10 min, atenção ≥ 5 min.
const CHAMADO_SLA_CRITICO = 10, CHAMADO_SLA_ATENCAO = 5;
const CHAMADO_PRIOS = {
  critico: { label: "Crítico", cor: "#DC2626" },
  atencao: { label: "Atenção", cor: "#D97706" },
  normal:  { label: "Normal",  cor: "#059669" },
};
const CHAMADO_PRIO_PESO = { critico: 3, atencao: 2, normal: 1 };
function chamadoPrioridade(esperaMin) {
  if (esperaMin >= CHAMADO_SLA_CRITICO) return "critico";
  if (esperaMin >= CHAMADO_SLA_ATENCAO) return "atencao";
  return "normal";
}
function fmtEsperaChamado(min) {
  const m = Math.max(0, Math.round(min));
  if (m < 1) return "agora mesmo";
  if (m < 60) return `há ${m} min`;
  const h = Math.floor(m / 60), r = m % 60;
  return `há ${h}h${r ? ` ${r}min` : ""}`;
}
function fmtRespostaChamado(min) {
  const seg = Math.max(0, Math.round(min * 60));
  if (seg < 60) return `${seg}s`;                 // respostas rápidas: segundos
  const totalMin = Math.floor(seg / 60), s = seg % 60;
  if (totalMin < 60) return `${totalMin}min${s ? ` ${String(s).padStart(2, "0")}s` : ""}`;
  const h = Math.floor(totalMin / 60), m = totalMin % 60; // ≥ 1h: horas e minutos
  return `${h}h ${String(m).padStart(2, "0")}min`;
}
function fmtHoraChamado(iso) {
  if (!iso) return "—";
  const d = new Date(iso); return isNaN(d.getTime()) ? "—" : d.toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" });
}

// ── Painel gerencial de Chamados de Mesa (dados reais · migration 044) ──
function ChamadosPainel({ chamados = [], atenderChamado, assumirChamado = async () => {}, usuarios = [] }) {
  const [busca, setBusca] = useState("");
  const [fTipo, setFTipo] = useState("todos");
  const [fEstado, setFEstado] = useState("abertos");     // abertos | pendente | em_atendimento | atendido
  const [fPrio, setFPrio] = useState("todas");
  const [fEspera, setFEspera] = useState("todos");        // todos | 5 | 10
  const [fResp, setFResp] = useState("todos");            // todos | nao | <userId>
  const [ordenacao, setOrdenacao] = useState("prioridade");
  const [periodoAnalise, setPeriodoAnalise] = useState("hoje"); // rege KPIs de análise + Visão analítica
  const [periodoIni, setPeriodoIni] = useState("");
  const [periodoFim, setPeriodoFim] = useState("");
  const [pagina, setPagina] = useState(1);
  const [expandido, setExpandido] = useState(null);
  const [alertasAbertos, setAlertasAbertos] = useState(false);
  const [atualizadoEm, setAtualizadoEm] = useState(() => Date.now());
  const agora = Date.now();
  const POR_PAGINA = 8;
  const comReset = (setter) => (v) => { setter(v); setPagina(1); };
  const nomeResp = (id) => { if (id == null) return null; const u = usuarios.find((x) => String(x.id) === String(id)); return u ? (u.name || u.email || `#${id}`) : `#${id}`; };

  // Enriquecimento: espera/resposta, estado e prioridade — só dados reais.
  const enriquecidos = useMemo(() => chamados
    .filter((c) => c.status !== "cancelado")
    .map((c) => {
      const criadoMs = c.criadoEmISO ? new Date(c.criadoEmISO).getTime() : agora;
      const atendido = c.status === "atendido";
      const esperaMin = atendido ? null : Math.max(0, (agora - criadoMs) / 60000);
      const respostaMin = (atendido && c.atendidoEmISO) ? Math.max(0, (new Date(c.atendidoEmISO).getTime() - criadoMs) / 60000) : null;
      const estado = atendido ? "atendido" : (c.atendidoPor != null ? "em_atendimento" : "pendente");
      const prioridade = atendido ? null : chamadoPrioridade(esperaMin);
      return { ...c, criadoMs, atendido, esperaMin, respostaMin, estado, prioridade, responsavel: nomeResp(c.atendidoPor), origem: c.origem || "QR da mesa" };
    }), [chamados, agora, usuarios]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── KPIs operacionais AO VIVO (independem do período): fila aberta agora ──
  const h1 = agora - 3600000;
  const abertos = enriquecidos.filter((c) => !c.atendido);
  const criticos = abertos.filter((c) => c.prioridade === "critico").length;
  const novosUltimaHora = abertos.filter((c) => c.criadoMs >= h1).length;

  // ── Período de análise (rege KPIs de análise + Visão analítica) ──
  const [aData, bData] = intervaloPeriodo(periodoAnalise, periodoIni, periodoFim);
  const aMs = aData.getTime(), bMs = bData.getTime();
  const durMs = Math.max(1, bMs - aMs);
  const prevAMs = aMs - durMs; // período anterior de mesma duração (para o comparativo)
  const noPeriodo = (ms) => ms >= aMs && ms <= bMs;
  const atendMs = (c) => (c.atendido && c.atendidoEmISO) ? new Date(c.atendidoEmISO).getTime() : null;

  const chamadosPeriodo = enriquecidos.filter((c) => noPeriodo(c.criadoMs));
  const atendidosPeriodo = enriquecidos.filter((c) => { const t = atendMs(c); return t != null && noPeriodo(t); });
  const atendidosAnterior = enriquecidos.filter((c) => { const t = atendMs(c); return t != null && t >= prevAMs && t < aMs; });
  const media = (arr) => arr.length ? arr.reduce((s, c) => s + c.respostaMin, 0) / arr.length : null;
  const tmr = media(atendidosPeriodo), tmrPrev = media(atendidosAnterior);
  const deltaTmr = (tmr != null && tmrPrev != null) ? tmr - tmrPrev : null;
  const deltaAtend = atendidosAnterior.length ? atendidosPeriodo.length - atendidosAnterior.length : null;

  // Ranking de mesas e análise por tipo / SLA / tendência — no período.
  const porMesa = {}; chamadosPeriodo.forEach((c) => { const m = c.mesa || "—"; porMesa[m] = (porMesa[m] || 0) + 1; });
  const mesasRank = Object.entries(porMesa).map(([mesa, n]) => ({ mesa, n })).sort((a, b) => b.n - a.n);
  const mesaTop = mesasRank[0] || null;

  const porTipo = Object.keys(CHAMADO_TIPOS).map((t) => ({ t, ...CHAMADO_TIPOS[t], n: chamadosPeriodo.filter((c) => c.tipo === t).length }));
  const totalTipo = porTipo.reduce((s, x) => s + x.n, 0);
  const dentroPrazo = atendidosPeriodo.filter((c) => c.respostaMin <= CHAMADO_SLA_CRITICO).length;
  const slaPct = atendidosPeriodo.length ? Math.round((dentroPrazo / atendidosPeriodo.length) * 100) : 0;
  const acimaPrazo = atendidosPeriodo.length - dentroPrazo;

  // Tendência adaptativa: divide o período em faixas iguais e conta os chamados
  // criados em cada faixa. Rótulos por hora (1 dia) ou por data (vários dias).
  const umDia = 86400000;
  const multiDias = durMs > umDia * 1.5;
  const nFaixas = Math.min(12, Math.max(4, multiDias ? Math.ceil(durMs / umDia) : 6));
  const faixaMs = durMs / nFaixas;
  const buckets = [];
  for (let i = 0; i < nFaixas; i++) {
    const ini = aMs + i * faixaMs, fim = i === nFaixas - 1 ? bMs + 1 : aMs + (i + 1) * faixaMs;
    const d = new Date(ini);
    const rot = multiDias ? d.toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit" }) : fmtHoraChamado(d.toISOString());
    buckets.push({ n: enriquecidos.filter((c) => c.criadoMs >= ini && c.criadoMs < fim).length, rot });
  }
  const maxBucket = Math.max(1, ...buckets.map((b) => b.n));
  const PERIODO_LABEL = { hoje: "Hoje", ontem: "Ontem", "7": "Últimos 7 dias", "15": "Últimos 15 dias", "30": "Últimos 30 dias", periodo: (periodoIni || periodoFim) ? `${periodoIni || "—"} a ${periodoFim || "—"}` : "Período" };
  const periodoLabel = PERIODO_LABEL[periodoAnalise] || "Período";

  // ── Fila filtrada + ordenada ──
  const q = busca.trim().toLowerCase();
  const ORDENADORES = {
    prioridade: (a, b) => (CHAMADO_PRIO_PESO[b.prioridade] || 0) - (CHAMADO_PRIO_PESO[a.prioridade] || 0) || a.criadoMs - b.criadoMs,
    antigos: (a, b) => a.criadoMs - b.criadoMs,
    recentes: (a, b) => b.criadoMs - a.criadoMs,
  };
  const fila = enriquecidos
    .filter((c) => fEstado === "abertos" ? !c.atendido : c.estado === fEstado)
    .filter((c) => fTipo === "todos" || c.tipo === fTipo)
    .filter((c) => fPrio === "todas" || c.prioridade === fPrio)
    .filter((c) => fEspera === "todos" || (c.esperaMin != null && c.esperaMin >= Number(fEspera)))
    .filter((c) => fResp === "todos" || (fResp === "nao" ? c.atendidoPor == null : String(c.atendidoPor) === fResp))
    .filter((c) => !q || `${c.mesa || ""} ${CHAMADO_TIPOS[c.tipo]?.label || ""} ${c.responsavel || ""}`.toLowerCase().includes(q))
    .sort(ORDENADORES[ordenacao] || ORDENADORES.prioridade);
  const totalFila = fila.length;
  const totalPaginas = Math.max(1, Math.ceil(totalFila / POR_PAGINA));
  const pgAtual = Math.min(pagina, totalPaginas);
  const inicio = (pgAtual - 1) * POR_PAGINA;
  const visiveis = fila.slice(inicio, inicio + POR_PAGINA);
  const recentes = enriquecidos.filter((c) => c.atendido && c.atendidoEmISO).sort((a, b) => new Date(b.atendidoEmISO) - new Date(a.atendidoEmISO)).slice(0, 6);
  const respOpcoes = [...new Set(enriquecidos.map((c) => c.atendidoPor).filter((x) => x != null).map(String))];

  function limparFiltros() { setBusca(""); setFTipo("todos"); setFEstado("abertos"); setFPrio("todas"); setFEspera("todos"); setFResp("todos"); setOrdenacao("prioridade"); setPeriodoAnalise("hoje"); setPeriodoIni(""); setPeriodoFim(""); setPagina(1); }
  const horaAtualizacao = `${String(new Date(atualizadoEm).getHours()).padStart(2, "0")}:${String(new Date(atualizadoEm).getMinutes()).padStart(2, "0")}`;
  const periodoBaixo = periodoLabel.toLowerCase();

  const KPIS = [
    { rot: "Pendentes agora", val: abertos.length, cor: "#E67E22", Icone: IconComanda, sub: novosUltimaHora > 0 ? `+${novosUltimaHora} na última hora` : "estável na última hora" },
    { rot: "Críticos", val: criticos, cor: "#DC2626", Icone: IconAlerta, sub: `acima de ${CHAMADO_SLA_CRITICO} min de espera` },
    { rot: "Tempo médio de resposta", val: tmr != null ? fmtRespostaChamado(tmr) : "—", cor: "#0F4C5C", Icone: IconRelogio, sub: deltaTmr != null ? `${deltaTmr <= 0 ? "−" : "+"}${fmtRespostaChamado(Math.abs(deltaTmr))} vs. período anterior` : `${periodoBaixo} · sem base anterior`, subCor: deltaTmr != null ? (deltaTmr <= 0 ? "#047857" : "#B91C1C") : null },
    { rot: "Mesa com mais chamados", val: mesaTop ? mesaTop.mesa : "—", cor: "#0F4C5C", Icone: IconUsuarios, sub: mesaTop ? `${mesaTop.n} ${mesaTop.n === 1 ? "chamado" : "chamados"} · ${periodoBaixo}` : `sem chamados · ${periodoBaixo}` },
    { rot: "Atendidos", val: atendidosPeriodo.length, cor: "#059669", Icone: IconCheck, sub: deltaAtend != null ? `${deltaAtend >= 0 ? "+" : "−"}${Math.abs(deltaAtend)} vs. período anterior` : `${dentroPrazo} no prazo · ${periodoBaixo}`, subCor: deltaAtend != null ? (deltaAtend >= 0 ? "#047857" : "#B91C1C") : null },
  ];
  const selBox = "flex min-w-0 items-center gap-2 rounded-xl border border-[var(--pp-border)] bg-white px-3 py-1.5";
  const CHIP_ESTADOS = [["pendente", "Pendentes"], ["em_atendimento", "Em atendimento"], ["atendido", "Atendidos"]];
  const CHIP_TIPOS = [["todos", "Todos"], ...Object.keys(CHAMADO_TIPOS).map((t) => [t, CHAMADO_TIPOS[t].label])];

  return (
    <main className="space-y-5">
      {/* Cabeçalho */}
      <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
        <div>
          <h2 className="page-title flex items-center gap-2.5 text-2xl font-bold tracking-tight text-dash-navy">
            <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl border border-[#E67E22]/30 bg-[#E67E22]/10 text-[#E67E22] [&>svg]:h-5 [&>svg]:w-5"><IconMesas /></span>
            Chamados de Mesa
          </h2>
          <p className="mt-1 text-sm text-[var(--pp-text-muted)]">Solicitações dos clientes em tempo real — garçom, conta, ajuda e limpeza.</p>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <span className="hidden items-center gap-1.5 text-sm text-[var(--pp-text-muted)] sm:inline-flex">Última atualização: hoje às {horaAtualizacao} <span className="h-1.5 w-1.5 rounded-full bg-[#059669]" /></span>
          <button onClick={() => setAtualizadoEm(Date.now())} className="inline-flex items-center gap-2 rounded-xl border border-[var(--pp-border)] bg-white px-3.5 py-2 text-sm font-bold text-dash-navy transition hover:bg-[var(--pp-bg)]"><IconRelogio /> Atualizar</button>
          <button onClick={() => setAlertasAbertos((v) => !v)} className={`inline-flex items-center gap-2 rounded-xl border px-3.5 py-2 text-sm font-bold transition ${alertasAbertos ? "border-[#E67E22] bg-[#E67E22]/10 text-[#C2410C]" : "border-[#E67E22]/40 bg-[#E67E22]/8 text-[#C2410C] hover:bg-[#E67E22]/15"}`}><IconAlerta /> Configurar alertas</button>
        </div>
      </div>

      {alertasAbertos && (
        <div className="rounded-2xl border border-[#E67E22]/30 bg-[#E67E22]/[0.06] p-4 text-sm text-dash-navy">
          <p className="font-bold">Regras de alerta por tempo de espera (SLA)</p>
          <p className="mt-1 text-[var(--pp-text-muted)]">Um chamado entra em <b className="text-[#B45309]">Atenção</b> ao passar de {CHAMADO_SLA_ATENCAO} min sem atendimento e vira <b className="text-[#B91C1C]">Crítico</b> a partir de {CHAMADO_SLA_CRITICO} min. Esses limites definem os KPIs "Críticos" e "SLA de atendimento".</p>
        </div>
      )}

      {/* KPIs */}
      <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5">
        {KPIS.map((k) => (
          <div key={k.rot} className="flex items-start gap-3 rounded-2xl border border-[var(--pp-border)] bg-white p-4 shadow-[0_2px_8px_rgba(43,35,32,0.04)]">
            <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl [&>svg]:h-6 [&>svg]:w-6" style={{ background: `${k.cor}1A`, color: k.cor }}><k.Icone /></span>
            <div className="min-w-0">
              <p className="truncate text-xs font-semibold text-[var(--pp-text-muted)]">{k.rot}</p>
              <p className="page-title text-xl font-black text-dash-navy">{k.val}</p>
              {k.sub && <p className="mt-0.5 truncate text-[11px] font-semibold" style={{ color: k.subCor || "var(--pp-text-muted)" }}>{k.sub}</p>}
            </div>
          </div>
        ))}
      </div>

      {/* Barra de filtros */}
      <div className="space-y-3 rounded-2xl border border-[var(--pp-border)] bg-white p-3">
        <div className="flex flex-col gap-3 xl:flex-row xl:items-center">
          <label className="flex flex-1 items-center gap-2 rounded-xl border border-[var(--pp-border)] bg-[var(--pp-bg)] px-3 py-2">
            <span className="text-[var(--pp-text-muted)]"><IconBusca /></span>
            <input value={busca} onChange={(e) => comReset(setBusca)(e.target.value)} placeholder="Buscar por mesa, tipo ou responsável"
              className="w-full bg-transparent text-sm text-dash-navy outline-none placeholder:text-[var(--pp-text-muted)]" />
          </label>
          <div className="flex flex-wrap items-center gap-1.5">
            {CHIP_TIPOS.map(([id, label]) => (
              <button key={id} onClick={() => comReset(setFTipo)(id)}
                className={`inline-flex items-center rounded-full border px-3 py-1.5 text-[13px] font-bold transition ${fTipo === id ? "border-[#E67E22] bg-[#E67E22] text-white shadow-sm" : "border-[var(--pp-border)] bg-white text-dash-navy hover:border-[#E67E22]/50"}`}>{label}</button>
            ))}
          </div>
          <div className="flex flex-wrap items-center gap-1.5">
            {CHIP_ESTADOS.map(([id, label]) => (
              <button key={id} onClick={() => comReset(setFEstado)(fEstado === id ? "abertos" : id)}
                className={`inline-flex items-center rounded-full border px-3 py-1.5 text-[13px] font-bold transition ${fEstado === id ? "border-[#0F4C5C] bg-[#0F4C5C] text-white shadow-sm" : "border-[var(--pp-border)] bg-white text-dash-navy hover:border-[#0F4C5C]/40"}`}>{label}</button>
            ))}
          </div>
        </div>
        <div className="grid grid-cols-2 gap-2 sm:grid-cols-4 xl:flex xl:items-center">
          {[
            { rot: "Período (análise)", val: periodoAnalise, set: setPeriodoAnalise, ops: [["hoje", "Hoje"], ["ontem", "Ontem"], ["7", "7 dias"], ["15", "15 dias"], ["30", "30 dias"], ["periodo", "Período"]] },
            { rot: "Prioridade", val: fPrio, set: setFPrio, ops: [["todas", "Todas"], ["critico", "Crítico"], ["atencao", "Atenção"], ["normal", "Normal"]] },
            { rot: "Tempo de espera", val: fEspera, set: setFEspera, ops: [["todos", "Qualquer"], ["5", "Acima de 5 min"], ["10", "Acima de 10 min"]] },
            { rot: "Responsável", val: fResp, set: setFResp, ops: [["todos", "Todos"], ["nao", "Não atribuído"], ...respOpcoes.map((id) => [id, nomeResp(id)])] },
            { rot: "Ordenar por", val: ordenacao, set: setOrdenacao, ops: [["prioridade", "Prioridade"], ["antigos", "Mais antigos"], ["recentes", "Mais recentes"]] },
          ].map((s) => (
            <label key={s.rot} className={selBox}>
              <div className="min-w-0 flex-1">
                <span className="block text-[9px] font-bold uppercase tracking-wider text-[var(--pp-text-muted)]">{s.rot}</span>
                <select value={s.val} onChange={(e) => comReset(s.set)(e.target.value)} className="w-full cursor-pointer bg-transparent text-[13px] font-bold text-dash-navy outline-none">
                  {s.ops.map(([v, l]) => <option key={v} value={v}>{l}</option>)}
                </select>
              </div>
            </label>
          ))}
          {periodoAnalise === "periodo" && (
            <>
              <label className={`${selBox} col-span-2 sm:col-span-1`}>
                <div className="min-w-0 flex-1">
                  <span className="block text-[9px] font-bold uppercase tracking-wider text-[var(--pp-text-muted)]">Data inicial</span>
                  <input type="date" value={periodoIni} max={periodoFim || undefined} onChange={(e) => comReset(setPeriodoIni)(e.target.value)}
                    className="w-full cursor-pointer bg-transparent text-[13px] font-bold text-dash-navy outline-none" />
                </div>
              </label>
              <label className={`${selBox} col-span-2 sm:col-span-1`}>
                <div className="min-w-0 flex-1">
                  <span className="block text-[9px] font-bold uppercase tracking-wider text-[var(--pp-text-muted)]">Data final</span>
                  <input type="date" value={periodoFim} min={periodoIni || undefined} onChange={(e) => comReset(setPeriodoFim)(e.target.value)}
                    className="w-full cursor-pointer bg-transparent text-[13px] font-bold text-dash-navy outline-none" />
                </div>
              </label>
            </>
          )}
          <button onClick={limparFiltros} className="inline-flex shrink-0 items-center justify-center gap-1.5 rounded-xl border border-[#E67E22]/40 bg-[#E67E22]/8 px-3.5 py-2 text-[13px] font-bold text-[#C2410C] transition hover:bg-[#E67E22]/15">Limpar filtros</button>
        </div>
      </div>

      {/* Fila de chamados + Visão analítica */}
      <div className="grid gap-4 xl:grid-cols-[1.35fr_1fr]">
        {/* Fila */}
        <div className="space-y-3">
          <div className="flex items-center justify-between gap-2">
            <h3 className="page-title flex items-center gap-2 text-lg font-bold text-dash-navy">Fila de chamados
              <span className="inline-flex h-6 min-w-6 items-center justify-center rounded-full bg-[#E67E22]/12 px-1.5 text-xs font-black text-[#C2410C]">{totalFila}</span>
            </h3>
            <span className="text-xs font-semibold text-[var(--pp-text-muted)]">Ordenar por: <b className="text-dash-navy">{({ prioridade: "Prioridade", antigos: "Mais antigos", recentes: "Mais recentes" })[ordenacao]}</b></span>
          </div>

          {totalFila === 0 ? (
            <EmptyState titulo="Nenhum chamado nesta fila" dica="Ajuste os filtros ou aguarde novas solicitações das mesas." />
          ) : (
            <div className="space-y-2.5">
              {visiveis.map((c) => {
                const t = CHAMADO_TIPOS[c.tipo] || CHAMADO_TIPOS.garcom;
                const p = c.atendido ? null : (CHAMADO_PRIOS[c.prioridade] || CHAMADO_PRIOS.normal);
                const critico = c.prioridade === "critico";
                const aberto = expandido === c.id;
                return (
                  <div key={c.id} className={`rounded-2xl border bg-white p-4 shadow-[0_2px_8px_rgba(43,35,32,0.04)] transition ${critico ? "border-[#DC2626]/40 bg-[#DC2626]/[0.04]" : "border-[var(--pp-border)]"}`}>
                    <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
                      <div className="min-w-[120px]">
                        <p className="page-title text-base font-black text-dash-navy">{c.mesa || "Mesa —"}</p>
                        <p className="text-[11px] text-[var(--pp-text-muted)]">Origem: {c.origem}</p>
                      </div>
                      <span className={`inline-flex items-center gap-1 rounded-full border px-2.5 py-1 text-[11px] font-black ${t.cls}`}>{t.emoji} {t.label}</span>
                      <div className="min-w-[110px] text-[13px]">
                        <p className="flex items-center gap-1.5 font-semibold text-dash-navy"><IconRelogio /> {fmtEsperaChamado(c.esperaMin ?? 0)}</p>
                        <p className="text-[11px] text-[var(--pp-text-muted)]">Responsável: {c.responsavel || "Não atribuído"}</p>
                      </div>
                      {p && <span className="inline-flex items-center gap-1.5 text-[13px] font-bold" style={{ color: p.cor }}><span className="h-2 w-2 rounded-full" style={{ background: p.cor }} />{p.label}</span>}
                      <div className="ml-auto flex items-center gap-2">
                        {c.estado === "em_atendimento"
                          ? <button onClick={() => atenderChamado(c.id)} className="btn-verde rounded-xl px-4 py-2 text-[13px] font-bold">Marcar atendido</button>
                          : <button onClick={() => assumirChamado(c.id)} className="btn-laranja rounded-xl px-4 py-2 text-[13px] font-bold">Assumir</button>}
                        <button onClick={() => setExpandido(aberto ? null : c.id)} className="rounded-xl border border-[var(--pp-border)] bg-white px-3 py-2 text-[13px] font-bold text-dash-navy transition hover:bg-[var(--pp-bg)]">Ver detalhes</button>
                      </div>
                    </div>
                    {aberto && (
                      <div className="mt-3 grid grid-cols-2 gap-3 border-t border-[var(--pp-border)] pt-3 text-[13px] sm:grid-cols-4">
                        <div><p className="text-[10px] font-bold uppercase tracking-wider text-[var(--pp-text-muted)]">Comanda</p><p className="font-semibold text-dash-navy">{c.comanda || "—"}</p></div>
                        <div><p className="text-[10px] font-bold uppercase tracking-wider text-[var(--pp-text-muted)]">Aberto às</p><p className="font-semibold text-dash-navy">{fmtHoraChamado(c.criadoEmISO)}</p></div>
                        <div><p className="text-[10px] font-bold uppercase tracking-wider text-[var(--pp-text-muted)]">Estado</p><p className="font-semibold text-dash-navy">{c.estado === "em_atendimento" ? "Em atendimento" : c.estado === "atendido" ? "Atendido" : "Pendente"}</p></div>
                        <div><p className="text-[10px] font-bold uppercase tracking-wider text-[var(--pp-text-muted)]">Origem</p><p className="font-semibold text-dash-navy">{c.origem}</p></div>
                      </div>
                    )}
                  </div>
                );
              })}

              {/* Paginação */}
              {totalFila > POR_PAGINA && (
                <div className="flex items-center justify-between gap-3 pt-1">
                  <p className="text-sm text-[var(--pp-text-muted)]">Mostrando {inicio + 1}–{Math.min(inicio + POR_PAGINA, totalFila)} de {totalFila} chamados</p>
                  <div className="flex items-center gap-1">
                    <button onClick={() => setPagina(Math.max(1, pgAtual - 1))} disabled={pgAtual <= 1} className="flex h-8 w-8 items-center justify-center rounded-lg border border-[var(--pp-border)] bg-white text-dash-navy transition hover:bg-[var(--pp-bg)] disabled:opacity-40">‹</button>
                    {Array.from({ length: totalPaginas }, (_, i) => i + 1).map((pp) => (
                      <button key={pp} onClick={() => setPagina(pp)} className={`flex h-8 min-w-8 items-center justify-center rounded-lg border px-2 text-sm font-bold transition ${pp === pgAtual ? "border-[#E67E22] bg-[#E67E22] text-white" : "border-[var(--pp-border)] bg-white text-dash-navy hover:bg-[var(--pp-bg)]"}`}>{pp}</button>
                    ))}
                    <button onClick={() => setPagina(Math.min(totalPaginas, pgAtual + 1))} disabled={pgAtual >= totalPaginas} className="flex h-8 w-8 items-center justify-center rounded-lg border border-[var(--pp-border)] bg-white text-dash-navy transition hover:bg-[var(--pp-bg)] disabled:opacity-40">›</button>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        {/* Visão analítica */}
        <div className="space-y-4 rounded-2xl border border-[var(--pp-border)] bg-white p-4 shadow-[0_2px_8px_rgba(43,35,32,0.04)]">
          <h3 className="page-title text-lg font-bold text-dash-navy">Visão analítica <span className="text-xs font-semibold text-[var(--pp-text-muted)]">· {periodoBaixo}</span></h3>

          {/* Chamados por tipo (rosca) */}
          <div className="rounded-xl border border-[var(--pp-border)] bg-[var(--pp-bg)] p-4">
            <p className="mb-3 text-[11px] font-bold uppercase tracking-wider text-[var(--pp-text-muted)]">Chamados por tipo</p>
            <div className="flex items-center gap-4">
              <div className="relative h-[130px] w-[130px] shrink-0">
                <svg viewBox="0 0 140 140" className="h-full w-full -rotate-90">
                  <circle cx="70" cy="70" r="54" fill="none" stroke="#EAE0D6" strokeWidth="18" />
                  {totalTipo > 0 && (() => {
                    const C = 2 * Math.PI * 54; let acc = 0;
                    return porTipo.filter((x) => x.n > 0).map((x) => {
                      const len = (x.n / totalTipo) * C; const el = <circle key={x.t} cx="70" cy="70" r="54" fill="none" stroke={x.cor} strokeWidth="18" strokeDasharray={`${len} ${C - len}`} strokeDashoffset={-acc} strokeLinecap="butt" />; acc += len; return el;
                    });
                  })()}
                </svg>
                <div className="absolute inset-0 flex flex-col items-center justify-center">
                  <span className="text-[10px] font-bold uppercase tracking-wider text-[var(--pp-text-muted)]">Total</span>
                  <span className="page-title text-2xl font-black text-dash-navy">{totalTipo}</span>
                </div>
              </div>
              <div className="min-w-0 flex-1 space-y-1.5">
                {porTipo.map((x) => (
                  <div key={x.t} className="flex items-center gap-2 text-[13px]">
                    <span className="h-2.5 w-2.5 shrink-0 rounded-full" style={{ background: x.cor }} />
                    <span className="text-dash-navy">{x.label}</span>
                    <span className="ml-auto font-bold text-dash-navy">{x.n} <span className="font-semibold text-[var(--pp-text-muted)]">({totalTipo ? Math.round((x.n / totalTipo) * 100) : 0}%)</span></span>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Mesas com mais chamados */}
          <div className="rounded-xl border border-[var(--pp-border)] bg-[var(--pp-bg)] p-4">
            <p className="mb-3 text-[11px] font-bold uppercase tracking-wider text-[var(--pp-text-muted)]">Mesas com mais chamados</p>
            {mesasRank.length === 0 ? <p className="text-sm text-[var(--pp-text-muted)]">Sem chamados no período.</p> : (
              <div className="space-y-2">
                {mesasRank.slice(0, 4).map((m) => (
                  <div key={m.mesa} className="flex items-center gap-2 text-[13px]">
                    <span className="w-16 shrink-0 font-semibold text-dash-navy">{m.mesa}</span>
                    <div className="h-3 flex-1 overflow-hidden rounded-full bg-[#EAE0D6]"><div className="h-full rounded-full bg-[#0F4C5C]" style={{ width: `${Math.max(8, (m.n / mesasRank[0].n) * 100)}%` }} /></div>
                    <span className="w-5 shrink-0 text-right font-bold text-dash-navy">{m.n}</span>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* SLA + Tendência */}
          <div className="grid gap-3 sm:grid-cols-2">
            <div className="rounded-xl border border-[var(--pp-border)] bg-[var(--pp-bg)] p-4">
              <p className="mb-3 text-[11px] font-bold uppercase tracking-wider text-[var(--pp-text-muted)]">SLA de atendimento</p>
              <div className="flex items-center gap-3">
                <div className="relative h-[76px] w-[76px] shrink-0">
                  <svg viewBox="0 0 80 80" className="h-full w-full -rotate-90">
                    <circle cx="40" cy="40" r="32" fill="none" stroke="#EAE0D6" strokeWidth="10" />
                    <circle cx="40" cy="40" r="32" fill="none" stroke={slaPct >= 80 ? "#059669" : slaPct >= 50 ? "#D97706" : "#DC2626"} strokeWidth="10" strokeLinecap="round" strokeDasharray={`${(slaPct / 100) * 2 * Math.PI * 32} ${2 * Math.PI * 32}`} />
                  </svg>
                  <div className="absolute inset-0 flex items-center justify-center"><span className="page-title text-base font-black text-dash-navy">{slaPct}%</span></div>
                </div>
                <div className="min-w-0 text-[12px]">
                  <p className="font-semibold text-[#047857]">Dentro do prazo <b>{slaPct}%</b></p>
                  <p className="mt-1 text-[var(--pp-text-muted)]">Acima de {CHAMADO_SLA_CRITICO} min</p>
                  <p className="font-bold text-[#B91C1C]">{acimaPrazo} {acimaPrazo === 1 ? "chamado" : "chamados"}</p>
                </div>
              </div>
            </div>
            <div className="rounded-xl border border-[var(--pp-border)] bg-[var(--pp-bg)] p-4">
              <p className="mb-3 text-[11px] font-bold uppercase tracking-wider text-[var(--pp-text-muted)]">Tendência <span className="normal-case text-[var(--pp-text-muted)]">· {periodoBaixo}</span></p>
              <svg viewBox="0 0 240 80" className="h-[70px] w-full">
                {(() => {
                  const pts = buckets.map((b, i) => { const x = 10 + (i / (buckets.length - 1)) * 220; const y = 70 - (b.n / maxBucket) * 56; return [x, y]; });
                  const linha = pts.map((p) => p.join(",")).join(" ");
                  const area = `10,70 ${linha} 230,70`;
                  return <>
                    <polygon points={area} fill="#0F4C5C" opacity="0.08" />
                    <polyline points={linha} fill="none" stroke="#0F4C5C" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
                    {pts.map((p, i) => <circle key={i} cx={p[0]} cy={p[1]} r="2.5" fill="#0F4C5C" />)}
                  </>;
                })()}
              </svg>
              <div className="mt-1 flex justify-between text-[10px] font-semibold text-[var(--pp-text-muted)]"><span>{buckets[0]?.rot}</span><span>{buckets[buckets.length - 1]?.rot}</span></div>
            </div>
          </div>

          {/* Sugestão do sistema */}
          {mesaTop && mesaTop.n >= 3 && (
            <div className="rounded-xl border border-[#0F4C5C]/20 bg-[#0F4C5C]/[0.05] p-4">
              <p className="flex items-center gap-2 text-[11px] font-bold uppercase tracking-wider text-[#0F4C5C]">💡 Sugestão do sistema</p>
              <p className="mt-1.5 text-[13px] text-dash-navy">{mesaTop.mesa} concentrou {mesaTop.n} chamados ({periodoBaixo}). Verificar necessidade de apoio no salão.</p>
            </div>
          )}
        </div>
      </div>

      {/* Atendidos recentemente */}
      {recentes.length > 0 && (
        <div className="overflow-hidden rounded-2xl border border-[var(--pp-border)] bg-white">
          <div className="flex items-center justify-between border-b border-[var(--pp-border)] px-5 py-3">
            <h3 className="page-title flex items-center gap-2 text-sm font-bold uppercase tracking-wider text-dash-navy"><IconCheck /> Atendidos recentemente</h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full min-w-[720px] text-sm">
              <thead>
                <tr className="border-b border-[var(--pp-border)] text-left text-[10px] font-bold uppercase tracking-widest text-[var(--pp-text-muted)]">
                  <th className="py-2.5 pl-5 pr-3">Mesa</th><th className="py-2.5 pr-3">Tipo</th><th className="py-2.5 pr-3">Responsável</th>
                  <th className="py-2.5 pr-3">Horário</th><th className="py-2.5 pr-3">Tempo de resposta</th><th className="py-2.5 pr-5">Origem</th>
                </tr>
              </thead>
              <tbody>
                {recentes.map((c) => {
                  const t = CHAMADO_TIPOS[c.tipo] || CHAMADO_TIPOS.garcom;
                  return (
                    <tr key={c.id} className="border-b border-[var(--pp-border)] last:border-0">
                      <td className="py-2.5 pl-5 pr-3 font-bold text-dash-navy">{c.mesa || "—"}</td>
                      <td className="py-2.5 pr-3"><span className={`inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-[11px] font-black ${t.cls}`}>{t.emoji} {t.label}</span></td>
                      <td className="py-2.5 pr-3 text-dash-navy">{c.responsavel || "—"}</td>
                      <td className="py-2.5 pr-3 text-[var(--pp-text-muted)]">{fmtHoraChamado(c.atendidoEmISO)}</td>
                      <td className="py-2.5 pr-3 font-semibold text-dash-navy">{c.respostaMin != null ? fmtRespostaChamado(c.respostaMin) : "—"}</td>
                      <td className="py-2.5 pr-5 text-[var(--pp-text-muted)]">{c.origem}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </main>
  );
}

// ════════════════════════════════════════════════════════════
//  Admin — Auditoria Gerencial (migrations 045 + 053)
//  Central de rastreabilidade, segurança e controle administrativo.
// ════════════════════════════════════════════════════════════
const AUDIT_ACAO = { login: { l: "Login realizado" }, logout: { l: "Logout realizado" }, criar: { l: "Cadastro criado" }, editar: { l: "Registro alterado" }, excluir: { l: "Exclusão" }, cancelar: { l: "Cancelamento" }, abrir_caixa: { l: "Caixa aberto" }, fechar_caixa: { l: "Caixa fechado" }, alterar_plano: { l: "Plano alterado" }, alterar_licenca: { l: "Alteração de licença" } };

// Níveis de risco e suas cores (verde / dourado / laranja / vermelho)
const AUDIT_RISCO = {
  baixo:   { label: "Baixo",   classes: "border-emerald-400/30 bg-emerald-500/10 text-emerald-300", dot: "bg-emerald-400" },
  medio:   { label: "Médio",   classes: "border-gold-400/40 bg-gold-400/10 text-gold-300",          dot: "bg-gold-400" },
  alto:    { label: "Alto",    classes: "border-orange-400/40 bg-orange-500/10 text-orange-300",     dot: "bg-orange-400" },
  critico: { label: "Crítico", classes: "border-red-400/40 bg-red-500/10 text-red-300",              dot: "bg-red-400" },
};
const RISCO_PESO = { baixo: 0, medio: 1, alto: 2, critico: 3 };

// Classificação automática de risco a partir do texto da ação/entidade/dados
function classificarRisco(texto = "") {
  const s = ("" + texto).toLowerCase();
  const tem = (...ks) => ks.some((k) => s.includes(k));
  if (
    tem("permiss", "perfil admin", "alterar_plano", "plano alterad", "licença removid", "licenca removid",
        "licença modific", "licenca modific", "tentativa", "suspeit", "config crít", "configuração crít") ||
    (tem("exclu", "remov", "excluir") && tem("usuári", "usuario", "perfil"))
  ) return "critico";
  if (tem("cancel", "fechar_caixa", "caixa fechad", "reabert", "abrir_caixa", "exclus", "excluir",
          "remov", "preço", "preco", "estoque", "pagamento", "valor financ", "financeir")) return "alto";
  if (tem("cadastro", "criar", "novo", "produto alterad", "cliente alterad", "editar", "cadastra",
          "licença ativ", "licenca ativ", "alterar_licenca", "alteração de licença", "atualiz")) return "medio";
  if (tem("login", "logout", "consulta", "visualiz", "acesso", "sessão", "sessao")) return "baixo";
  return "medio";
}

// Deriva dispositivo/navegador a partir do user-agent
function dispositivoDoUA(ua = "") {
  const s = ("" + ua).toLowerCase();
  let dispositivo = "Desktop";
  if (/mobile|iphone|android.*mobile/.test(s)) dispositivo = "Mobile";
  else if (/ipad|tablet/.test(s)) dispositivo = "Tablet";
  let navegador = "—";
  if (s.includes("edg")) navegador = "Edge";
  else if (s.includes("chrome")) navegador = "Chrome";
  else if (s.includes("firefox")) navegador = "Firefox";
  else if (s.includes("safari")) navegador = "Safari";
  return { dispositivo, navegador };
}

function resumoAuditoria(log) {
  if (log.resumoDados) return log.resumoDados;
  if (log.dadosNovos && log.dadosAnteriores && typeof log.dadosNovos === "object") {
    const campos = Object.keys(log.dadosNovos);
    return campos.map((k) => `${k} alterado de ${log.dadosAnteriores?.[k] ?? "—"} para ${log.dadosNovos[k]}`).join(" · ");
  }
  if (log.dados && typeof log.dados === "object") return Object.entries(log.dados).map(([k, v]) => `${k}: ${v}`).join(" · ");
  return "—";
}

function codigoAuditoria(log) {
  if (log.codigoEvento) return log.codigoEvento;
  const ano = (log.criadoEmISO ? new Date(log.criadoEmISO) : new Date()).getFullYear();
  const num = ("" + (log.id ?? "")).replace(/\D/g, "") || "0";
  return `EVT-${ano}-${num.padStart(6, "0").slice(-6)}`;
}

// Converte um registro do banco no modelo de exibição da Auditoria Gerencial
function mapearEvento(log, lojas = []) {
  const acaoTxt = AUDIT_ACAO[log.acao]?.l || log.acao || "Ação";
  const resumo = resumoAuditoria(log);
  const risco = log.nivelRisco && AUDIT_RISCO[log.nivelRisco]
    ? log.nivelRisco
    : classificarRisco(`${log.acao} ${acaoTxt} ${log.entidade} ${resumo}`);
  const dev = (log.dispositivo || log.navegador)
    ? { dispositivo: log.dispositivo || "—", navegador: log.navegador || "—" }
    : dispositivoDoUA(log.userAgent);
  const loja = lojas.find((l) => l.id === log.lojaId);
  return {
    id: log.id,
    codigo: codigoAuditoria(log),
    acaoKey: log.acao,
    acao: acaoTxt,
    risco,
    usuarioNome: log.usuarioNome || "—",
    usuarioEmail: log.usuarioEmail || "",
    perfil: log.usuarioPerfil || "—",
    entidade: log.entidade || "—",
    entidadeId: log.entidadeId,
    entidadeLabel: `${log.entidade || "—"}${log.entidadeId ? ` #${log.entidadeId}` : ""}`,
    resumo,
    dadosAnteriores: log.dadosAnteriores,
    dadosNovos: log.dadosNovos,
    origem: log.origem || "Sistema Web",
    ip: log.ipOrigem || "—",
    dispositivo: dev.dispositivo,
    navegador: dev.navegador,
    quandoISO: log.criadoEmISO,
    analisado: !!log.analisado,
    statusAnalise: log.statusAnalise || (log.analisado ? "Analisado" : "Pendente"),
    lojaNome: loja?.nome || "",
  };
}

