function fmtDataHora(iso) {
  if (!iso) return "—";
  return new Date(iso).toLocaleString("pt-BR", { day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" });
}

// Selo de risco colorido
function RiscoBadge({ risco }) {
  const r = AUDIT_RISCO[risco] || AUDIT_RISCO.medio;
  return (
    <span className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-0.5 text-[10px] font-bold ${r.classes}`}>
      <span className={`h-1.5 w-1.5 rounded-full ${r.dot}`} />{r.label}
    </span>
  );
}

// Card de indicador (KPI) da auditoria
function KpiCard({ titulo, valor, sub = null, delta = null, deltaTom = "good", icone, iconeTom = "gold" }) {
  const iconBg =
    iconeTom === "red" ? "border-red-400/30 bg-red-500/10 text-red-300"
    : iconeTom === "orange" ? "border-orange-400/30 bg-orange-500/10 text-orange-300"
    : iconeTom === "blue" ? "border-blue-400/30 bg-blue-500/10 text-blue-200"
    : iconeTom === "emerald" ? "border-emerald-400/30 bg-emerald-500/10 text-emerald-300"
    : "border-gold-400/30 bg-gold-400/10 text-gold-300";
  const up = delta != null && delta >= 0;
  const deltaCor = delta == null ? "" : (deltaTom === "bad" ? (up ? "text-red-400" : "text-emerald-400") : (up ? "text-emerald-400" : "text-red-400"));
  return (
    <div className="rounded-2xl border border-white/[0.07] bg-white/[0.03] p-4 shadow-lg shadow-black/20">
      <div className="flex items-start justify-between gap-3">
        <p className="text-[10px] font-bold uppercase tracking-widest text-slate-500">{titulo}</p>
        <span className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-full border [&>svg]:h-5 [&>svg]:w-5 ${iconBg}`}>{icone}</span>
      </div>
      <p className="page-title mt-2 truncate text-2xl font-bold text-white">{valor}</p>
      {delta != null
        ? <p className={`mt-1 text-[11px] font-semibold ${deltaCor}`}>{up ? "▲ +" : "▼ "}{Math.abs(delta)}% vs período anterior</p>
        : (sub && <p className="mt-1 truncate text-[11px] text-slate-500">{sub}</p>)}
    </div>
  );
}

function AuditoriaAdmin({ logs = [], lojas = [], onAtualizar = null, onMarcarAnalisado = null }) {
  const [busca, setBusca] = useState("");
  const [fAcao, setFAcao] = useState("todas");
  const [fEnt, setFEnt] = useState("todas");
  const [fUser, setFUser] = useState("todos");
  const [fRisco, setFRisco] = useState("todos");
  const [ini, setIni] = useState("");
  const [fim, setFim] = useState("");
  const [pagina, setPagina] = useState(1);
  const [porPagina, setPorPagina] = useState(10);
  const [ordCol, setOrdCol] = useState("quando");
  const [ordDir, setOrdDir] = useState("desc");
  const [selId, setSelId] = useState(null);
  const [atualizando, setAtualizando] = useState(false);
  const [erro, setErro] = useState(false);
  const [marcando, setMarcando] = useState(false);
  const [copiado, setCopiado] = useState(false);
  const [analisadosLocais, setAnalisadosLocais] = useState(() => new Set());
  const [ultimaAtt, setUltimaAtt] = useState(() => new Date());

  // Base: dados reais (mapeados) ou demonstração quando ainda não há registros
  const eventos = useMemo(() => {
    const base = (logs && logs.length) ? logs.map((l) => mapearEvento(l, lojas)) : AUDIT_DEMO;
    return base.map((e) => (analisadosLocais.has(e.id) ? { ...e, analisado: true, statusAnalise: "Analisado" } : e));
  }, [logs, lojas, analisadosLocais]);

  const acoes = useMemo(() => [...new Set(eventos.map((e) => e.acao))].sort(), [eventos]);
  const entidades = useMemo(() => [...new Set(eventos.map((e) => e.entidade).filter(Boolean))].sort(), [eventos]);
  const usuarios = useMemo(() => [...new Set(eventos.map((e) => e.usuarioNome).filter(Boolean))].sort(), [eventos]);
  const termo = busca.trim().toLowerCase();

  // Filtro completo (todos os critérios) — usado nos cards e na tabela
  const passaFiltrosBase = (e) => {
    if (fAcao !== "todas" && e.acao !== fAcao) return false;
    if (fEnt !== "todas" && e.entidade !== fEnt) return false;
    if (fUser !== "todos" && e.usuarioNome !== fUser) return false;
    if (fRisco !== "todos" && e.risco !== fRisco) return false;
    if (termo) {
      const alvo = `${e.usuarioNome} ${e.usuarioEmail} ${e.acao} ${e.entidadeLabel} ${e.ip} ${e.dispositivo} ${e.resumo} ${e.origem}`.toLowerCase();
      if (!alvo.includes(termo)) return false;
    }
    return true;
  };
  const noPeriodo = (e, a, b) => { const t = new Date(e.quandoISO).getTime(); return t >= a && t <= b; };

  const filtrados = useMemo(() => eventos.filter((e) => {
    if (!passaFiltrosBase(e)) return false;
    if (ini && new Date(e.quandoISO) < new Date(`${ini}T00:00:00`)) return false;
    if (fim && new Date(e.quandoISO) > new Date(`${fim}T23:59:59`)) return false;
    return true;
  }), [eventos, fAcao, fEnt, fUser, fRisco, termo, ini, fim]);

  // Ordenação
  const ordenados = useMemo(() => {
    const arr = [...filtrados];
    const dir = ordDir === "asc" ? 1 : -1;
    arr.sort((a, b) => {
      let va, vb;
      if (ordCol === "risco") { va = RISCO_PESO[a.risco]; vb = RISCO_PESO[b.risco]; }
      else if (ordCol === "acao") { va = a.acao; vb = b.acao; }
      else if (ordCol === "usuario") { va = a.usuarioNome; vb = b.usuarioNome; }
      else if (ordCol === "entidade") { va = a.entidade; vb = b.entidade; }
      else { va = new Date(a.quandoISO).getTime(); vb = new Date(b.quandoISO).getTime(); }
      if (va < vb) return -1 * dir;
      if (va > vb) return 1 * dir;
      return 0;
    });
    return arr;
  }, [filtrados, ordCol, ordDir]);

  // KPIs e variação vs período anterior ───────────────────────────
  const conta = (lista) => ({
    total: lista.length,
    logins: lista.filter((e) => e.acaoKey === "login" || /login/.test(e.acao.toLowerCase())).length,
    criticas: lista.filter((e) => e.risco === "critico").length,
    usuarios: new Set(lista.map((e) => e.usuarioNome)).size,
    suspeitas: lista.filter((e) => /tentativa|suspeit|falha|negad/.test(`${e.acao} ${e.resumo}`.toLowerCase())).length,
  });
  const kpis = useMemo(() => {
    const agora = Date.now();
    const fimW = fim ? new Date(`${fim}T23:59:59`).getTime() : agora;
    const iniW = ini ? new Date(`${ini}T00:00:00`).getTime() : (fimW - 15 * 864e5);
    const dur = Math.max(1, fimW - iniW);
    const semData = eventos.filter(passaFiltrosBase);
    const atual = conta(semData.filter((e) => noPeriodo(e, iniW, fimW)));
    const prev = conta(semData.filter((e) => noPeriodo(e, iniW - dur, iniW)));
    const pct = (c, p) => (p > 0 ? Math.round(((c - p) / p) * 100) : (c > 0 ? 100 : 0));
    const cur = conta(filtrados);
    const ultimo = ordenados.length ? [...ordenados].sort((a, b) => new Date(b.quandoISO) - new Date(a.quandoISO))[0] : null;
    return {
      total: cur.total,
      logins: cur.logins, dLogins: pct(atual.logins, prev.logins),
      criticas: cur.criticas, dCriticas: pct(atual.criticas, prev.criticas),
      usuarios: cur.usuarios, dUsuarios: pct(atual.usuarios, prev.usuarios),
      suspeitas: cur.suspeitas, dSuspeitas: pct(atual.suspeitas, prev.suspeitas),
      ultimo,
    };
  }, [eventos, filtrados, ordenados, fAcao, fEnt, fUser, fRisco, termo, ini, fim]);

  // Paginação
  const totalPaginas = Math.max(1, Math.ceil(ordenados.length / porPagina));
  useEffect(() => { setPagina(1); }, [fAcao, fEnt, fUser, fRisco, termo, ini, fim, porPagina, ordCol, ordDir]);
  const paginaAtual = Math.min(pagina, totalPaginas);
  const visiveis = ordenados.slice((paginaAtual - 1) * porPagina, paginaAtual * porPagina);
  const inicio = ordenados.length ? (paginaAtual - 1) * porPagina + 1 : 0;
  const fimReg = Math.min(paginaAtual * porPagina, ordenados.length);

  const selecionado = selId != null ? eventos.find((e) => e.id === selId) || null : null;

  // Ações ───────────────────────────────────────────────────────
  async function atualizar() {
    if (!onAtualizar) { setUltimaAtt(new Date()); return; }
    setAtualizando(true); setErro(false);
    try { await onAtualizar(); setUltimaAtt(new Date()); }
    catch { setErro(true); }
    finally { setAtualizando(false); }
  }
  function limpar() {
    setBusca(""); setFAcao("todas"); setFEnt("todas"); setFUser("todos"); setFRisco("todos");
    setIni(""); setFim(""); setPagina(1);
  }
  async function marcar(e) {
    setMarcando(true);
    try { if (onMarcarAnalisado) await onMarcarAnalisado(e.id); } catch { /* tolerante */ }
    setAnalisadosLocais((s) => new Set(s).add(e.id));
    setMarcando(false);
  }
  async function copiar(e) {
    const txt = [
      `Código: ${e.codigo}`, `Data/Hora: ${fmtDataHora(e.quandoISO)}`, `Risco: ${AUDIT_RISCO[e.risco]?.label}`,
      `Usuário: ${e.usuarioNome} (${e.perfil})`, `Ação: ${e.acao}`, `Entidade: ${e.entidadeLabel}`,
      `Dados: ${e.resumo}`, `Origem: ${e.origem}`, `IP: ${e.ip}`, `Dispositivo: ${e.dispositivo}`, `Navegador: ${e.navegador}`,
    ].join("\n");
    try { await navigator.clipboard.writeText(txt); setCopiado(true); setTimeout(() => setCopiado(false), 1500); } catch { /* sem permissão */ }
  }
  function exportar() {
    const cols = ["Código", "Risco", "Ação", "Usuário", "Perfil", "E-mail", "Entidade", "Dados", "Origem", "IP", "Dispositivo", "Navegador", "Quando", "Status"];
    const linhas = ordenados.map((e) => [e.codigo, AUDIT_RISCO[e.risco]?.label, e.acao, e.usuarioNome, e.perfil, e.usuarioEmail, e.entidadeLabel, e.resumo, e.origem, e.ip, e.dispositivo, e.navegador, fmtDataHora(e.quandoISO), e.statusAnalise]);
    const csv = [cols, ...linhas].map((r) => r.map((c) => `"${String(c ?? "").replace(/"/g, '""')}"`).join(";")).join("\n");
    const blob = new Blob(["﻿" + csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = `auditoria_${new Date().toISOString().slice(0, 10)}.csv`; a.click();
    URL.revokeObjectURL(url);
  }
  function ordenar(col) {
    if (ordCol === col) setOrdDir((d) => (d === "asc" ? "desc" : "asc"));
    else { setOrdCol(col); setOrdDir(col === "quando" ? "desc" : "asc"); }
  }

  const inp = "rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-2.5 text-sm text-white outline-none focus:border-gold-400/60";
  const Seta = ({ col }) => (
    <span className={`ml-1 inline-block text-[9px] transition ${ordCol === col ? "text-gold-300" : "text-slate-600"}`}>{ordCol === col ? (ordDir === "asc" ? "▲" : "▼") : "↕"}</span>
  );
  const Th = ({ children, col = null, right = false }) => (
    <th className={`whitespace-nowrap px-3 py-3 text-[10px] font-bold uppercase tracking-widest text-slate-400 ${right ? "text-right" : "text-left"}`}>
      {col ? <button onClick={() => ordenar(col)} className="inline-flex items-center hover:text-gold-300">{children}<Seta col={col} /></button> : children}
    </th>
  );

  return (
    <main className="space-y-5">
      {/* ── Cabeçalho ─────────────────────────────────────── */}
      <div className="rounded-[2rem] border border-white/10 bg-blue-950/40 p-5">
        <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
          <div className="flex items-start gap-3">
            <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl border border-gold-400/40 bg-gold-400/10 text-gold-300 [&>svg]:h-6 [&>svg]:w-6"><IcoEscudo /></span>
            <div className="min-w-0">
              <h3 className="page-title text-xl font-bold tracking-tight text-white sm:text-2xl">Auditoria Gerencial</h3>
              <p className="mt-1 max-w-2xl text-sm leading-6 text-slate-400">Acompanhe acessos, alterações, exclusões, caixa, plano, licença e permissões em tempo real.</p>
            </div>
          </div>
          <div className="flex flex-col items-stretch gap-2 sm:items-end">
            <div className="flex flex-wrap gap-2 sm:justify-end">
              <button onClick={atualizar} disabled={atualizando}
                className="inline-flex items-center justify-center gap-2 rounded-2xl border border-white/10 bg-white/[0.06] px-4 py-2.5 text-sm font-bold text-white transition hover:bg-white/10 disabled:opacity-50 [&>svg]:h-4 [&>svg]:w-4">
                <span className={atualizando ? "animate-spin" : ""}><IcoRefresh /></span> Atualizar dados
              </button>
              <button onClick={exportar}
                className="inline-flex items-center justify-center gap-2 rounded-2xl bg-gold-400 px-4 py-2.5 text-sm font-bold text-blue-950 shadow-lg shadow-gold-900/30 transition hover:bg-gold-300 [&>svg]:h-4 [&>svg]:w-4">
                <IcoDownload /> Exportar relatório
              </button>
            </div>
            <p className="text-[11px] text-slate-500">Última atualização: {fmtDataHora(ultimaAtt.toISOString())}</p>
          </div>
        </div>
      </div>

      {/* ── KPIs ──────────────────────────────────────────── */}
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6">
        <KpiCard titulo="Total de eventos" valor={kpis.total} sub="No período selecionado" icone={<IcoDoc />} iconeTom="gold" />
        <KpiCard titulo="Logins realizados" valor={kpis.logins} delta={kpis.dLogins} deltaTom="good" icone={<IcoUserAud />} iconeTom="blue" />
        <KpiCard titulo="Ações críticas" valor={kpis.criticas} delta={kpis.dCriticas} deltaTom="bad" icone={<IcoAlertaEsc />} iconeTom="red" />
        <KpiCard titulo="Usuários ativos" valor={kpis.usuarios} delta={kpis.dUsuarios} deltaTom="good" icone={<IcoUsersAud />} iconeTom="gold" />
        <KpiCard titulo="Tentativas suspeitas" valor={kpis.suspeitas} delta={kpis.dSuspeitas} deltaTom="bad" icone={<IcoTriangulo />} iconeTom="orange" />
        <KpiCard titulo="Última ação" valor={kpis.ultimo ? `${kpis.ultimo.usuarioNome.split(" ")[0]} • ${kpis.ultimo.acao}` : "—"} sub={kpis.ultimo ? fmtDataHora(kpis.ultimo.quandoISO) : "Sem eventos"} icone={<IcoRelogioAud />} iconeTom="emerald" />
      </div>

      {/* ── Filtros ───────────────────────────────────────── */}
      <div className="rounded-[2rem] border border-white/10 bg-white/[0.04] p-5">
        <div className="grid gap-3 lg:grid-cols-[2fr_1fr_1fr_1fr_1fr]">
          <div className="relative">
            <span className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-slate-500"><IconBusca /></span>
            <input value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar por usuário, e-mail, ação, entidade, IP ou dados alterados..." className={`${inp} w-full pl-11`} />
          </div>
          <select value={fAcao} onChange={(e) => setFAcao(e.target.value)} className={inp}><option value="todas">Todas as ações</option>{acoes.map((a) => <option key={a} value={a}>{a}</option>)}</select>
          <select value={fEnt} onChange={(e) => setFEnt(e.target.value)} className={inp}><option value="todas">Todas as entidades</option>{entidades.map((e) => <option key={e} value={e}>{e}</option>)}</select>
          <select value={fUser} onChange={(e) => setFUser(e.target.value)} className={inp}><option value="todos">Todos os usuários</option>{usuarios.map((u) => <option key={u} value={u}>{u}</option>)}</select>
          <select value={fRisco} onChange={(e) => setFRisco(e.target.value)} className={inp}><option value="todos">Todos os riscos</option>{Object.entries(AUDIT_RISCO).map(([k, v]) => <option key={k} value={k}>{v.label}</option>)}</select>
        </div>
        <div className="mt-3 grid gap-3 sm:grid-cols-2 lg:grid-cols-[1fr_1fr_auto_auto]">
          <label className="flex flex-col gap-1"><span className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Data inicial</span><input type="date" value={ini} onChange={(e) => setIni(e.target.value)} className={inp} /></label>
          <label className="flex flex-col gap-1"><span className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Data final</span><input type="date" value={fim} onChange={(e) => setFim(e.target.value)} className={inp} /></label>
          <button onClick={() => setPagina(1)} className="self-end rounded-2xl bg-gold-400 px-5 py-2.5 text-sm font-bold text-blue-950 transition hover:bg-gold-300">Aplicar filtros</button>
          <button onClick={limpar} className="self-end rounded-2xl border border-white/10 bg-white/[0.06] px-5 py-2.5 text-sm font-bold text-slate-300 transition hover:bg-white/10">Limpar</button>
        </div>
      </div>

      {/* ── Tabela / cards ────────────────────────────────── */}
      <div className="overflow-hidden rounded-[2rem] border border-white/10 bg-white/[0.04]">
        {erro ? (
          <div className="px-5 py-12 text-center">
            <p className="text-sm font-semibold text-red-300">Não foi possível carregar os registros de auditoria.</p>
            <button onClick={atualizar} className="mt-3 rounded-2xl border border-white/10 bg-white/[0.06] px-4 py-2 text-sm font-bold text-slate-200 hover:bg-white/10">Tentar novamente</button>
          </div>
        ) : atualizando ? (
          <div className="space-y-2 p-5">{Array.from({ length: 6 }).map((_, i) => <div key={i} className="h-12 animate-pulse rounded-xl bg-white/[0.04]" />)}</div>
        ) : ordenados.length === 0 ? (
          <EmptyState icone={<IcoEscudo />} titulo="Nenhum registro de auditoria encontrado para os filtros selecionados." dica="Ajuste os filtros, o período ou limpe a busca para ver mais eventos." />
        ) : (
          <>
            {/* Desktop / tablet — tabela com rolagem horizontal */}
            <div className="hidden overflow-x-auto lg:block">
              <table className="w-full min-w-[1120px] border-collapse text-sm">
                <thead className="sticky top-0 z-10 bg-blue-950/80 backdrop-blur">
                  <tr className="border-b border-white/10">
                    <Th col="risco">Risco</Th>
                    <Th col="acao">Ação</Th>
                    <Th col="usuario">Usuário</Th>
                    <Th>Perfil</Th>
                    <Th col="entidade">Entidade</Th>
                    <Th>Dados da alteração</Th>
                    <Th>Origem</Th>
                    <Th>IP / Dispositivo</Th>
                    <Th col="quando">Quando</Th>
                    <Th right>Ações</Th>
                  </tr>
                </thead>
                <tbody>
                  {visiveis.map((e) => (
                    <tr key={e.id} className={`border-b border-white/5 transition hover:bg-white/[0.04] ${e.risco === "critico" ? "bg-red-500/[0.04]" : ""}`}>
                      <td className="px-3 py-3"><RiscoBadge risco={e.risco} /></td>
                      <td className="whitespace-nowrap px-3 py-3 font-semibold text-white">{e.acao}</td>
                      <td className="whitespace-nowrap px-3 py-3 text-slate-200">{e.usuarioNome}</td>
                      <td className="whitespace-nowrap px-3 py-3 text-slate-400">{e.perfil}</td>
                      <td className="whitespace-nowrap px-3 py-3 text-slate-300">{e.entidadeLabel}</td>
                      <td className="max-w-[240px] truncate px-3 py-3 text-slate-400" title={e.resumo}>{e.resumo}</td>
                      <td className="whitespace-nowrap px-3 py-3 text-slate-400">{e.origem}</td>
                      <td className="whitespace-nowrap px-3 py-3 text-slate-400">{e.ip} • {e.dispositivo}</td>
                      <td className="whitespace-nowrap px-3 py-3 text-[12px] text-slate-400">{fmtDataHora(e.quandoISO)}</td>
                      <td className="whitespace-nowrap px-3 py-3 text-right">
                        <button onClick={() => setSelId(e.id)} className="rounded-xl border border-gold-400/30 bg-gold-400/10 px-3 py-1.5 text-xs font-bold text-gold-300 transition hover:bg-gold-400/20">Ver detalhes</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Mobile — cards */}
            <div className="space-y-2 p-3 lg:hidden">
              {visiveis.map((e) => (
                <div key={e.id} className={`rounded-2xl border p-3 ${e.risco === "critico" ? "border-red-400/20 bg-red-500/[0.05]" : "border-white/10 bg-slate-950/40"}`}>
                  <div className="flex items-center justify-between gap-2">
                    <RiscoBadge risco={e.risco} />
                    <span className="text-[11px] text-slate-500">{fmtDataHora(e.quandoISO)}</span>
                  </div>
                  <p className="mt-2 font-bold text-white">{e.acao}</p>
                  <p className="text-[12px] text-slate-400">{e.usuarioNome} • {e.perfil} • {e.entidadeLabel}</p>
                  <p className="mt-1 line-clamp-2 text-[12px] text-slate-500">{e.resumo}</p>
                  <div className="mt-2 flex items-center justify-between gap-2">
                    <span className="truncate text-[11px] text-slate-500">{e.origem} • {e.ip} • {e.dispositivo}</span>
                    <button onClick={() => setSelId(e.id)} className="shrink-0 rounded-xl border border-gold-400/30 bg-gold-400/10 px-3 py-1.5 text-xs font-bold text-gold-300">Ver detalhes</button>
                  </div>
                </div>
              ))}
            </div>

            {/* Paginação */}
            <div className="flex flex-col items-center justify-between gap-3 border-t border-white/10 px-5 py-4 lg:flex-row">
              <div className="flex items-center gap-2 text-xs text-slate-400">
                <span>Exibir</span>
                <select value={porPagina} onChange={(e) => setPorPagina(Number(e.target.value))} className="rounded-xl border border-white/10 bg-slate-950/70 px-2 py-1.5 text-xs text-white outline-none focus:border-gold-400/60">
                  {[10, 25, 50, 100].map((n) => <option key={n} value={n}>{n}</option>)}
                </select>
                <span>por página</span>
              </div>
              <p className="text-xs text-slate-400"><b className="text-white">{inicio}–{fimReg}</b> de <b className="text-white">{ordenados.length}</b> eventos</p>
              <div className="flex flex-wrap items-center justify-center gap-1">
                <button disabled={paginaAtual <= 1} onClick={() => setPagina(paginaAtual - 1)} className="min-w-9 rounded-xl border border-white/10 bg-white/[0.06] px-3 py-2 text-xs font-black text-slate-300 transition hover:bg-white/10 disabled:opacity-30">‹</button>
                {(() => {
                  const nums = []; const add = (n) => { if (n >= 1 && n <= totalPaginas && !nums.includes(n)) nums.push(n); };
                  add(1); for (let i = paginaAtual - 1; i <= paginaAtual + 1; i++) add(i); add(totalPaginas); nums.sort((a, b) => a - b);
                  return nums.map((n, i) => (
                    <span key={n} className="flex items-center gap-1">
                      {i > 0 && n - nums[i - 1] > 1 && <span className="px-1 text-slate-600">…</span>}
                      <button onClick={() => setPagina(n)} className={`min-w-9 rounded-xl px-3 py-2 text-xs font-black transition ${n === paginaAtual ? "bg-gold-400 text-blue-950" : "border border-white/10 bg-white/[0.06] text-slate-300 hover:bg-white/10"}`}>{n}</button>
                    </span>
                  ));
                })()}
                <button disabled={paginaAtual >= totalPaginas} onClick={() => setPagina(paginaAtual + 1)} className="min-w-9 rounded-xl border border-white/10 bg-white/[0.06] px-3 py-2 text-xs font-black text-slate-300 transition hover:bg-white/10 disabled:opacity-30">›</button>
              </div>
            </div>
          </>
        )}
      </div>

      {/* ── Rodapé gerencial ──────────────────────────────── */}
      {!erro && ordenados.length > 0 && (
        <div className="flex items-start gap-3 rounded-[2rem] border border-white/10 bg-white/[0.04] p-5">
          <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full border border-gold-400/30 bg-gold-400/10 text-gold-300 [&>svg]:h-5 [&>svg]:w-5"><IcoInfoAud /></span>
          <p className="text-sm leading-6 text-slate-400">
            Foram encontrados <b className="text-gold-300">{ordenados.length}</b> evento(s){(ini || fim) ? ` no período de ${ini ? new Date(`${ini}T00:00:00`).toLocaleDateString("pt-BR") : "início"} a ${fim ? new Date(`${fim}T00:00:00`).toLocaleDateString("pt-BR") : "hoje"}` : ""}.
            {" "}Deste total, <b className="text-red-400">{kpis.criticas}</b> ação(ões) foram classificadas como <b className="text-red-300">críticas</b> e precisam de análise gerencial.
          </p>
        </div>
      )}

      {/* ── Painel lateral de detalhes ────────────────────── */}
      {selecionado && (
        <div className="fixed inset-0 z-50 flex justify-end">
          <button aria-label="Fechar" onClick={() => setSelId(null)} className="absolute inset-0 bg-black/60 backdrop-blur-sm" />
          <aside className="relative flex h-full w-full flex-col border-l border-white/10 bg-blue-950 shadow-2xl sm:max-w-md">
            <div className="flex items-center justify-between gap-3 border-b border-white/10 px-5 py-4">
              <div className="flex items-center gap-2.5">
                <h4 className="page-title text-lg font-bold text-white">Detalhes da Auditoria</h4>
                <RiscoBadge risco={selecionado.risco} />
              </div>
              <button onClick={() => setSelId(null)} className="flex h-9 w-9 items-center justify-center rounded-full border border-white/10 bg-white/[0.06] text-slate-300 hover:bg-white/10 [&>svg]:h-4 [&>svg]:w-4"><IcoFechar /></button>
            </div>
            <div className="flex-1 overflow-y-auto px-5 py-4">
              <dl className="divide-y divide-white/5">
                {[
                  ["Código do evento", selecionado.codigo],
                  ["Data e hora", fmtDataHora(selecionado.quandoISO)],
                  ["Usuário responsável", selecionado.usuarioNome],
                  ["Perfil", selecionado.perfil],
                  ["Ação", selecionado.acao],
                  ["Entidade", selecionado.entidadeLabel],
                  ["Dados anteriores", selecionado.dadosAnteriores ? Object.entries(selecionado.dadosAnteriores).map(([k, v]) => `${k}: ${v}`).join(", ") : "—"],
                  ["Dados novos", selecionado.dadosNovos ? Object.entries(selecionado.dadosNovos).map(([k, v]) => `${k}: ${v}`).join(", ") : "—"],
                  ["Resumo", selecionado.resumo],
                  ["IP", selecionado.ip],
                  ["Dispositivo", selecionado.dispositivo],
                  ["Navegador", selecionado.navegador],
                  ["Origem", selecionado.origem],
                ].map(([label, valor]) => (
                  <div key={label} className="grid grid-cols-[130px_1fr] gap-3 py-2.5">
                    <dt className="text-[11px] font-semibold uppercase tracking-wide text-slate-500">{label}</dt>
                    <dd className="break-words text-sm text-white">{valor}</dd>
                  </div>
                ))}
                <div className="grid grid-cols-[130px_1fr] gap-3 py-2.5">
                  <dt className="text-[11px] font-semibold uppercase tracking-wide text-slate-500">Status da análise</dt>
                  <dd>
                    {selecionado.analisado
                      ? <span className="inline-flex items-center gap-1 rounded-full border border-emerald-400/30 bg-emerald-500/10 px-2.5 py-0.5 text-[10px] font-bold text-emerald-300">Analisado</span>
                      : <span className="inline-flex items-center gap-1 rounded-full border border-gold-400/40 bg-gold-400/10 px-2.5 py-0.5 text-[10px] font-bold text-gold-300">Pendente</span>}
                  </dd>
                </div>
              </dl>
            </div>
            <div className="flex flex-col gap-2 border-t border-white/10 px-5 py-4 sm:flex-row">
              <button onClick={() => marcar(selecionado)} disabled={selecionado.analisado || marcando}
                className="flex-1 rounded-2xl bg-gold-400 px-4 py-2.5 text-sm font-bold text-blue-950 transition hover:bg-gold-300 disabled:opacity-40">
                {selecionado.analisado ? "Analisado" : marcando ? "Salvando…" : "Marcar como analisado"}
              </button>
              <button onClick={() => copiar(selecionado)} className="flex items-center justify-center gap-2 rounded-2xl border border-white/10 bg-white/[0.06] px-4 py-2.5 text-sm font-bold text-slate-200 transition hover:bg-white/10 [&>svg]:h-4 [&>svg]:w-4"><IcoCopiar /> {copiado ? "Copiado!" : "Copiar registro"}</button>
              <button onClick={() => setSelId(null)} className="rounded-2xl border border-white/10 bg-white/[0.06] px-4 py-2.5 text-sm font-bold text-slate-200 transition hover:bg-white/10">Fechar</button>
            </div>
          </aside>
        </div>
      )}
    </main>
  );
}

// ── Taxa de serviço — parametrização por empresa ──
// TODO: mover para coluna própria em `tab_lojas` (JSONB) quando existir
// migration para isso; por ora, persistida localmente por empresa (mesmo
// padrão dos favoritos), sem exigir alteração de banco.
const TAXA_SERVICO_DEFAULT = { enabled: true, percent: 10, chargingRule: "opcional", partialStrategy: "proporcional_itens" };
function lerConfigTaxaServico(lojaId) {
  try { return { ...TAXA_SERVICO_DEFAULT, ...JSON.parse(localStorage.getItem(`pedidoPrime:taxaServico:${lojaId || "geral"}`) || "{}") }; }
  catch { return TAXA_SERVICO_DEFAULT; }
}
function salvarConfigTaxaServico(lojaId, cfg) {
  try { localStorage.setItem(`pedidoPrime:taxaServico:${lojaId || "geral"}`, JSON.stringify(cfg)); } catch {}
}

function ConfiguracoesAdmin({ lojaInfo }) {
  const [taxaCfg, setTaxaCfg] = useState(() => lerConfigTaxaServico(lojaInfo?.id));
  function atualizarTaxa(patch) {
    setTaxaCfg((cur) => { const novo = { ...cur, ...patch }; salvarConfigTaxaServico(lojaInfo?.id, novo); return novo; });
  }
  return (
    <main className="space-y-5">
      <PageHeader
        icone={<IconConfig />}
        titulo="Configurações"
        descricao="Preferências do sistema. As alterações ficam salvas neste aparelho."
      />

      {/* Taxa de serviço */}
      <div className="rounded-[2rem] border border-white/10 bg-white/[0.04] p-6">
        <h3 className="page-title text-base font-bold tracking-tight text-white">Taxa de serviço</h3>
        <p className="mt-1 text-sm text-slate-400">Configure como a taxa de serviço será sugerida/cobrada no caixa. A regra definida aqui será aplicada automaticamente no fechamento.</p>
        <label className="mt-4 flex items-center justify-between gap-2 cursor-pointer">
          <span className="text-sm font-bold text-slate-200">Cobrar taxa de serviço</span>
          <input type="checkbox" checked={taxaCfg.enabled} onChange={(e) => atualizarTaxa({ enabled: e.target.checked })} className="h-5 w-5 accent-gold-400" />
        </label>
        <label className="mt-3 block">
          <span className="mb-1 block text-xs font-bold uppercase tracking-widest text-slate-500">Percentual da taxa</span>
          <input type="number" min="0" max="100" step="1" value={taxaCfg.percent}
            onChange={(e) => atualizarTaxa({ percent: Math.max(0, Number(e.target.value) || 0) })}
            className="w-32 rounded-xl border border-white/10 bg-slate-950/70 px-3 py-2 text-white outline-none focus:border-gold-400/60" />
        </label>
        <div className="mt-3">
          <span className="mb-1.5 block text-xs font-bold uppercase tracking-widest text-slate-500">Regra de cobrança</span>
          <div className="flex flex-wrap gap-2">
            {[["fixa", "Fixa"], ["opcional", "Opcional"], ["nao_cobrar", "Não cobrar"]].map(([id, label]) => (
              <FilterChip key={id} size="sm" selected={taxaCfg.chargingRule === id} label={label} onClick={() => atualizarTaxa({ chargingRule: id })} />
            ))}
          </div>
        </div>
        <div className="mt-3">
          <span className="mb-1.5 block text-xs font-bold uppercase tracking-widest text-slate-500">Estratégia no pagamento parcial</span>
          <div className="flex flex-wrap gap-2">
            {[["proporcional_itens", "Proporcional aos itens"], ["proporcional_valor", "Proporcional ao valor"], ["manual", "Manual"], ["nao_ratear", "Não ratear"]].map(([id, label]) => (
              <FilterChip key={id} size="sm" selected={taxaCfg.partialStrategy === id} label={label} onClick={() => atualizarTaxa({ partialStrategy: id })} />
            ))}
          </div>
        </div>
      </div>
    </main>
  );
}

function PagamentoAdmin({ formasPagamento, addFormaPagamento, toggleFormaPagamento, removerFormaPagamento, editarFormaPagamento }) {
  const [excluir, setExcluir]   = useState(null);
  const [criando, setCriando]   = useState(false);
  const [editando, setEditando] = useState(null);
  const [busca, setBusca]       = useState("");
  const labelTipo = (id) => TIPOS_PAGAMENTO.find((t) => t.id === id)?.label || id;

  const termo = busca.trim().toLowerCase();
  const filtradas = termo ? formasPagamento.filter((f) => `${f.nome} ${labelTipo(f.tipo)}`.toLowerCase().includes(termo)) : formasPagamento;

  async function salvarNova(forma) {
    const ok = await addFormaPagamento({ ...forma, permiteTroco: forma.tipo === "dinheiro" ? true : forma.permiteTroco });
    if (ok) setCriando(false);
  }
  async function salvarEdicao(dados) {
    const ok = await editarFormaPagamento(editando.id, { ...dados, permiteTroco: dados.tipo === "dinheiro" ? true : dados.permiteTroco });
    if (ok) setEditando(null);
  }

  return (
    <main className="space-y-5">
      {/* ── Cabeçalho padronizado (PageHeader) ─────────────── */}
      <PageHeader
        icone={<IconPagamento />}
        titulo="Formas de Pagamento"
        descricao="Defina como o caixa recebe os pagamentos: dinheiro, cartões, PIX e outras formas."
        indicadores={[
          { valor: formasPagamento.length, rotulo: formasPagamento.length === 1 ? "forma" : "formas" },
          { valor: formasPagamento.filter((f) => f.active !== false).length, rotulo: "ativas", tom: "ok" },
          { valor: formasPagamento.filter((f) => f.active === false).length, rotulo: "inativas" },
        ]}
        acao={<PrimeButton onClick={() => setCriando(true)}><span className="text-lg leading-none">+</span> Cadastrar forma</PrimeButton>}
      />

      {/* Busca + lista */}
      <div className="rounded-[2rem] border border-white/10 bg-white/[0.04] p-5">
        <div className="relative mb-4">
          <span className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-slate-500"><IconBusca /></span>
          <input value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar forma de pagamento..."
            className="w-full rounded-2xl border border-white/10 bg-slate-950/70 py-3 pl-11 pr-4 text-sm text-white outline-none focus:border-gold-400/60" />
        </div>
        <div className="space-y-2">
          {formasPagamento.length === 0 && (
            <div className="py-10 text-center">
              <p className="text-sm text-slate-500">Nenhuma forma cadastrada.</p>
              <button onClick={() => setCriando(true)} className="mt-3 rounded-2xl border border-blue-400/30 bg-blue-500/15 px-4 py-2 text-xs font-black text-blue-200 hover:bg-blue-500/25">+ Cadastrar forma</button>
            </div>
          )}
          {formasPagamento.length > 0 && filtradas.length === 0 && <p className="py-6 text-center text-sm text-slate-500">Nenhuma forma encontrada.</p>}
          {filtradas.map((f) => (
            <div key={f.id}
              onClick={() => setEditando(f)}
              className="group flex cursor-pointer items-center gap-3 rounded-3xl border border-white/10 bg-slate-950/40 p-3 transition hover:border-blue-400/30 hover:bg-white/[0.06]">
              <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-2xl bg-white/[0.06] text-lg group-hover:bg-blue-500/15 transition">💳</span>
              <div className="min-w-0 flex-1">
                <p className="font-black text-white truncate">{f.nome}</p>
                <p className="text-xs text-slate-400">{labelTipo(f.tipo)}{f.permiteTroco ? " • permite troco" : ""}</p>
              </div>
              <span className="shrink-0 text-xs text-slate-600 group-hover:text-blue-400 transition">✏️ Editar</span>
              <button onClick={(e) => { e.stopPropagation(); toggleFormaPagamento(f.id); }}
                className={`shrink-0 rounded-full px-3 py-1.5 text-xs font-black ${f.active !== false ? "bg-emerald-500 text-white" : "bg-slate-700 text-slate-200"}`}>
                {f.active !== false ? "Ativo" : "Inativo"}
              </button>
              <button onClick={(e) => { e.stopPropagation(); setExcluir(f); }}
                title="Excluir" className="shrink-0 rounded-xl border border-red-400/20 bg-red-500/10 px-3 py-1.5 text-xs font-black text-red-300 hover:bg-red-500/20">
                🗑️
              </button>
            </div>
          ))}
        </div>
      </div>

      {criando && <FormaPagamentoCadastroModal onSalvar={salvarNova} onFechar={() => setCriando(false)} />}
      {editando && (
        <FormaPagamentoEditModal
          forma={editando}
          onSalvar={salvarEdicao}
          onToggle={() => { toggleFormaPagamento(editando.id); setEditando((f) => f ? { ...f, active: f.active === false ? true : false } : f); }}
          onFechar={() => setEditando(null)}
        />
      )}
      {excluir && (
        <ConfirmModal titulo="Excluir forma de pagamento?"
          mensagem={`Deseja excluir "${excluir.nome}"? Esta ação não pode ser desfeita. (Dica: você pode apenas inativar.)`}
          confirmar="Sim, excluir"
          onConfirmar={() => { removerFormaPagamento(excluir.id); setExcluir(null); }}
          onCancelar={() => setExcluir(null)} />
      )}
    </main>
  );
}

// Modal de edição de forma de pagamento
function FormaPagamentoEditModal({ forma, onSalvar, onToggle, onFechar }) {
  const [f, setF] = useState({ nome: forma.nome, tipo: forma.tipo || "outro", permiteTroco: !!forma.permiteTroco });
  const inp = "w-full rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-3 text-white outline-none focus:border-gold-400/60 placeholder:text-slate-600";
  const lbl = "mb-1 block text-xs font-bold uppercase tracking-widest text-slate-500";
  const valido = f.nome.trim().length > 0;
  const ativa = forma.active !== false;
  const alterado = f.nome.trim() !== forma.nome || f.tipo !== (forma.tipo || "outro") || f.permiteTroco !== !!forma.permiteTroco;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/75 backdrop-blur-sm p-4" onClick={onFechar}>
      <div onClick={(e) => e.stopPropagation()} className="flex w-full max-w-md flex-col overflow-hidden rounded-[2rem] border border-white/10 bg-slate-900 shadow-2xl">
        {/* Header */}
        <div className="flex items-center justify-between border-b border-white/10 px-6 py-4">
          <div className="flex items-center gap-2">
            <span className="flex h-9 w-9 items-center justify-center rounded-2xl bg-blue-500/15 text-lg">💳</span>
            <h2 className="text-lg font-black text-white">Editar forma de pagamento</h2>
          </div>
          <button onClick={onFechar} className="rounded-2xl border border-white/10 bg-white/[0.08] px-4 py-2 text-sm font-black text-slate-300 hover:bg-white/20">✕</button>
        </div>

        <div className="px-6 py-5 space-y-4">
          {/* Nome */}
          <div>
            <span className={lbl}>Nome *</span>
            <input autoFocus value={f.nome} onChange={(e) => setF({ ...f, nome: e.target.value })}
              placeholder="Ex.: Vale Refeição, Ticket..." className={inp} />
          </div>

          {/* Tipo */}
          <div>
            <span className={lbl}>Tipo</span>
            <select value={f.tipo} onChange={(e) => setF({ ...f, tipo: e.target.value })} className={inp}>
              {TIPOS_PAGAMENTO.map((t) => <option key={t.id} value={t.id}>{t.label}</option>)}
            </select>
          </div>

          {/* Troco */}
          <label className="flex items-center gap-2 rounded-2xl border border-white/10 bg-slate-950/40 px-4 py-3 text-sm text-slate-300 cursor-pointer hover:bg-white/[0.04] transition">
            <input type="checkbox" checked={f.tipo === "dinheiro" || f.permiteTroco}
              disabled={f.tipo === "dinheiro"}
              onChange={(e) => setF({ ...f, permiteTroco: e.target.checked })}
              className="accent-blue-500" />
            Permite troco {f.tipo === "dinheiro" && <span className="text-slate-500">(dinheiro sempre permite)</span>}
          </label>

          {/* Status */}
          <div className="flex items-center justify-between rounded-2xl border border-white/10 bg-white/[0.04] px-4 py-3">
            <div>
              <p className="text-sm font-black text-white">Status</p>
              <p className="text-xs text-slate-400">{ativa ? "Disponível na tela do caixa" : "Oculta na tela do caixa"}</p>
            </div>
            <button onClick={onToggle}
              className={`shrink-0 rounded-full px-4 py-2 text-sm font-black transition ${ativa ? "bg-emerald-500 text-white hover:bg-emerald-400" : "bg-slate-700 text-slate-200 hover:bg-slate-600"}`}>
              {ativa ? "✅ Ativo" : "⏸ Inativo"}
            </button>
          </div>
        </div>

        {/* Rodapé */}
        <div className="shrink-0 border-t border-white/10 px-6 py-4 flex gap-3">
          <button onClick={onFechar} className="flex-1 rounded-2xl border border-white/10 bg-white/[0.06] py-3.5 text-sm font-black text-slate-300 hover:bg-white/10">Cancelar</button>
          <button onClick={() => onSalvar(f)} disabled={!valido || !alterado}
            className="flex-[2] rounded-2xl bg-blue-500 py-3.5 text-sm font-black text-white hover:bg-blue-400 transition active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed">
            💾 Salvar alterações
          </button>
        </div>
      </div>
    </div>
  );
}

// Modal de cadastro de forma de pagamento (mesmo padrão dos demais)
function FormaPagamentoCadastroModal({ onSalvar, onFechar }) {
  const [form, setForm] = useState({ nome: "", tipo: "outro", permiteTroco: false });
  const inp = "w-full rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-3 text-white outline-none focus:border-gold-400/60 placeholder:text-slate-600";
  const lbl = "mb-1 block text-xs font-bold uppercase tracking-widest text-slate-500";
  const valido = form.nome.trim().length > 0;
  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/75 backdrop-blur-sm p-4" onClick={onFechar}>
      <div onClick={(e) => e.stopPropagation()} className="flex w-full max-w-md flex-col overflow-hidden rounded-[2rem] border border-white/10 bg-slate-900 shadow-2xl">
        <div className="flex items-center justify-between border-b border-white/10 px-6 py-4">
          <div className="flex items-center gap-2">
            <span className="flex h-9 w-9 items-center justify-center rounded-2xl bg-blue-500/15 text-lg">💳</span>
            <h2 className="text-lg font-black text-white">Nova forma de pagamento</h2>
          </div>
          <button onClick={onFechar} className="rounded-2xl border border-white/10 bg-white/[0.08] px-4 py-2 text-sm font-black text-slate-300 hover:bg-white/20">✕</button>
        </div>
        <div className="px-6 py-5 space-y-3">
          <div>
            <span className={lbl}>Nome *</span>
            <input autoFocus value={form.nome} onChange={(e) => setForm({ ...form, nome: e.target.value })}
              onKeyDown={(e) => { if (e.key === "Enter" && valido) onSalvar(form); }}
              placeholder="Ex.: Vale Refeição, Ticket..." className={inp} />
          </div>
          <div>
            <span className={lbl}>Tipo</span>
            <select value={form.tipo} onChange={(e) => setForm({ ...form, tipo: e.target.value })} className={inp}>
              {TIPOS_PAGAMENTO.map((t) => <option key={t.id} value={t.id}>{t.label}</option>)}
            </select>
          </div>
          <label className="flex items-center gap-2 rounded-2xl border border-white/10 bg-slate-950/40 px-4 py-3 text-sm text-slate-300">
            <input type="checkbox" checked={form.tipo === "dinheiro" || form.permiteTroco}
              disabled={form.tipo === "dinheiro"}
              onChange={(e) => setForm({ ...form, permiteTroco: e.target.checked })} />
            Permite troco {form.tipo === "dinheiro" && <span className="text-slate-500">(dinheiro sempre permite)</span>}
          </label>
        </div>
        <div className="shrink-0 border-t border-white/10 px-6 py-4 flex gap-3">
          <button onClick={onFechar} className="flex-1 rounded-2xl border border-white/10 bg-white/[0.06] py-3.5 text-sm font-black text-slate-300 hover:bg-white/10">Cancelar</button>
          <button onClick={() => onSalvar(form)} disabled={!valido}
            className="flex-[2] rounded-2xl bg-blue-500 py-3.5 text-sm font-black text-white hover:bg-blue-400 transition active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed">
            + Cadastrar forma
          </button>
        </div>
      </div>
    </div>
  );
}

// Modal de confirmação reutilizável (exclusões)
function ConfirmModal({ titulo, mensagem, confirmar, onConfirmar, onCancelar, perigo = true }) {
  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/75 backdrop-blur-sm p-4" onClick={onCancelar}>
      <div onClick={(e) => e.stopPropagation()} className="w-full max-w-sm rounded-[2rem] border border-white/10 bg-slate-900 p-6 shadow-2xl">
        <div className="text-center">
          <span className="text-4xl">{perigo ? "⚠️" : "❓"}</span>
          <h2 className="mt-3 text-lg font-black text-white">{titulo}</h2>
          <p className="mt-2 text-sm text-slate-400">{mensagem}</p>
        </div>
        <div className="mt-6 grid grid-cols-2 gap-3">
          <button onClick={onCancelar} className="rounded-2xl border border-white/10 bg-white/[0.06] py-3 text-sm font-black text-slate-300 hover:bg-white/10">Cancelar</button>
          <button onClick={onConfirmar} className={`rounded-2xl py-3 text-sm font-black text-white ${perigo ? "bg-red-500 hover:bg-red-400" : "bg-blue-500 hover:bg-blue-400"}`}>{confirmar}</button>
        </div>
      </div>
    </div>
  );
}

// Paginação reutilizável (10 itens por página por padrão).
// tema="claro": variante clara (paleta do Dashboard/Relatórios) — opcional,
// não usada pelos chamadores antigos (permanecem no visual escuro de sempre).
// porPaginaOpcoes + onMudarPorPagina (opcionais): exibe um seletor de
// quantidade por página; quando presentes, o resumo "Mostrando X–Y de Z"
// nunca é ocultado, mesmo com 1 página só.
function Paginacao({ pagina, totalPaginas, total, porPagina = 10, onMudar, rotulo = "item(ns)", tema = "escuro", porPaginaOpcoes = null, onMudarPorPagina = null, mostrarExtremos = false }) {
  const temSeletor = !!porPaginaOpcoes && !!onMudarPorPagina;
  if (total <= porPagina && !temSeletor) return null; // cabe em 1 página e sem seletor → não exibe
  const inicio = total ? (pagina - 1) * porPagina + 1 : 0;
  const fim = Math.min(pagina * porPagina, total);
  // Janela de páginas: atual ±2, sempre com 1 e última
  const nums = [];
  const add = (n) => { if (n >= 1 && n <= totalPaginas && !nums.includes(n)) nums.push(n); };
  add(1);
  for (let i = pagina - 2; i <= pagina + 2; i++) add(i);
  add(totalPaginas);
  nums.sort((a, b) => a - b);
  const claro = tema === "claro";
  const txt = claro ? "text-slate-500" : "text-slate-400";
  const forte = claro ? "text-dash-navy" : "text-white";
  const borda = claro ? "border-slate-200" : "border-white/10";
  const btnCls = claro ? "border border-slate-200 bg-white text-slate-600 hover:bg-slate-100" : "border border-white/10 bg-white/[0.06] text-slate-300 hover:bg-white/10";
  const selectCls = claro ? "border border-slate-200 bg-white text-[#334155] focus:border-blue-500" : "border border-white/10 bg-slate-950/70 text-white focus:border-gold-400/60";
  const btn = "min-w-9 rounded-xl px-3 py-2 text-xs font-black transition disabled:opacity-30 disabled:cursor-not-allowed";

  return (
    <div className={`mt-4 flex flex-col items-center justify-between gap-3 border-t ${borda} pt-4 sm:flex-row`}>
      <div className="flex flex-wrap items-center justify-center gap-3">
        <p className={`text-xs ${txt}`}>
          {total > 0
            ? <>Mostrando <b className={forte}>{inicio}–{fim}</b> de <b className={forte}>{total}</b> {rotulo} · página {pagina}/{totalPaginas}</>
            : `Nenhum ${rotulo} encontrado.`}
        </p>
        {temSeletor && (
          <label className={`flex items-center gap-1.5 text-xs ${txt}`}>
            Por página:
            <select value={porPagina} onChange={(e) => onMudarPorPagina(Number(e.target.value))} className={`rounded-lg ${selectCls} px-2 py-1 text-xs outline-none`}>
              {porPaginaOpcoes.map((n) => <option key={n} value={n}>{n}</option>)}
            </select>
          </label>
        )}
      </div>
      {totalPaginas > 1 && (
        <div className="flex flex-wrap items-center justify-center gap-1">
          {mostrarExtremos && (
            <button disabled={pagina <= 1} onClick={() => onMudar(1)}
              className={`${btn} ${btnCls}`}>« Primeira</button>
          )}
          <button disabled={pagina <= 1} onClick={() => onMudar(pagina - 1)}
            className={`${btn} ${btnCls}`}>‹ Anterior</button>
          {nums.map((n, i) => {
            const gap = i > 0 && n - nums[i - 1] > 1;
            return (
              <span key={n} className="flex items-center gap-1">
                {gap && <span className={`px-1 ${claro ? "text-slate-400" : "text-slate-600"}`}>…</span>}
                <button onClick={() => onMudar(n)}
                  className={`${btn} ${n === pagina ? "bg-blue-500 text-white" : btnCls}`}>{n}</button>
              </span>
            );
          })}
          <button disabled={pagina >= totalPaginas} onClick={() => onMudar(pagina + 1)}
            className={`${btn} ${btnCls}`}>Próxima ›</button>
          {mostrarExtremos && (
            <button disabled={pagina >= totalPaginas} onClick={() => onMudar(totalPaginas)}
              className={`${btn} ${btnCls}`}>Última »</button>
          )}
        </div>
      )}
    </div>
  );
}

// Campo de tags reutilizável (ingredientes, etc.)
function TagsInput({ tags, setTags, placeholder = "Adicionar + Enter" }) {
  const [input, setInput] = useState("");
  const inp = "flex-1 rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-3 text-white outline-none focus:border-gold-400/60";
  function add() {
    const novos = input.split(",").map((s) => s.trim()).filter((s) => s && !tags.includes(s));
    if (novos.length) setTags([...tags, ...novos]);
    setInput("");
  }
  return (
    <div>
      <div className="flex gap-2">
        <input value={input} onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); add(); } }}
          placeholder={placeholder} className={inp} />
        <button onClick={add} className="shrink-0 rounded-2xl bg-blue-500 px-4 text-sm font-black text-white hover:bg-blue-400 transition">Adicionar</button>
      </div>
      {tags.length > 0 && (
        <div className="mt-2 flex flex-wrap gap-2">
          {tags.map((t) => (
            <span key={t} className="inline-flex items-center gap-1.5 rounded-full border border-emerald-400/30 bg-emerald-500/10 px-3 py-1.5 text-sm font-bold text-emerald-200">
              {t}
              <button onClick={() => setTags(tags.filter((x) => x !== t))} className="flex h-4 w-4 items-center justify-center rounded-full bg-emerald-500/30 text-xs text-emerald-100 hover:bg-red-500/40 hover:text-white transition">✕</button>
            </span>
          ))}
        </div>
      )}
    </div>
  );
}

// Editor de adicionais (extras) do produto: lista de { nome, preco }
function AdicionaisEditor({ value = [], onChange }) {
  const [nome, setNome] = useState("");
  const [preco, setPreco] = useState("");
  const inp = "rounded-2xl border border-white/10 bg-slate-950/70 px-3 py-2.5 text-white outline-none focus:border-gold-400/60 text-sm";
  function add() {
    const n = nome.trim();
    // Preço opcional: vazio = R$ 0,00 (adicional sem custo / grátis)
    const p = moedaParaNum(String(preco));
    if (!n || isNaN(p) || p < 0) return;
    if (value.some((a) => a.nome.toLowerCase() === n.toLowerCase())) { setNome(""); setPreco(""); return; }
    onChange([...(value || []), { nome: n, preco: p }]);
    setNome(""); setPreco("");
  }
  return (
    <div>
      <div className="flex gap-2">
        <input value={nome} onChange={(e) => setNome(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); add(); } }}
          placeholder="Adicional (ex.: Bacon)" className={`${inp} flex-1`} />
        <input value={preco} onChange={(e) => { const { display } = handleMoeda(e); setPreco(display); }} onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); add(); } }}
          inputMode="numeric" placeholder="R$ 0,00" className={`${inp} w-28`} />
        <button type="button" onClick={add} className="shrink-0 rounded-2xl bg-blue-500 px-4 text-sm font-black text-white hover:bg-blue-400">+</button>
      </div>
      {(value || []).length > 0 && (
        <div className="mt-2 space-y-1.5">
          {value.map((a, i) => (
            <div key={i} className="flex items-center justify-between rounded-xl border border-white/10 bg-slate-950/40 px-3 py-1.5">
              <span className="text-sm font-bold text-white">{a.nome}</span>
              <span className="flex items-center gap-2 text-sm"><span className="font-black text-emerald-300">{(Number(a.preco) || 0) > 0 ? formatCurrency(Number(a.preco)) : "Grátis"}</span>
                <button type="button" onClick={() => onChange(value.filter((_, idx) => idx !== i))} className="flex h-5 w-5 items-center justify-center rounded-full bg-red-500/20 text-xs text-red-300 hover:bg-red-500/40">✕</button></span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function ProductAdmin({ products, categories, categoriasDb = [], adminForm, setAdminForm, addProduct, toggleProduct, editarProduto, removerProduto, lojaId, opcoesApi = null, setores = [] }) {
  const [editando, setEditando] = useState(null);
  const [excluir, setExcluir]   = useState(null);
  const [variacoes, setVariacoes] = useState(null); // produto cujas variações/adicionais estamos editando
  const [criando, setCriando]   = useState(false);
  const [busca, setBusca]       = useState("");
  const [filtroCat, setFiltroCat] = useState("Todos");
  const [pagina, setPagina] = useState(1);
  const POR_PAGINA = 10;
  const cats = categories.filter((c) => c !== "Todos");
  // Categorias cadastradas e ativas — únicas selecionáveis ao criar/editar
  // produto (migration 068: vínculo obrigatório por ID, nunca por nome).
  const categoriasAtivas = categoriasDb.filter((c) => c.active !== false);

  const filtrados = products.filter((p) => {
    const t = `${p.name} ${p.category}`.toLowerCase();
    const okBusca = t.includes(busca.toLowerCase());
    const okCat = filtroCat === "Todos" || p.category === filtroCat;
    return okBusca && okCat;
  });

  // Paginação: 10 produtos por página (por categoria ou em "Todos")
  const totalPaginas = Math.max(1, Math.ceil(filtrados.length / POR_PAGINA));
  useEffect(() => { setPagina(1); }, [busca, filtroCat, products.length]);
  const paginaAtual = Math.min(pagina, totalPaginas);
  const visiveis = filtrados.slice((paginaAtual - 1) * POR_PAGINA, paginaAtual * POR_PAGINA);

  function abrirCadastro() {
    // Sem categoria padrão fixa — o admin precisa escolher (campo obrigatório).
    setAdminForm({ name: "", category: "", categoriaId: null, price: "", cost: "", time: TEMPOS_PREPARO[3], imageUrl: "", ingredientsText: "", description: "" });
    setCriando(true);
  }
  async function salvarNovo(overrideImageUrl) {
    const ok = await addProduct(overrideImageUrl);
    if (ok) setCriando(false);
  }

  return (
    <main className="space-y-5">
      {/* ── Cabeçalho padronizado (PageHeader) ─────────────── */}
      <PageHeader
        icone={<IconProdutos />}
        titulo="Produtos"
        descricao="Gerencie os itens vendidos no tablet, QR Code e cardápio externo."
        indicadores={[
          { valor: products.length, rotulo: products.length === 1 ? "produto" : "produtos" },
          { valor: products.filter((p) => p.active).length, rotulo: "ativos", tom: "ok" },
          { valor: products.filter((p) => !p.active).length, rotulo: "inativos" },
          ...(products.filter((p) => p.active && (p.estoque ?? 0) > 0 && p.estoque <= 5).length > 0
            ? [{ valor: products.filter((p) => p.active && (p.estoque ?? 0) > 0 && p.estoque <= 5).length, rotulo: "com estoque baixo", tom: "alerta" }] : []),
        ]}
        acao={<PrimeButton onClick={abrirCadastro}><span className="text-lg leading-none">+</span> Cadastrar produto</PrimeButton>}
      />

      {/* ── Cards de resumo ──────────────────────────────── */}
      <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
        {[
          { l: "Total de produtos", v: products.length, tom: "text-white" },
          { l: "Ativos", v: products.filter((p) => p.active).length, tom: "text-emerald-400" },
          { l: "Indisponíveis", v: products.filter((p) => !p.active).length, tom: "text-amber-400" },
          { l: "Sem imagem", v: products.filter((p) => !p.imageUrl).length, tom: "text-slate-300" },
        ].map((c) => (
          <div key={c.l} className="rounded-2xl border border-white/10 bg-white/[0.04] p-4">
            <p className="text-[10px] font-bold uppercase tracking-widest text-slate-500">{c.l}</p>
            <p className={`page-title mt-1.5 text-2xl font-black ${c.tom}`}>{c.v}</p>
          </div>
        ))}
      </div>

      {/* ── Busca + filtro por categoria ─────────────────── */}
      <div className="rounded-[2rem] border border-white/10 bg-white/[0.04] p-5">
        <div className="relative mb-3">
          <span className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-slate-500"><IconBusca /></span>
          <input value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar produto por nome ou categoria..."
            className="w-full rounded-2xl border border-white/10 bg-slate-950/70 py-3 pl-11 pr-4 text-sm text-white outline-none focus:border-gold-400/60" />
        </div>
        <div className="flex flex-wrap gap-2">
          {["Todos", ...cats].map((c) => (
            <FilterChip key={c} size="sm" selected={filtroCat === c} label={c} onClick={() => setFiltroCat(c)} />
          ))}
        </div>

        <div className="mt-4 space-y-2">
          {filtrados.length === 0 && (
            <div className="py-10 text-center">
              <p className="text-sm text-slate-500">Nenhum produto encontrado.</p>
              <button onClick={abrirCadastro} className="mt-3 rounded-2xl border border-blue-400/30 bg-blue-500/15 px-4 py-2 text-xs font-black text-blue-200 hover:bg-blue-500/25">+ Cadastrar produto</button>
            </div>
          )}
          {visiveis.map((p) => {
            const margin = p.price > 0 ? ((p.price - p.cost) / p.price) * 100 : 0;
            const estoqueBaixo = (p.estoque ?? 0) <= 5;
            return (
              <div key={p.id} className={`flex items-center gap-3 rounded-3xl border bg-slate-950/40 p-3 transition hover:bg-slate-900/60 ${p.active ? "border-white/10" : "border-white/10 opacity-60"}`}>
                <img src={p.imageUrl || fallbackImage} alt={p.name} className="h-14 w-14 shrink-0 rounded-2xl object-cover" />
                <div className="min-w-0 flex-1">
                  <p className="flex items-center gap-1.5 font-black text-white truncate">
                    {p.name}
                    {p.precoPromocional > 0 && <span className="shrink-0 rounded-full bg-gold-400/15 px-1.5 py-0.5 text-[9px] font-black text-gold-300">PROMO</span>}
                  </p>
                  <div className="flex flex-wrap items-center gap-x-2 text-xs text-slate-400">
                    <span className="rounded-full bg-white/[0.06] px-2 py-0.5">{p.category}</span>
                    {p.precoPromocional > 0
                      ? <span><span className="text-slate-500 line-through">{formatCurrency(p.price)}</span> <span className="font-bold text-gold-300">{formatCurrency(p.precoPromocional)}</span></span>
                      : <span className="font-bold text-white">{formatCurrency(p.price)}</span>}
                    <span className="text-emerald-300">margem {margin.toFixed(0)}%</span>
                    <span className={estoqueBaixo ? "font-bold text-red-300" : ""}>estoque {p.estoque ?? 0}{estoqueBaixo ? " ⚠" : ""}</span>
                    {/* Canais ocultos (migration 034) */}
                    {(p.visivelTablet === false || p.visivelQr === false || p.visivelExterno === false) && (
                      <span className="rounded-full bg-amber-500/15 px-1.5 py-0.5 text-[10px] font-bold text-amber-300">
                        oculto: {[p.visivelTablet === false && "tablet", p.visivelQr === false && "QR", p.visivelExterno === false && "externo"].filter(Boolean).join(", ")}
                      </span>
                    )}
                  </div>
                </div>
                <button onClick={() => toggleProduct(p.id)} title={p.active ? "Inativar" : "Ativar"} className={`shrink-0 rounded-full px-3 py-1.5 text-xs font-black transition ${p.active ? "bg-emerald-500 text-white hover:bg-emerald-400" : "bg-slate-700 text-slate-200 hover:bg-slate-600"}`}>{p.active ? "Ativo" : "Inativo"}</button>
                <button onClick={() => setEditando(p)} title="Editar" className="shrink-0 rounded-xl border border-blue-400/20 bg-blue-500/10 px-3 py-1.5 text-xs font-black text-blue-300 hover:bg-blue-500/20 transition">✏️</button>
                {opcoesApi && <button onClick={() => setVariacoes(p)} title="Adicionais e variações" className="shrink-0 rounded-xl border border-gold-400/30 bg-gold-400/10 px-3 py-1.5 text-xs font-black text-gold-200 hover:bg-gold-400/20 transition">⭐ Variações</button>}
                <button onClick={() => setExcluir(p)} title="Excluir" className="shrink-0 rounded-xl border border-red-400/20 bg-red-500/10 px-3 py-1.5 text-xs font-black text-red-300 hover:bg-red-500/20 transition">🗑️</button>
              </div>
            );
          })}
        </div>

        {/* Paginação — 10 por página */}
        <Paginacao
          pagina={paginaAtual} totalPaginas={totalPaginas} total={filtrados.length}
          porPagina={POR_PAGINA} onMudar={setPagina} rotulo="produto(s)"
        />
      </div>

      {criando && (
        <ProdutoCadastroModal adminForm={adminForm} setAdminForm={setAdminForm} categoriasAtivas={categoriasAtivas} lojaId={lojaId}
          onSalvar={salvarNovo} onFechar={() => setCriando(false)} />
      )}
      {editando && <ProdutoEditModal produto={editando} categoriasAtivas={categoriasAtivas} lojaId={lojaId} setores={setores} onSalvar={(d) => { editarProduto(editando.id, d); setEditando(null); }} onFechar={() => setEditando(null)} />}
      {variacoes && opcoesApi && <GruposOpcoesModal produto={variacoes} api={opcoesApi} onFechar={() => setVariacoes(null)} />}
      {excluir && (
        <ConfirmModal titulo="Excluir produto?"
          mensagem={`Tem certeza que deseja excluir "${excluir.name}"? Esta ação não pode ser desfeita. Dica: você pode apenas inativar o produto.`}
          confirmar="Sim, excluir"
          onConfirmar={() => { removerProduto(excluir.id); setExcluir(null); }}
          onCancelar={() => setExcluir(null)} />
      )}
    </main>
  );
}

// Modal de cadastro de novo produto (layout minimalista, bound ao adminForm)
// Converte string raw (só dígitos) para exibição "R$ 0,00"
function rawParaMoeda(raw) {
  const digits = raw.replace(/\D/g, "").padStart(3, "0");
  const cents = digits.slice(-2);
  const reais = digits.slice(0, -2).replace(/^0+/, "") || "0";
  return `R$ ${reais},${cents}`;
}
// Converte string de exibição "R$ 1.234,56" para número
function moedaParaNum(raw) {
  const digits = raw.replace(/\D/g, "");
  if (!digits || digits === "000") return 0;
  return Number((parseInt(digits, 10) / 100).toFixed(2));
}
// Handler de campo moeda: recebe o evento e retorna { display, num }
function handleMoeda(e) {
  const digits = e.target.value.replace(/\D/g, "");
  return { display: rawParaMoeda(digits), num: moedaParaNum(digits) };
}

// ── Seletor de imagem (arquivo local + URL) ────────────────────
// Aceita PNG e JPEG, máx 2 MB. Mostra prévia e progresso de upload.
// onImageUrl(url) → chamado com a URL final (blob para prévia, publicUrl após upload)
// onFileChange(file|null) → arquivo selecionado (para upload no salvar)
function SeletorImagem({ urlAtual, onImageUrl, onFileChange, uploading = false, erroUpload = "" }) {
  const fileRef = React.useRef(null);
  const [previa, setPrevia] = React.useState("");

  function handleFile(e) {
    const f = e.target.files?.[0];
    if (!f) return;
    const erroVal = validarImagemProduto(f);
    if (erroVal) { onFileChange(null); onImageUrl(""); alert(erroVal); return; }
    const blob = URL.createObjectURL(f);
    setPrevia(blob);
    onFileChange(f);
    onImageUrl(blob); // prévia imediata
  }

  const exibir = previa || urlAtual;

  return (
    <div className="space-y-2">
      <div className="flex gap-3">
        {/* Miniatura */}
        <div className="relative h-20 w-20 shrink-0 overflow-hidden rounded-2xl border border-white/10 bg-slate-800">
          {exibir
            ? <img src={exibir} alt="prévia" className="h-full w-full object-cover" onError={() => {}} />
            : <div className="flex h-full w-full items-center justify-center text-2xl">🖼️</div>
          }
          {uploading && (
            <div className="absolute inset-0 flex items-center justify-center bg-black/60">
              <div className="h-6 w-6 animate-spin rounded-full border-2 border-blue-400 border-t-transparent" />
            </div>
          )}
        </div>
        {/* Controles */}
        <div className="flex-1 space-y-2">
          {/* Arquivo local */}
          <input ref={fileRef} type="file" accept=".png,.jpg,.jpeg,image/png,image/jpeg" className="hidden" onChange={handleFile} />
          <button type="button" onClick={() => fileRef.current?.click()}
            className="flex w-full items-center justify-center gap-2 rounded-2xl border border-blue-400/30 bg-blue-500/10 py-2.5 text-xs font-black text-blue-300 hover:bg-blue-500/20 transition">
            📁 Escolher arquivo (PNG / JPEG • máx 2 MB)
          </button>
          {/* OU URL */}
          <div className="relative">
            <span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-xs text-slate-600">🔗</span>
            <input
              value={previa ? "" : (urlAtual || "")}
              onChange={(e) => { setPrevia(""); onFileChange(null); onImageUrl(e.target.value); }}
              placeholder="ou cole uma URL de imagem..."
              className="w-full rounded-2xl border border-white/10 bg-slate-950/70 py-2.5 pl-8 pr-3 text-xs text-white outline-none focus:border-gold-400/60 placeholder:text-slate-600"
            />
          </div>
        </div>
      </div>
      {previa && <p className="text-[11px] text-emerald-400">✅ Arquivo selecionado — será enviado ao salvar.</p>}
      {erroUpload && <p className="text-[11px] text-red-400">❌ {erroUpload}</p>}
    </div>
  );
}

function ProdutoCadastroModal({ adminForm, setAdminForm, categoriasAtivas, onSalvar, onFechar, lojaId }) {
  const inp = "w-full rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-3 text-white outline-none focus:border-gold-400/60 placeholder:text-slate-600";
  const lbl = "mb-1 block text-xs font-bold uppercase tracking-widest text-slate-500";
  const set = (k, v) => setAdminForm({ ...adminForm, [k]: v });
  // Escolher a categoria grava os dois: categoriaId (vínculo real, migration
  // 068) e category (nome, mantido em sincronia p/ telas ainda lendo o texto).
  const setCategoria = (cat) => setAdminForm({ ...adminForm, categoriaId: cat.id, category: cat.nome });
  const tagsAtuais = adminForm.ingredientsText ? adminForm.ingredientsText.split(",").map((s) => s.trim()).filter(Boolean) : [];
  const precoNum = moedaParaNum(String(adminForm.price));
  const custoNum = moedaParaNum(String(adminForm.cost));
  const [arquivoImg, setArquivoImg] = React.useState(null);
  const [uploadando, setUploadando] = React.useState(false);
  const [erroUpload, setErroUpload] = React.useState("");
  // Todos os campos são obrigatórios (categoria: migration 068, vínculo por ID)
  const valido = adminForm.name.trim() &&
    adminForm.categoriaId != null &&
    precoNum > 0 && custoNum > 0 &&
    adminForm.time.trim() &&
    adminForm.imageUrl.trim() &&
    tagsAtuais.length > 0 &&
    adminForm.description.trim();
  const margem = precoNum > 0 && custoNum > 0
    ? (((precoNum - custoNum) / precoNum) * 100).toFixed(0)
    : null;
  // Inicializa display dos campos moeda na primeira vez (se value for numérico puro)
  function displayMoeda(v) {
    if (!v || v === "0") return "";
    if (String(v).startsWith("R$")) return v;
    const digits = String(Math.round(Number(v) * 100)).padStart(3, "0");
    return rawParaMoeda(digits);
  }

  // Salvar: se houver arquivo local, faz upload primeiro e usa a URL pública
  async function handleSalvar() {
    setErroUpload("");
    let urlFinal;
    if (arquivoImg) {
      setUploadando(true);
      try {
        urlFinal = await uploadImagemProduto(arquivoImg, lojaId || "geral");
        set("imageUrl", urlFinal);
      } catch (e) {
        setUploadando(false);
        setErroUpload(e.message || "Falha no upload da imagem.");
        return;
      }
      setUploadando(false);
    }
    onSalvar(urlFinal);
  }

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/75 backdrop-blur-sm p-4" onClick={onFechar}>
      <div onClick={(e) => e.stopPropagation()} className="flex w-full max-w-2xl flex-col overflow-hidden rounded-[2rem] border border-white/10 bg-slate-900 shadow-2xl max-h-[92vh]">
        <div className="flex items-center justify-between border-b border-white/10 px-6 py-4">
          <div className="flex items-center gap-2">
            <span className="flex h-9 w-9 items-center justify-center rounded-2xl bg-blue-500/15 text-lg">🛒</span>
            <h2 className="text-lg font-black text-white">Novo produto</h2>
          </div>
          <button onClick={onFechar} className="rounded-2xl border border-white/10 bg-white/[0.08] px-4 py-2 text-sm font-black text-slate-300 hover:bg-white/20">✕</button>
        </div>

        <div className="flex-1 overflow-y-auto px-6 py-4 space-y-4">
          {/* Prévia + nome/categoria */}
          <div className="flex gap-4">
            <div className="h-24 w-24 shrink-0 overflow-hidden rounded-2xl border border-white/10 bg-slate-800">
              <img src={adminForm.imageUrl || fallbackImage} alt="prévia" className="h-full w-full object-cover" />
            </div>
            <div className="min-w-0 flex-1 space-y-3">
              <div>
                <span className={lbl}>Nome do produto *</span>
                <input autoFocus value={adminForm.name} onChange={(e) => set("name", e.target.value)} placeholder="Ex.: Risoto de Filé Mignon" className={inp} />
              </div>
              <div>
                <span className={lbl}>Categoria *</span>
                {categoriasAtivas.length === 0 ? (
                  <p className="rounded-2xl border border-amber-400/20 bg-amber-500/10 px-3 py-2 text-xs font-bold text-amber-200">
                    Nenhuma categoria ativa cadastrada. Cadastre em <b className="text-white">Cadastros → Categorias</b> antes de criar produtos.
                  </p>
                ) : (
                  <SeletorCategoria valorId={adminForm.categoriaId} aoMudar={setCategoria} categorias={categoriasAtivas} />
                )}
              </div>
            </div>
          </div>

          {/* Custo / Preço venda / Preparo */}
          <div className="grid grid-cols-3 gap-3">
            <div>
              <span className={lbl}>Custo *</span>
              <input inputMode="numeric" value={displayMoeda(adminForm.cost)}
                onChange={(e) => { const {display} = handleMoeda(e); set("cost", display); }}
                placeholder="R$ 0,00" className={inp} />
            </div>
            <div>
              <span className={lbl}>Preço venda *</span>
              <input inputMode="numeric" value={displayMoeda(adminForm.price)}
                onChange={(e) => { const {display} = handleMoeda(e); set("price", display); }}
                placeholder="R$ 0,00" className={inp} />
            </div>
            <div>
              <span className={lbl}>Preparo *</span>
              <select value={adminForm.time || ""} onChange={(e) => set("time", e.target.value)} className={inp}>
                <option value="" disabled>Selecione...</option>
                {TEMPOS_PREPARO.map((t) => <option key={t} value={t}>{t}</option>)}
              </select>
            </div>
          </div>
          {margem !== null && <p className="text-xs font-bold text-emerald-300">Margem estimada: {margem}%</p>}

          {/* Imagem — arquivo local (PNG/JPEG) ou URL */}
          <div>
            <span className={lbl}>Imagem do produto *</span>
            <SeletorImagem
              urlAtual={adminForm.imageUrl}
              onImageUrl={(u) => set("imageUrl", u)}
              onFileChange={setArquivoImg}
              uploading={uploadando}
              erroUpload={erroUpload}
            />
          </div>

          {/* Ingredientes */}
          <div>
            <span className={lbl}>Ingredientes * <span className="text-slate-600 normal-case">— Enter para adicionar</span></span>
            <TagsInput tags={tagsAtuais} setTags={(arr) => set("ingredientsText", arr.join(", "))} placeholder="Ex.: Parmesão" />
          </div>

          {/* Adicionais (extras) do produto */}
          <div>
            <span className={lbl}>Adicionais <span className="text-slate-600 normal-case">— extras com preço que o cliente pode escolher</span></span>
            <AdicionaisEditor value={adminForm.adicionais || []} onChange={(v) => set("adicionais", v)} />
          </div>

          {/* Descrição */}
          <div>
            <span className={lbl}>Descrição *</span>
            <textarea value={adminForm.description} onChange={(e) => set("description", e.target.value)} placeholder="Descrição do produto" rows={2} className={`${inp} resize-none`} />
          </div>
        </div>

        <div className="shrink-0 border-t border-white/10 px-6 py-4 space-y-2">
          {!valido && (adminForm.name || moedaParaNum(String(adminForm.price)) > 0) && (
            <p className="text-xs font-semibold text-amber-400">
              ⚠ Preencha todos os campos obrigatórios (*) para cadastrar.
            </p>
          )}
          <div className="flex gap-3">
            <button onClick={onFechar} className="flex-1 rounded-2xl border border-white/10 bg-white/[0.06] py-3.5 text-sm font-black text-slate-300 hover:bg-white/10">Cancelar</button>
            <button onClick={handleSalvar} disabled={!valido || uploadando}
              className="flex-[2] rounded-2xl bg-blue-500 py-3.5 text-sm font-black text-white hover:bg-blue-400 transition active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed">
              {uploadando ? "⏳ Enviando imagem..." : "+ Cadastrar produto"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

// Seletor de categoria minimalista e gourmet (chips com acento dourado/âmbar)
// Migration 068: seleciona a categoria pelo ID real (nunca pelo nome) —
// `categorias` recebe objetos { id, nome }, `aoMudar` devolve o objeto
// inteiro (o chamador grava categoriaId + o nome de exibição).
function SeletorCategoria({ valorId, aoMudar, categorias }) {
  return (
    <div className="flex flex-wrap gap-2">
      {categorias.map((c) => {
        const ativo = valorId === c.id;
        return (
          <button key={c.id} type="button" onClick={() => aoMudar(c)}
            className={`group inline-flex items-center gap-2 rounded-full border px-4 py-2 text-sm font-bold tracking-tight transition active:scale-95 ${
              ativo
                ? "border-[#EBCE86] bg-[#FAF0D6] text-[#8A6A12] shadow-[0_0_0_1px_rgba(201,154,46,0.18),0_4px_16px_-6px_rgba(201,154,46,0.4)]"
                : "border-white/10 bg-white/[0.04] text-slate-300 hover:border-[#EBCE86]/60 hover:bg-white/[0.07] hover:text-[#8A6A12]"
            }`}>
            <span className={`h-1.5 w-1.5 rounded-full transition ${ativo ? "bg-[#C99A2E] shadow-[0_0_6px_1px_rgba(201,154,46,0.6)]" : "bg-slate-600 group-hover:bg-[#C99A2E]/60"}`} />
            {c.nome}
          </button>
        );
      })}
    </div>
  );
}

function ProdutoEditModal({ produto, categoriasAtivas, onSalvar, onFechar, lojaId, setores = [] }) {
  // Inicializa campos de moeda já formatados
  const toDisplay = (v) => {
    if (!v && v !== 0) return "";
    if (String(v).startsWith("R$")) return v;
    const digits = String(Math.round(Number(v) * 100)).padStart(3, "0");
    return rawParaMoeda(digits);
  };
  const [f, setF] = useState({
    name: produto.name, category: produto.category, categoriaId: produto.categoriaId ?? null,
    price: toDisplay(produto.price), cost: toDisplay(produto.cost),
    precoPromo: produto.precoPromocional ? toDisplay(produto.precoPromocional) : "",
    time: produto.time || "", imageUrl: produto.imageUrl || "", description: produto.description || "",
    estoque: produto.estoque ?? 0,
    controlaEstoque: produto.controlaEstoque ?? false,
    estoqueMinimo: produto.estoqueMinimo ?? 0,
    visivelTablet: produto.visivelTablet !== false,
    visivelQr: produto.visivelQr !== false,
    visivelExterno: produto.visivelExterno !== false,
    // Migration 038 — destaque e disponibilidade
    isFeatured: produto.isFeatured ?? false,
    featuredLabel: produto.featuredLabel || "",
    showOnHome: produto.showOnHome !== false,
    disponivel: produto.disponivel !== false,
    // Migration 041 — setor de cozinha
    setorId: produto.setorId || "",
  });
  const [tags, setTags] = useState([...(produto.ingredients || [])]); // ingredientes como tags
  const [adicionais, setAdicionais] = useState([...(produto.adicionais || [])]); // extras do produto
  const [arquivoImg, setArquivoImg] = React.useState(null);
  const [uploadando, setUploadando] = React.useState(false);
  const [erroUpload, setErroUpload] = React.useState("");
  const inp = "w-full rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-3 text-white outline-none focus:border-gold-400/60";
  const lbl = "mb-1 block text-xs font-bold uppercase tracking-widest text-slate-500";
  const precoNum = moedaParaNum(String(f.price));
  const custoNum = moedaParaNum(String(f.cost));
  const validoEdit = f.name.trim() && f.categoriaId != null && precoNum > 0 && custoNum > 0 &&
    f.time.trim() && f.imageUrl.trim() && tags.length > 0 && f.description.trim();
  // Tempos: garante que o valor atual apareça mesmo se for um texto antigo fora do padrão
  const opcoesTempo = TEMPOS_PREPARO.includes(f.time) || !f.time ? TEMPOS_PREPARO : [f.time, ...TEMPOS_PREPARO];

  async function handleSalvarEdit() {
    setErroUpload("");
    let imgFinal = f.imageUrl;
    if (arquivoImg) {
      setUploadando(true);
      try {
        imgFinal = await uploadImagemProduto(arquivoImg, lojaId || "geral");
      } catch (e) {
        setUploadando(false);
        setErroUpload(e.message || "Falha no upload da imagem.");
        return;
      }
      setUploadando(false);
    }
    onSalvar({
      ...f, imageUrl: imgFinal, price: precoNum, cost: custoNum, ingredients: tags, adicionais,
      precoPromocional: moedaParaNum(String(f.precoPromo)),
      controlaEstoque: f.controlaEstoque, estoqueMinimo: f.estoqueMinimo,
      visivelTablet: f.visivelTablet, visivelQr: f.visivelQr, visivelExterno: f.visivelExterno,
      isFeatured: f.isFeatured, featuredLabel: f.isFeatured ? (f.featuredLabel || "Destaque") : "", showOnHome: f.showOnHome, disponivel: f.disponivel,
      setorId: f.setorId || null,
    });
  }

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/75 backdrop-blur-sm p-4" onClick={onFechar}>
      <div onClick={(e) => e.stopPropagation()} className="flex w-full max-w-2xl flex-col overflow-hidden rounded-[2rem] border border-white/10 bg-slate-900 shadow-2xl max-h-[92vh]">
        <div className="flex items-center justify-between border-b border-white/10 px-6 py-4">
          <div className="flex items-center gap-2">
            <span className="flex h-9 w-9 items-center justify-center rounded-2xl bg-blue-500/15 text-lg">✏️</span>
            <h2 className="text-lg font-black text-white">Editar produto</h2>
          </div>
          <button onClick={onFechar} className="rounded-2xl border border-white/10 bg-white/[0.08] px-4 py-2 text-sm font-black text-slate-300 hover:bg-white/20">✕</button>
        </div>

        <div className="flex-1 overflow-y-auto px-6 py-4 space-y-4">
          {/* Prévia + nome/categoria */}
          <div className="flex gap-4">
            <div className="h-24 w-24 shrink-0 overflow-hidden rounded-2xl border border-white/10 bg-slate-800">
              <img src={f.imageUrl || fallbackImage} alt="prévia" className="h-full w-full object-cover" />
            </div>
            <div className="min-w-0 flex-1 space-y-3">
              <div>
                <span className={lbl}>Nome do produto *</span>
                <input value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} placeholder="Ex.: Risoto de Filé Mignon" className={inp} />
              </div>
              <div>
                <span className={lbl}>Categoria *</span>
                {categoriasAtivas.length === 0 ? (
                  <p className="rounded-2xl border border-amber-400/20 bg-amber-500/10 px-3 py-2 text-xs font-bold text-amber-200">
                    Nenhuma categoria ativa cadastrada. Cadastre em <b className="text-white">Cadastros → Categorias</b>.
                  </p>
                ) : (
                  <SeletorCategoria valorId={f.categoriaId} aoMudar={(c) => setF({ ...f, categoriaId: c.id, category: c.nome })} categorias={categoriasAtivas} />
                )}
              </div>
            </div>
          </div>

          {/* Custo / Preço venda / Preparo / Estoque */}
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
            <div>
              <span className={lbl}>Custo *</span>
              <input inputMode="numeric" value={f.cost}
                onChange={(e) => { const {display}=handleMoeda(e); setF({...f, cost: display}); }}
                placeholder="R$ 0,00" className={inp} />
            </div>
            <div>
              <span className={lbl}>Preço venda *</span>
              <input inputMode="numeric" value={f.price}
                onChange={(e) => { const {display}=handleMoeda(e); setF({...f, price: display}); }}
                placeholder="R$ 0,00" className={inp} />
            </div>
            <div>
              <span className={lbl}>Preparo *</span>
              <select value={f.time || ""} onChange={(e) => setF({ ...f, time: e.target.value })} className={inp}>
                <option value="" disabled>Selecione...</option>
                {opcoesTempo.map((t) => <option key={t} value={t}>{t}</option>)}
              </select>
            </div>
            <div>
              <span className={lbl}>Estoque</span>
              <input value={f.estoque} onChange={(e) => setF({ ...f, estoque: e.target.value.replace(/\D/g, "") })} placeholder="0" className={inp} />
            </div>
          </div>
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
            <div className="sm:col-span-2">
              <span className={lbl}>Preço promocional <span className="text-slate-600 normal-case">— opcional</span></span>
              <input inputMode="numeric" value={f.precoPromo}
                onChange={(e) => { const {display}=handleMoeda(e); setF({...f, precoPromo: display}); }}
                placeholder="R$ 0,00" className={inp} />
            </div>
          </div>
          {precoNum > 0 && custoNum > 0 && (
            <p className="text-xs font-bold text-emerald-300">
              Margem estimada: {(((precoNum-custoNum)/precoNum)*100).toFixed(0)}%
              {moedaParaNum(String(f.precoPromo)) > 0 && <span className="ml-2 text-gold-300">· Promo: {(((moedaParaNum(String(f.precoPromo))-custoNum)/moedaParaNum(String(f.precoPromo)))*100).toFixed(0)}%</span>}
            </p>
          )}

          {/* Estoque & Visibilidade (migration 034) */}
          <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-4 space-y-3">
            <div className="flex items-center justify-between gap-3">
              <span className="text-xs font-bold uppercase tracking-widest text-slate-400">Controle de estoque</span>
              <button type="button" onClick={() => setF({ ...f, controlaEstoque: !f.controlaEstoque })}
                className={`relative h-6 w-11 shrink-0 rounded-full transition ${f.controlaEstoque ? "bg-emerald-500" : "bg-slate-700"}`}>
                <span className={`absolute top-0.5 h-5 w-5 rounded-full bg-white transition-all ${f.controlaEstoque ? "left-[22px]" : "left-0.5"}`} />
              </button>
            </div>
            {f.controlaEstoque && (
              <div>
                <span className={lbl}>Estoque mínimo <span className="text-slate-600 normal-case">— alerta de baixo estoque</span></span>
                <input value={f.estoqueMinimo} onChange={(e) => setF({ ...f, estoqueMinimo: e.target.value.replace(/\D/g, "") })} placeholder="0" className={inp} />
              </div>
            )}
            <div>
              <span className={lbl}>Visível em</span>
              <div className="flex flex-wrap gap-2">
                {[["visivelTablet", "📲 Tablet"], ["visivelQr", "🔳 QR Code"], ["visivelExterno", "📱 Cardápio externo"]].map(([k, t]) => (
                  <button key={k} type="button" onClick={() => setF({ ...f, [k]: !f[k] })}
                    className={`rounded-xl border px-3 py-2 text-xs font-bold transition ${f[k] ? "border-gold-400/60 bg-gold-400/10 text-gold-200" : "border-white/10 bg-white/[0.03] text-slate-500"}`}>
                    <span className={`mr-1.5 ${f[k] ? "" : "opacity-40"}`}>{f[k] ? "✓" : "○"}</span>{t}
                  </button>
                ))}
              </div>
            </div>
          </div>

          {/* Setor de cozinha (migration 041) */}
          {setores.length > 0 && (
            <div>
              <span className={lbl}>Setor de preparo</span>
              <select value={f.setorId} onChange={(e) => setF({ ...f, setorId: e.target.value ? Number(e.target.value) : "" })} className={inp}>
                <option value="">— Sem setor —</option>
                {setores.filter((s) => s.ativo !== false).map((s) => <option key={s.id} value={s.id}>{s.nome}</option>)}
              </select>
            </div>
          )}

          {/* Destaque & Disponibilidade (migration 038) */}
          <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-4 space-y-3">
            {/* Disponibilidade */}
            <div className="flex items-center justify-between gap-3">
              <div>
                <span className="text-xs font-bold uppercase tracking-widest text-slate-400">Disponível para venda</span>
                <p className="text-[11px] text-slate-500">Desligado: aparece como “Indisponível no momento” e não pode ser pedido.</p>
              </div>
              <button type="button" onClick={() => setF({ ...f, disponivel: !f.disponivel })}
                className={`relative h-6 w-11 shrink-0 rounded-full transition ${f.disponivel ? "bg-emerald-500" : "bg-slate-700"}`}>
                <span className={`absolute top-0.5 h-5 w-5 rounded-full bg-white transition-all ${f.disponivel ? "left-[22px]" : "left-0.5"}`} />
              </button>
            </div>
            {/* Destaque */}
            <div className="flex items-center justify-between gap-3 border-t border-white/10 pt-3">
              <div>
                <span className="text-xs font-bold uppercase tracking-widest text-gold-300">⭐ Produto em destaque</span>
                <p className="text-[11px] text-slate-500">Aparece na seção “Destaques da Casa” do cardápio/tablet.</p>
              </div>
              <button type="button" onClick={() => setF({ ...f, isFeatured: !f.isFeatured })}
                className={`relative h-6 w-11 shrink-0 rounded-full transition ${f.isFeatured ? "bg-gold-400" : "bg-slate-700"}`}>
                <span className={`absolute top-0.5 h-5 w-5 rounded-full bg-white transition-all ${f.isFeatured ? "left-[22px]" : "left-0.5"}`} />
              </button>
            </div>
            {f.isFeatured && (
              <div>
                <span className={lbl}>Etiqueta do destaque</span>
                <div className="flex flex-wrap gap-2">
                  {["Mais vendido", "Sugestão do chef", "Novo", "Especial da casa", "Promoção", "Destaque"].map((lab) => (
                    <FilterChip key={lab} size="sm" selected={f.featuredLabel === lab} label={lab} onClick={() => setF({ ...f, featuredLabel: lab })} />
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Imagem — arquivo local (PNG/JPEG) ou URL */}
          <div>
            <span className={lbl}>Imagem do produto *</span>
            <SeletorImagem
              urlAtual={f.imageUrl}
              onImageUrl={(u) => setF((cur) => ({ ...cur, imageUrl: u }))}
              onFileChange={setArquivoImg}
              uploading={uploadando}
              erroUpload={erroUpload}
            />
          </div>

          {/* Ingredientes como TAGS */}
          <div>
            <span className={lbl}>Ingredientes * <span className="text-slate-600 normal-case">— Enter para adicionar</span></span>
            <TagsInput tags={tags} setTags={setTags} placeholder="Ex.: Parmesão" />
          </div>

          {/* Adicionais (extras) do produto — nome + preço */}
          <div>
            <span className={lbl}>Adicionais <span className="text-slate-600 normal-case">— extras com preço que o cliente pode escolher</span></span>
            <AdicionaisEditor value={adicionais} onChange={setAdicionais} />
          </div>

          {/* Descrição */}
          <div>
            <span className={lbl}>Descrição *</span>
            <textarea value={f.description} onChange={(e) => setF({ ...f, description: e.target.value })} placeholder="Descrição do produto" rows={2} className={`${inp} resize-none`} />
          </div>
        </div>

        <div className="shrink-0 border-t border-white/10 px-6 py-4 space-y-2">
          {!validoEdit && (
            <p className="text-xs font-semibold text-amber-400">
              ⚠ Preencha todos os campos obrigatórios (*) para salvar.
            </p>
          )}
          <div className="flex gap-3">
            <button onClick={onFechar} className="flex-1 rounded-2xl border border-white/10 bg-white/[0.06] py-3.5 text-sm font-black text-slate-300 hover:bg-white/10">Cancelar</button>
            <button onClick={handleSalvarEdit} disabled={!validoEdit || uploadando}
              className="flex-[2] rounded-2xl bg-blue-500 py-3.5 text-sm font-black text-white hover:bg-blue-400 transition active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed">
              {uploadando ? "⏳ Enviando imagem..." : "💾 Salvar alterações"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ════════════════════════════════════════════════════════════
//  Admin — Cargos / Perfis (cadastro reutilizável)
// ════════════════════════════════════════════════════════════
function CargoAdmin({ cargos = [], users = [], addCargo, editarCargo, toggleCargo, removerCargo }) {
  const [editando, setEditando] = useState(null);
  const [excluir, setExcluir]   = useState(null);
  const [criando, setCriando]   = useState(false);
  const [busca, setBusca]       = useState("");
  const qtdUsuarios = (id) => users.filter((u) => u.cargoId === id).length;

  const termo = busca.trim().toLowerCase();
  const filtrados = termo ? cargos.filter((c) => `${c.nome} ${c.descricao}`.toLowerCase().includes(termo)) : cargos;

  async function salvarNovo(form) {
    const ok = await addCargo(form);
    if (ok) setCriando(false);
  }

  return (
    <main className="space-y-5">
      {/* ── Cabeçalho padronizado (PageHeader) ─────────────── */}
      <PageHeader
        icone={<IconCargos />}
        titulo="Cargos / Perfis"
        descricao="Perfis de acesso que aparecem no cadastro de usuários e empresas."
        indicadores={[
          { valor: cargos.length, rotulo: cargos.length === 1 ? "cargo" : "cargos" },
          { valor: cargos.filter((c) => c.active !== false).length, rotulo: "ativos", tom: "ok" },
          { valor: cargos.filter((c) => c.active === false).length, rotulo: "inativos" },
          { valor: users.length, rotulo: "usuários vinculados", tom: "gold" },
        ]}
        acao={<PrimeButton onClick={() => setCriando(true)}><span className="text-lg leading-none">+</span> Cadastrar cargo</PrimeButton>}
      />

      {/* Busca + lista */}
      <div className="rounded-[2rem] border border-white/10 bg-white/[0.04] p-5">
        <div className="relative mb-4">
          <span className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-slate-500"><IconBusca /></span>
          <input value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar cargo..."
            className="w-full rounded-2xl border border-white/10 bg-slate-950/70 py-3 pl-11 pr-4 text-sm text-white outline-none focus:border-gold-400/60" />
        </div>
        <div className="space-y-2">
          {cargos.length === 0 && (
            <div className="py-10 text-center">
              <p className="text-sm text-slate-500">Nenhum cargo cadastrado.</p>
              <button onClick={() => setCriando(true)} className="mt-3 rounded-2xl border border-blue-400/30 bg-blue-500/15 px-4 py-2 text-xs font-black text-blue-200 hover:bg-blue-500/25">+ Cadastrar cargo</button>
            </div>
          )}
          {cargos.length > 0 && filtrados.length === 0 && <p className="py-6 text-center text-sm text-slate-500">Nenhum cargo encontrado.</p>}
          {filtrados.map((c) => (
            <div key={c.id} className="flex items-center gap-3 rounded-3xl border border-white/10 bg-slate-950/40 p-3">
              <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-white/[0.06] text-lg">🪪</span>
              <div className="min-w-0 flex-1">
                <p className="font-black text-white truncate">{c.nome}</p>
                {c.descricao && <p className="text-xs text-slate-400 truncate">{c.descricao}</p>}
                <p className="text-[11px] text-slate-500">{qtdUsuarios(c.id)} usuário(s) com este cargo</p>
              </div>
              <button onClick={() => toggleCargo(c.id)} className={`shrink-0 rounded-full px-3 py-1.5 text-xs font-black ${c.active !== false ? "bg-emerald-500 text-white" : "bg-slate-700 text-slate-200"}`}>{c.active !== false ? "Ativo" : "Inativo"}</button>
              <button onClick={() => setEditando(c)} className="shrink-0 rounded-xl border border-white/10 bg-white/[0.06] px-3 py-1.5 text-xs font-black text-blue-300 hover:bg-white/10">✏️</button>
              <button onClick={() => setExcluir(c)} disabled={qtdUsuarios(c.id) > 0} title={qtdUsuarios(c.id) > 0 ? "Há usuários vinculados — inative em vez de excluir" : "Excluir cargo"} className="shrink-0 rounded-xl border border-red-400/20 bg-red-500/10 px-3 py-1.5 text-xs font-black text-red-300 hover:bg-red-500/20 disabled:opacity-30 disabled:cursor-not-allowed">🗑️</button>
            </div>
          ))}
        </div>
      </div>

      {criando && <CargoCadastroModal onSalvar={salvarNovo} onFechar={() => setCriando(false)} />}
      {editando && <CargoEditModal cargo={editando} onSalvar={(d) => { editarCargo(editando.id, d); setEditando(null); }} onFechar={() => setEditando(null)} />}
      {excluir && (
        <ConfirmModal titulo="Excluir cargo?"
          mensagem={`Deseja excluir o cargo "${excluir.nome}"? Esta ação não pode ser desfeita.`}
          confirmar="Sim, excluir"
          onConfirmar={() => { removerCargo(excluir.id); setExcluir(null); }}
          onCancelar={() => setExcluir(null)} />
      )}
    </main>
  );
}

// Modal de cadastro de cargo (mesmo padrão dos demais)
function CargoCadastroModal({ onSalvar, onFechar }) {
  const [form, setForm] = useState({ nome: "", descricao: "" });
  const inp = "w-full rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-3 text-white outline-none focus:border-gold-400/60 placeholder:text-slate-600";
  const lbl = "mb-1.5 block text-xs font-bold uppercase tracking-widest text-slate-500";
  const valido = form.nome.trim().length > 0;
  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/75 backdrop-blur-sm p-4" onClick={onFechar}>
      <div onClick={(e) => e.stopPropagation()} className="flex w-full max-w-md flex-col overflow-hidden rounded-[2rem] border border-white/10 bg-slate-900 shadow-2xl">
        <div className="flex items-center justify-between border-b border-white/10 px-6 py-4">
          <div className="flex items-center gap-2">
            <span className="flex h-9 w-9 items-center justify-center rounded-2xl bg-blue-500/15 text-lg">🪪</span>
            <h2 className="text-lg font-black text-white">Novo cargo / perfil</h2>
          </div>
          <button onClick={onFechar} className="rounded-2xl border border-white/10 bg-white/[0.08] px-4 py-2 text-sm font-black text-slate-300 hover:bg-white/20">✕</button>
        </div>
        <div className="px-6 py-5 space-y-3">
          <div>
            <label className={lbl}>Nome do cargo *</label>
            <input autoFocus value={form.nome} onChange={(e) => setForm({ ...form, nome: e.target.value })}
              onKeyDown={(e) => { if (e.key === "Enter" && valido) onSalvar(form); }}
              placeholder="Ex.: Garçom, Gerente, Caixa" className={inp} />
          </div>
          <div>
            <label className={lbl}>Descrição</label>
            <input value={form.descricao} onChange={(e) => setForm({ ...form, descricao: e.target.value })} placeholder="Breve descrição das funções" className={inp} />
          </div>
          <p className="text-xs text-slate-500">Disponível imediatamente no cadastro de usuários e empresas.</p>
        </div>
        <div className="shrink-0 border-t border-white/10 px-6 py-4 flex gap-3">
          <button onClick={onFechar} className="flex-1 rounded-2xl border border-white/10 bg-white/[0.06] py-3.5 text-sm font-black text-slate-300 hover:bg-white/10">Cancelar</button>
          <button onClick={() => onSalvar(form)} disabled={!valido}
            className="flex-[2] rounded-2xl bg-blue-500 py-3.5 text-sm font-black text-white hover:bg-blue-400 transition active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed">
            + Cadastrar cargo
          </button>
        </div>
      </div>
    </div>
  );
}

function CargoEditModal({ cargo, onSalvar, onFechar }) {
  const [nome, setNome] = useState(cargo.nome || "");
  const [descricao, setDescricao] = useState(cargo.descricao || "");
  const inp = "w-full rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-3 text-white outline-none focus:border-gold-400/60";
  const lbl = "mb-1.5 block text-xs font-bold uppercase tracking-widest text-slate-500";
  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/75 backdrop-blur-sm p-4" onClick={onFechar}>
      <div onClick={(e) => e.stopPropagation()} className="w-full max-w-md rounded-[2rem] border border-white/10 bg-slate-900 shadow-2xl">
        <div className="flex items-center justify-between border-b border-white/10 px-6 py-4">
          <h2 className="text-lg font-black text-white">✏️ Editar cargo</h2>
          <button onClick={onFechar} className="rounded-2xl border border-white/10 bg-white/[0.08] px-4 py-2 text-sm font-black text-slate-300 hover:bg-white/20">✕</button>
        </div>
        <div className="px-6 py-4 space-y-3">
          <div><label className={lbl}>Nome</label><input value={nome} onChange={(e) => setNome(e.target.value)} className={inp} autoFocus /></div>
          <div><label className={lbl}>Descrição</label><input value={descricao} onChange={(e) => setDescricao(e.target.value)} className={inp} /></div>
          <button onClick={() => nome.trim() && onSalvar({ nome: nome.trim(), descricao: descricao.trim() })} disabled={!nome.trim()} className="w-full rounded-2xl bg-emerald-500 py-4 text-sm font-black text-white hover:bg-emerald-400 disabled:opacity-50">💾 Salvar alterações</button>
        </div>
      </div>
    </div>
  );
}

function UserAdmin({ users, userForm, setUserForm, addUser, toggleUserStatus, editarUsuario, removerUsuario, lojaInfo, lojas = [], isSuperAdmin = false, cargos = [] }) {
  const [editando, setEditando] = useState(null);
  const [excluir, setExcluir]   = useState(null);
  const [criando, setCriando]   = useState(false);
  const [busca, setBusca]       = useState("");
  const lojasAtivas = lojas.filter((l) => l.active !== false);
  const cargosAtivos = cargos.filter((c) => c.active !== false);
  const lojaDoUser = (u) => lojas.find((l) => l.id === u.lojaId);

  // Validação para habilitar o botão (sem salvar nada antes de tudo preenchido)
  const formValido =
    (!isSuperAdmin || userForm.lojaId) &&
    userForm.name.trim() && userForm.email.trim() &&
    (userForm.password || "").length >= 4 && userForm.cargoId;

  // Lista sempre da EMPRESA EM FOCO (seletor da lateral esquerda). Para o super
  // admin, restringe pela empresa em foco; sem foco definido, mostra todas.
  const baseUsuarios = (isSuperAdmin && lojaInfo)
    ? users.filter((u) => String(u.lojaId ?? "") === String(lojaInfo.id))
    : users;
  const termo = busca.trim().toLowerCase();
  const usuariosFiltrados = baseUsuarios.filter((u) => {
    if (!termo) return true;
    return `${u.name} ${u.email} ${u.role} ${lojaDoUser(u)?.nome || ""}`.toLowerCase().includes(termo);
  });

  function abrirCadastro() {
    setUserForm({ name: "", email: "", password: "", role: "", cargoId: "", lojaId: isSuperAdmin ? "" : (lojaInfo?.id ?? "") });
    setCriando(true);
  }
  async function salvarNovo() {
    const ok = await addUser();
    if (ok) setCriando(false);
  }

  return (
    <main className="space-y-5">
      {/* ── Cabeçalho padronizado (PageHeader) ─────────────── */}
      <PageHeader
        icone={<IconUsuarios />}
        titulo="Usuários"
        descricao={!isSuperAdmin && lojaInfo ? `Equipe com acesso ao sistema — novos usuários ficam vinculados a ${lojaInfo.nome}.` : "Equipe com acesso ao sistema, com cargo, empresa e telas liberadas por permissão."}
        indicadores={[
          { valor: baseUsuarios.length, rotulo: baseUsuarios.length === 1 ? "usuário" : "usuários" },
          { valor: baseUsuarios.filter((u) => u.active).length, rotulo: "ativos", tom: "ok" },
          { valor: baseUsuarios.filter((u) => !u.active).length, rotulo: "inativos" },
        ]}
        acao={<PrimeButton onClick={abrirCadastro}><span className="text-lg leading-none">+</span> Cadastrar usuário</PrimeButton>}
      />

      {/* Busca + filtro + lista */}
      <div className="rounded-[2rem] border border-white/10 bg-white/[0.04] p-5">
        <div className="mb-4">
          <div className="relative">
            <span className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-slate-500"><IconBusca /></span>
            <input value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar por nome, e-mail, cargo ou empresa..."
              className="w-full rounded-2xl border border-white/10 bg-slate-950/70 py-3 pl-11 pr-4 text-sm text-white outline-none focus:border-gold-400/60" />
          </div>
        </div>
        <p className="mb-3 text-xs text-slate-500">{usuariosFiltrados.length} de {baseUsuarios.length} usuário(s)</p>
        <div className="space-y-2">
          {users.length === 0 && (
            <div className="py-10 text-center">
              <p className="text-sm text-slate-500">Nenhum usuário cadastrado.</p>
              <button onClick={abrirCadastro} className="mt-3 rounded-2xl border border-blue-400/30 bg-blue-500/15 px-4 py-2 text-xs font-black text-blue-200 hover:bg-blue-500/25">+ Cadastrar usuário</button>
            </div>
          )}
          {users.length > 0 && usuariosFiltrados.length === 0 && <p className="py-6 text-center text-sm text-slate-500">Nenhum usuário encontrado.</p>}
          {usuariosFiltrados.map((u) => (
            <div key={u.id} className="flex items-center gap-3 rounded-3xl border border-white/10 bg-slate-950/40 p-3">
              <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-blue-500/15 text-lg">👤</div>
              <div className="min-w-0 flex-1">
                <p className="font-black text-white truncate">{u.name}{u.superAdmin && <span className="ml-2 rounded-full bg-gold-500/20 px-2 py-0.5 text-[10px] font-black text-gold-300 align-middle">ADMIN GERAL</span>}</p>
                <p className="text-xs text-slate-400 truncate">{u.email}</p>
                <div className="mt-1 flex flex-wrap items-center gap-1.5">
                  <span className="rounded-full bg-white/[0.06] px-2 py-0.5 text-[11px] font-bold text-slate-200">🪪 {u.role || "—"}</span>
                  {isSuperAdmin && <span className="rounded-full bg-blue-500/10 px-2 py-0.5 text-[11px] font-bold text-blue-200">🏪 {lojaDoUser(u)?.nome || (u.superAdmin ? "Todas" : "Sem empresa")}</span>}
                  <span className="rounded-full bg-white/[0.04] px-2 py-0.5 text-[11px] font-bold text-slate-300">{u.accessIds.length} acesso(s)</span>
                </div>
              </div>
              <button onClick={() => toggleUserStatus(u.id)} className={`shrink-0 rounded-full px-3 py-1.5 text-xs font-black ${u.active ? "bg-emerald-500 text-white" : "bg-slate-700 text-slate-200"}`}>{u.active ? "Ativo" : "Inativo"}</button>
              <button onClick={() => setEditando(u)} className="shrink-0 rounded-xl border border-white/10 bg-white/[0.06] px-3 py-1.5 text-xs font-black text-blue-300 hover:bg-white/10">✏️</button>
              <button onClick={() => setExcluir(u)} disabled={u.superAdmin} className="shrink-0 rounded-xl border border-red-400/20 bg-red-500/10 px-3 py-1.5 text-xs font-black text-red-300 hover:bg-red-500/20 disabled:opacity-30 disabled:cursor-not-allowed">🗑️</button>
            </div>
          ))}
        </div>
      </div>

      {criando && (
        <UsuarioCadastroModal userForm={userForm} setUserForm={setUserForm} onSalvar={salvarNovo} onFechar={() => setCriando(false)}
          cargos={cargosAtivos} lojas={lojasAtivas} isSuperAdmin={isSuperAdmin} lojaInfo={lojaInfo} formValido={formValido} />
      )}
      {editando && <UsuarioEditModal usuario={editando} cargos={cargosAtivos} onSalvar={(d) => { editarUsuario(editando.id, d); setEditando(null); }} onFechar={() => setEditando(null)} />}
      {excluir && (
        <ConfirmModal titulo="Excluir usuário?"
          mensagem={`Deseja excluir o usuário "${excluir.name}" (${excluir.email})? Esta ação não pode ser desfeita.`}
          confirmar="Sim, excluir"
          onConfirmar={() => { removerUsuario(excluir.id); setExcluir(null); }}
          onCancelar={() => setExcluir(null)} />
      )}
    </main>
  );
}

// Modal de cadastro de usuário (empresa em chips p/ super admin + cargo em chips)
function UsuarioCadastroModal({ userForm, setUserForm, onSalvar, onFechar, cargos = [], lojas = [], isSuperAdmin, lojaInfo, formValido }) {
  const [verSenha, setVerSenha] = useState(false);
  const inp = "w-full rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-3 text-white outline-none focus:border-gold-400/60 placeholder:text-slate-600";
  const lbl = "mb-1.5 block text-xs font-bold uppercase tracking-widest text-slate-500";
  const chip = (sel) => `flex items-center gap-1.5 rounded-full border px-3.5 py-2 text-xs font-black transition active:scale-95 ${sel ? "border-blue-400 bg-blue-500 text-white shadow-lg shadow-blue-950/40" : "border-white/10 bg-white/[0.04] text-slate-300 hover:border-white/25 hover:bg-white/10"}`;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/75 backdrop-blur-sm p-4" onClick={onFechar}>
      <div onClick={(e) => e.stopPropagation()} className="flex w-full max-w-lg flex-col overflow-hidden rounded-[2rem] border border-white/10 bg-slate-900 shadow-2xl max-h-[92vh]">
        <div className="flex items-center justify-between border-b border-white/10 px-6 py-4">
          <div className="flex items-center gap-2">
            <span className="flex h-9 w-9 items-center justify-center rounded-2xl bg-blue-500/15 text-lg">👤</span>
            <h2 className="text-lg font-black text-white">Novo usuário</h2>
          </div>
          <button onClick={onFechar} className="rounded-2xl border border-white/10 bg-white/[0.08] px-4 py-2 text-sm font-black text-slate-300 hover:bg-white/20">✕</button>
        </div>

        <div className="flex-1 overflow-y-auto px-6 py-4 space-y-4">
          {/* Empresa (chips) — só super admin */}
          {isSuperAdmin ? (
            <div>
              <span className={lbl}>Empresa do usuário *</span>
              <div className="flex flex-wrap gap-2">
                {lojas.length === 0 && <p className="text-xs text-amber-300">Nenhuma empresa ativa.</p>}
                {lojas.map((l) => {
                  const sel = userForm.lojaId === l.id;
                  return <button key={l.id} type="button" onClick={() => setUserForm({ ...userForm, lojaId: l.id })} className={chip(sel)}>{sel && <span className="text-[11px]">✓</span>}{l.nome}</button>;
                })}
              </div>
            </div>
          ) : (lojaInfo && (
            <p className="rounded-2xl border border-white/10 bg-white/[0.03] px-4 py-2.5 text-xs text-slate-400">Vinculado à empresa <b className="text-blue-300">{lojaInfo.nome}</b> <span className="font-mono text-slate-500">({lojaInfo.prefixo})</span></p>
          ))}

          <div>
            <span className={lbl}>Nome *</span>
            <input autoFocus value={userForm.name} onChange={(e) => setUserForm({ ...userForm, name: e.target.value })} placeholder="Nome do usuário" className={inp} autoComplete="off" name="novo_usuario_nome" />
          </div>
          <div className="grid gap-3 sm:grid-cols-2">
            <div>
              <span className={lbl}>E-mail *</span>
              <input value={userForm.email} onChange={(e) => setUserForm({ ...userForm, email: e.target.value })} placeholder="usuario@empresa.com" className={inp} autoComplete="off" name="novo_usuario_email" />
            </div>
            <div>
              <span className={lbl}>Senha * (mín. 4)</span>
              <div className="relative">
                <input type={verSenha ? "text" : "password"} value={userForm.password} onChange={(e) => setUserForm({ ...userForm, password: e.target.value })} placeholder="Defina a senha" className={`${inp} pr-12`} autoComplete="new-password" name="novo_usuario_senha" />
                <button type="button" onClick={() => setVerSenha((v) => !v)} className="absolute right-3 top-1/2 -translate-y-1/2 text-sm text-slate-400 hover:text-white">{verSenha ? "🙈" : "👁️"}</button>
              </div>
            </div>
          </div>

          {/* Cargo (chips) */}
          <div>
            <span className={lbl}>Cargo / Perfil *</span>
            <div className="flex flex-wrap gap-2">
              {cargos.length === 0 && <p className="text-xs text-amber-300">Nenhum cargo ativo. Cadastre em “Cargos / Perfis”.</p>}
              {cargos.map((c) => {
                const sel = userForm.cargoId === c.id;
                return <button key={c.id} type="button" onClick={() => setUserForm({ ...userForm, cargoId: c.id, role: c.nome })} className={chip(sel)}>{sel && <span className="text-[11px]">✓</span>}{c.nome}</button>;
              })}
            </div>
          </div>
        </div>

        <div className="shrink-0 border-t border-white/10 px-6 py-4 flex gap-3">
          <button onClick={onFechar} className="flex-1 rounded-2xl border border-white/10 bg-white/[0.06] py-3.5 text-sm font-black text-slate-300 hover:bg-white/10">Cancelar</button>
          <button onClick={onSalvar} disabled={!formValido}
            className="flex-[2] rounded-2xl bg-blue-500 py-3.5 text-sm font-black text-white hover:bg-blue-400 transition active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed">
            + Cadastrar usuário
          </button>
        </div>
      </div>
    </div>
  );
}

function UsuarioEditModal({ usuario, cargos = [], onSalvar, onFechar }) {
  const [f, setF] = useState({ name: usuario.name, email: usuario.email, password: usuario.password, role: usuario.role, cargoId: usuario.cargoId ?? "" });
  const [verSenha, setVerSenha] = useState(false);
  const inp = "w-full rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-3 text-white outline-none focus:border-gold-400/60";
  const lbl = "mb-1.5 block text-xs font-bold uppercase tracking-widest text-slate-500";
  const valido = f.name.trim() && f.email.trim() && (f.password || "").length >= 4 && f.cargoId;
  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/75 backdrop-blur-sm p-4" onClick={onFechar}>
      <div onClick={(e) => e.stopPropagation()} className="w-full max-w-md rounded-[2rem] border border-white/10 bg-slate-900 shadow-2xl">
        <div className="flex items-center justify-between border-b border-white/10 px-6 py-4">
          <h2 className="text-lg font-black text-white">✏️ Editar usuário</h2>
          <button onClick={onFechar} className="rounded-2xl border border-white/10 bg-white/[0.08] px-4 py-2 text-sm font-black text-slate-300 hover:bg-white/20">✕</button>
        </div>
        <div className="px-6 py-4 space-y-3">
          <div><label className={lbl}>Nome</label><input value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} placeholder="Nome" className={inp} /></div>
          <div><label className={lbl}>E-mail</label><input value={f.email} onChange={(e) => setF({ ...f, email: e.target.value })} placeholder="E-mail" className={inp} /></div>
          <div>
            <label className={lbl}>Senha (mín. 4)</label>
            <div className="relative">
              <input type={verSenha ? "text" : "password"} value={f.password} onChange={(e) => setF({ ...f, password: e.target.value })} placeholder="Senha" className={`${inp} pr-12`} />
              <button type="button" onClick={() => setVerSenha((v) => !v)} className="absolute right-3 top-1/2 -translate-y-1/2 text-sm text-slate-400 hover:text-white">{verSenha ? "🙈" : "👁️"}</button>
            </div>
          </div>
          <div>
            <label className={lbl}>Cargo / Perfil</label>
            <select value={f.cargoId ?? ""} onChange={(e) => { const id = e.target.value ? Number(e.target.value) : ""; const c = cargos.find((x) => x.id === id); setF({ ...f, cargoId: id, role: c?.nome || f.role }); }} className={inp}>
              <option value="">Selecione o cargo…</option>
              {cargos.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}
            </select>
          </div>
          <button onClick={() => valido && onSalvar(f)} disabled={!valido} className="w-full rounded-2xl bg-emerald-500 py-4 text-sm font-black text-white hover:bg-emerald-400 disabled:opacity-50">💾 Salvar alterações</button>
        </div>
      </div>
    </div>
  );
}

function AccessAdmin({ accesses, accessForm, setAccessForm, addAccess, toggleAccessStatus }) {
  const [criando, setCriando] = useState(false);
  const [busca, setBusca]     = useState("");

  function abrirCadastro() {
    setAccessForm({ id: "", label: "", desc: "", type: "Operacional" });
    setCriando(true);
  }
  async function salvarNovo() {
    const ok = await addAccess();
    if (ok) setCriando(false);
  }

  const termo = busca.trim().toLowerCase();
  const filtrados = termo ? accesses.filter((a) => `${a.label} ${a.id} ${a.type} ${a.desc}`.toLowerCase().includes(termo)) : accesses;

  return (
    <main className="space-y-5">
      {/* ── Cabeçalho padronizado (PageHeader) ─────────────── */}
      <PageHeader
        icone={<IconPermissoes />}
        titulo="Permissões"
        descricao="Códigos de telas e módulos que controlam o menu exibido para cada usuário."
        indicadores={[
          { valor: accesses.length, rotulo: accesses.length === 1 ? "permissão" : "permissões" },
          { valor: accesses.filter((a) => a.active).length, rotulo: "ativas", tom: "ok" },
          { valor: accesses.filter((a) => !a.active).length, rotulo: "inativas" },
        ]}
        acao={<PrimeButton onClick={abrirCadastro}><span className="text-lg leading-none">+</span> Cadastrar permissão</PrimeButton>}
      />

      {/* Busca + lista */}
      <div className="rounded-[2rem] border border-white/10 bg-white/[0.04] p-5">
        <div className="relative mb-4">
          <span className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-slate-500"><IconBusca /></span>
          <input value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar permissão..."
            className="w-full rounded-2xl border border-white/10 bg-slate-950/70 py-3 pl-11 pr-4 text-sm text-white outline-none focus:border-gold-400/60" />
        </div>
        <div className="space-y-2">
          {accesses.length === 0 && (
            <div className="py-10 text-center">
              <p className="text-sm text-slate-500">Nenhuma permissão cadastrada.</p>
              <button onClick={abrirCadastro} className="mt-3 rounded-2xl border border-blue-400/30 bg-blue-500/15 px-4 py-2 text-xs font-black text-blue-200 hover:bg-blue-500/25">+ Cadastrar permissão</button>
            </div>
          )}
          {accesses.length > 0 && filtrados.length === 0 && <p className="py-6 text-center text-sm text-slate-500">Nenhuma permissão encontrada.</p>}
          {filtrados.map((a) => (
            <div key={a.id} className="flex items-center gap-3 rounded-3xl border border-white/10 bg-slate-950/40 p-3">
              <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-white/[0.06] text-lg">🔐</span>
              <div className="min-w-0 flex-1">
                <p className="font-black text-white truncate">{a.label}</p>
                <p className="text-xs text-slate-400 truncate">
                  <span className="font-mono text-blue-300">{a.id}</span>{a.type ? ` • ${a.type}` : ""}
                </p>
                {a.desc && <p className="text-[11px] text-slate-500 truncate">{a.desc}</p>}
              </div>
              <button onClick={() => toggleAccessStatus(a.id)} className={`shrink-0 rounded-full px-3 py-1.5 text-xs font-black ${a.active ? "bg-emerald-500 text-white" : "bg-slate-700 text-slate-200"}`}>{a.active ? "Ativa" : "Inativa"}</button>
            </div>
          ))}
        </div>
      </div>

      {criando && <PermissaoCadastroModal accessForm={accessForm} setAccessForm={setAccessForm} onSalvar={salvarNovo} onFechar={() => setCriando(false)} />}
    </main>
  );
}

// Modal de cadastro de permissão de acesso (mesmo padrão dos demais)
function PermissaoCadastroModal({ accessForm, setAccessForm, onSalvar, onFechar }) {
  const inp = "w-full rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-3 text-white outline-none focus:border-gold-400/60 placeholder:text-slate-600";
  const lbl = "mb-1.5 block text-xs font-bold uppercase tracking-widest text-slate-500";
  const valido = (accessForm.id || "").trim() && (accessForm.label || "").trim();
  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/75 backdrop-blur-sm p-4" onClick={onFechar}>
      <div onClick={(e) => e.stopPropagation()} className="flex w-full max-w-md flex-col overflow-hidden rounded-[2rem] border border-white/10 bg-slate-900 shadow-2xl">
        <div className="flex items-center justify-between border-b border-white/10 px-6 py-4">
          <div className="flex items-center gap-2">
            <span className="flex h-9 w-9 items-center justify-center rounded-2xl bg-blue-500/15 text-lg">🔐</span>
            <h2 className="text-lg font-black text-white">Nova permissão</h2>
          </div>
          <button onClick={onFechar} className="rounded-2xl border border-white/10 bg-white/[0.08] px-4 py-2 text-sm font-black text-slate-300 hover:bg-white/20">✕</button>
        </div>
        <div className="px-6 py-5 space-y-3">
          <div>
            <label className={lbl}>Código do acesso *</label>
            <input autoFocus value={accessForm.id} onChange={(e) => setAccessForm({ ...accessForm, id: e.target.value })} placeholder="Ex.: relatorios" className={`${inp} font-mono`} />
            <p className="mt-1 text-[11px] text-slate-500">Sem espaços/acentos — usado internamente para montar o menu.</p>
          </div>
          <div>
            <label className={lbl}>Nome do acesso *</label>
            <input value={accessForm.label} onChange={(e) => setAccessForm({ ...accessForm, label: e.target.value })} placeholder="Ex.: Relatórios" className={inp} />
          </div>
          <div className="grid gap-3 sm:grid-cols-2">
            <div>
              <label className={lbl}>Tipo / grupo</label>
              <input value={accessForm.type} onChange={(e) => setAccessForm({ ...accessForm, type: e.target.value })} placeholder="Ex.: Operacional" className={inp} />
            </div>
            <div>
              <label className={lbl}>Descrição</label>
              <input value={accessForm.desc} onChange={(e) => setAccessForm({ ...accessForm, desc: e.target.value })} placeholder="Breve descrição" className={inp} />
            </div>
          </div>
        </div>
        <div className="shrink-0 border-t border-white/10 px-6 py-4 flex gap-3">
          <button onClick={onFechar} className="flex-1 rounded-2xl border border-white/10 bg-white/[0.06] py-3.5 text-sm font-black text-slate-300 hover:bg-white/10">Cancelar</button>
          <button onClick={onSalvar} disabled={!valido}
            className="flex-[2] rounded-2xl bg-blue-500 py-3.5 text-sm font-black text-white hover:bg-blue-400 transition active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed">
            + Cadastrar permissão
          </button>
        </div>
      </div>
    </div>
  );
}

function UserAccessAdmin({ users, accesses, toggleUserAccess, definirAcessos, definirAcoesUsuario = async()=>{}, lojaInfo = null, lojas = [], isSuperAdmin = false }) {
  const [busca, setBusca]     = useState("");
  const [editandoId, setEditandoId] = useState(null); // usuário aberto no modal
  const [pagina, setPagina]   = useState(1);
  const POR_PAGINA = 10;
  const nomeLoja = (id) => lojas.find((l) => l.id === id)?.nome || "Sem empresa";
  const prefLoja = (id) => lojas.find((l) => l.id === id)?.prefixo || "—";
  const acessosAtivos = accesses.filter((a) => a.active !== false);

  // Lista sempre da EMPRESA EM FOCO (seletor da lateral esquerda). Para o super
  // admin, restringe pela empresa em foco; sem foco definido, mostra todas.
  const baseUsuarios = (isSuperAdmin && lojaInfo)
    ? users.filter((u) => String(u.lojaId ?? "") === String(lojaInfo.id))
    : users;
  const termo = busca.trim().toLowerCase();
  const filtrados = baseUsuarios.filter((u) => {
    if (!termo) return true;
    return `${u.name} ${u.email} ${u.role} ${nomeLoja(u.lojaId)} ${prefLoja(u.lojaId)}`.toLowerCase().includes(termo);
  });
  const comAcesso = baseUsuarios.filter((u) => u.accessIds.length > 0).length;
  const editando = users.find((u) => u.id === editandoId) || null; // live (reflete toggles)

  // Paginação: 10 registros por página
  const totalPaginas = Math.max(1, Math.ceil(filtrados.length / POR_PAGINA));
  useEffect(() => { setPagina(1); }, [busca, baseUsuarios.length]);
  const paginaAtual = Math.min(pagina, totalPaginas);
  const visiveis = filtrados.slice((paginaAtual - 1) * POR_PAGINA, paginaAtual * POR_PAGINA);

  return (
    <main className="space-y-5">
      {/* ── Cabeçalho padronizado (PageHeader) ─────────────── */}
      <PageHeader
        icone={<IconLink />}
        titulo="Usuário × Acesso"
        descricao="Clique em um usuário para liberar as telas que ele pode acessar. O menu de cada usuário é montado apenas com as telas liberadas aqui."
        indicadores={[
          { valor: baseUsuarios.length, rotulo: baseUsuarios.length === 1 ? "usuário" : "usuários" },
          { valor: comAcesso, rotulo: "com acesso liberado", tom: "ok" },
          { valor: baseUsuarios.length - comAcesso, rotulo: "sem acessos", tom: baseUsuarios.length - comAcesso > 0 ? "alerta" : undefined },
        ]}
      />

      {/* ── Busca + lista (largura total — padrão do projeto) ── */}
      <div className="rounded-[2rem] border border-white/10 bg-white/[0.04] p-5">
        <div className="mb-4">
          <div className="relative flex-1">
            <span className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-slate-500"><IconBusca /></span>
            <input value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar usuário por nome, e-mail ou cargo..."
              className="w-full rounded-2xl border border-white/10 bg-slate-950/70 py-3 pl-11 pr-4 text-sm text-white outline-none focus:border-gold-400/60" />
          </div>
        </div>

        <div className="space-y-2">
          {filtrados.length === 0 && <p className="py-8 text-center text-sm text-slate-500">Nenhum usuário encontrado.</p>}
          {visiveis.map((u) => (
            <div key={u.id}
              onClick={() => setEditandoId(u.id)}
              className="group flex cursor-pointer items-center gap-3 rounded-3xl border border-white/10 bg-slate-950/40 p-3 transition hover:border-blue-400/30 hover:bg-white/[0.06]">
              <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-2xl bg-white/[0.06] text-lg group-hover:bg-blue-500/15 transition">👤</span>
              <div className="min-w-0 flex-1">
                <p className="font-black text-white truncate">
                  {u.name}
                  {u.superAdmin && <span className="ml-2 rounded-full bg-gold-500/20 px-2 py-0.5 text-[10px] font-black text-gold-300 align-middle">ADMIN GERAL</span>}
                </p>
                <p className="truncate text-xs text-slate-400">{u.email} · {u.role || "—"}{isSuperAdmin ? ` · ${nomeLoja(u.lojaId)}` : ""}</p>
              </div>
              <span className="shrink-0 text-xs text-slate-600 group-hover:text-blue-400 transition hidden sm:inline">✏️ Gerenciar</span>
              <span className={`shrink-0 rounded-full px-3 py-1 text-xs font-black ${u.accessIds.length > 0 ? "bg-emerald-500/15 text-emerald-300" : "bg-slate-700 text-slate-300"}`}>
                {u.accessIds.length}/{acessosAtivos.length} telas
              </span>
            </div>
          ))}
        </div>

        {filtrados.length > POR_PAGINA && (
          <Paginacao pagina={paginaAtual} totalPaginas={totalPaginas} total={filtrados.length}
            porPagina={POR_PAGINA} onMudar={setPagina} rotulo="usuário(s)" />
        )}
      </div>

      {editando && (
        <UserAccessModal
          usuario={editando}
          acessosAtivos={acessosAtivos}
          nomeLoja={nomeLoja}
          toggleUserAccess={toggleUserAccess}
          definirAcessos={definirAcessos} definirAcoesUsuario={definirAcoesUsuario}
          outrosUsuarios={users.filter((u) => u.id !== editando.id && (u.accessIds || []).length > 0)}
          onFechar={() => setEditandoId(null)}
        />
      )}
    </main>
  );
}

// Modal de gestão de acessos de um usuário (padrão de modal do projeto)
function UserAccessModal({ usuario, acessosAtivos = [], nomeLoja, toggleUserAccess, definirAcessos, definirAcoesUsuario = async () => {}, outrosUsuarios = [], onFechar }) {
  const liberadas = usuario.accessIds.length;
  const total = acessosAtivos.length;
  const [qrAberto, setQrAberto] = useState(false);
  // Matriz de ações por módulo (item 23) — mapa local sincronizado com o usuário
  const [acoes, setAcoes] = useState(usuario.permissoesAcoes || {});
  const [expandido, setExpandido] = useState(null); // id do módulo com a matriz aberta
  // ações de um módulo; se não configurado, considera todas liberadas
  const acoesDe = (mid) => Array.isArray(acoes[mid]) ? acoes[mid] : ACOES_MODULO.map(([k]) => k);
  const configurado = (mid) => Array.isArray(acoes[mid]);
  function toggleAcao(mid, acao) {
    setAcoes((cur) => {
      const atual = Array.isArray(cur[mid]) ? cur[mid] : ACOES_MODULO.map(([k]) => k);
      const novo = atual.includes(acao) ? atual.filter((x) => x !== acao) : [...atual, acao];
      const mapa = { ...cur, [mid]: novo };
      definirAcoesUsuario(usuario.id, mapa);
      return mapa;
    });
  }
  function resetarAcoes(mid) {
    setAcoes((cur) => { const mapa = { ...cur }; delete mapa[mid]; definirAcoesUsuario(usuario.id, mapa); return mapa; });
  }
  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/75 backdrop-blur-sm p-4" onClick={onFechar}>
      <div onClick={(e) => e.stopPropagation()} className="flex w-full max-w-lg flex-col overflow-hidden rounded-[2rem] border border-white/10 bg-slate-900 shadow-2xl max-h-[92vh]">
        {/* Cabeçalho */}
        <div className="flex items-start justify-between gap-3 border-b border-white/10 px-6 py-4">
          <div className="min-w-0">
            <h2 className="text-lg font-black text-white">
              {usuario.name}
              {usuario.superAdmin && <span className="ml-2 rounded-full bg-gold-500/20 px-2 py-0.5 text-[10px] font-black text-gold-300 align-middle">ADMIN GERAL</span>}
            </h2>
            <p className="text-sm text-slate-400 truncate">{usuario.email}</p>
            <div className="mt-2 flex flex-wrap items-center gap-1.5">
              <span className="rounded-full bg-white/[0.06] px-2.5 py-0.5 text-xs font-bold text-slate-200">🪪 {usuario.role || "—"}</span>
              <span className="rounded-full bg-blue-500/10 px-2.5 py-0.5 text-xs font-bold text-blue-200">🏪 {usuario.superAdmin ? "Todas" : nomeLoja(usuario.lojaId)}</span>
              <span className={`rounded-full px-2.5 py-0.5 text-xs font-bold ${usuario.active ? "bg-emerald-500/15 text-emerald-300" : "bg-slate-700 text-slate-300"}`}>{usuario.active ? "Ativo" : "Inativo"}</span>
            </div>
          </div>
          <div className="flex shrink-0 items-center gap-3">
            <div className="text-right">
              <p className="text-2xl font-black text-white leading-none">{liberadas}<span className="text-sm text-slate-500">/{total}</span></p>
              <p className="mt-0.5 text-[10px] font-bold uppercase tracking-widest text-slate-500">telas</p>
            </div>
            <button onClick={onFechar} className="rounded-2xl border border-white/10 bg-white/[0.08] px-4 py-2 text-sm font-black text-slate-300 hover:bg-white/20">✕</button>
          </div>
        </div>

        {/* Corpo */}
        <div className="flex-1 overflow-y-auto px-6 py-4 space-y-3">
          <div className="flex flex-wrap items-center gap-2">
            <button onClick={() => definirAcessos(usuario.id, acessosAtivos.map((a) => a.id))}
              className="rounded-2xl border border-emerald-400/30 bg-emerald-500/15 px-4 py-2 text-xs font-black text-emerald-200 hover:bg-emerald-500/25 transition">✓ Liberar todas</button>
            <button onClick={() => definirAcessos(usuario.id, [])}
              className="rounded-2xl border border-red-400/30 bg-red-500/10 px-4 py-2 text-xs font-black text-red-300 hover:bg-red-500/20 transition">✕ Bloquear todas</button>
            {/* Copiar o conjunto de acessos de outro usuário (item 24 do padrão SaaS) */}
            {outrosUsuarios.length > 0 && (
              <select defaultValue=""
                onChange={(e) => { const u = outrosUsuarios.find((x) => String(x.id) === e.target.value); if (u) definirAcessos(usuario.id, [...(u.accessIds || [])]); e.target.value = ""; }}
                className="rounded-2xl border border-gold-400/30 bg-gold-400/10 px-3 py-2 text-xs font-black text-gold-200 outline-none focus:border-gold-400">
                <option value="" disabled>Copiar acesso de outro usuário…</option>
                {outrosUsuarios.map((u) => <option key={u.id} value={u.id}>{u.name} ({(u.accessIds || []).length} tela{(u.accessIds || []).length === 1 ? "" : "s"})</option>)}
              </select>
            )}
          </div>

          <div className="space-y-2">
            {acessosAtivos.length === 0 && <p className="text-sm text-slate-500">Nenhuma permissão ativa cadastrada.</p>}
            {acessosAtivos.map((a) => {
              const checked = usuario.accessIds.includes(a.id);
              const aberto = expandido === a.id;
              return (
                <div key={a.id} className={`rounded-2xl border transition ${checked ? "border-emerald-400/30 bg-emerald-500/10" : "border-white/10 bg-slate-950/40"}`}>
                  <div className="flex w-full items-center justify-between gap-3 p-3.5">
                    <button onClick={() => toggleUserAccess(usuario.id, a.id)} className="flex min-w-0 flex-1 items-center justify-between gap-3 text-left">
                      <div className="min-w-0">
                        <p className={`text-sm font-black ${checked ? "text-emerald-100" : "text-white"}`}>{a.label}</p>
                        {a.desc && <p className="mt-0.5 truncate text-xs text-slate-400">{a.desc}</p>}
                      </div>
                      <span className={`relative h-6 w-11 shrink-0 rounded-full transition ${checked ? "bg-emerald-500" : "bg-slate-700"}`}>
                        <span className={`absolute top-0.5 h-5 w-5 rounded-full bg-white shadow transition-all ${checked ? "left-[22px]" : "left-0.5"}`} />
                      </span>
                    </button>
                    {/* Abre a matriz de ações do módulo (só quando a tela está liberada) */}
                    {checked && (
                      <button onClick={() => setExpandido(aberto ? null : a.id)} title="Ações do módulo"
                        className={`shrink-0 rounded-xl border px-2.5 py-1.5 text-[10px] font-black transition ${configurado(a.id) ? "border-gold-400/50 bg-gold-400/10 text-gold-300" : "border-white/10 bg-white/[0.06] text-slate-400"}`}>
                        {configurado(a.id) ? `${acoesDe(a.id).length}/${ACOES_MODULO.length}` : "ações"} {aberto ? "▴" : "▾"}
                      </button>
                    )}
                  </div>
                  {/* Matriz de ações (item 23 — migration 032) */}
                  {checked && aberto && (
                    <div className="border-t border-white/10 px-3.5 py-3">
                      <div className="flex flex-wrap gap-1.5">
                        {ACOES_MODULO.map(([k, label]) => {
                          const on = acoesDe(a.id).includes(k);
                          return (
                            <button key={k} onClick={() => toggleAcao(a.id, k)}
                              className={`rounded-lg border px-2.5 py-1.5 text-[11px] font-bold transition ${on ? "border-gold-400/60 bg-gold-400/10 text-gold-200" : "border-white/10 bg-white/[0.03] text-slate-500"}`}>
                              <span className={`mr-1 ${on ? "" : "opacity-40"}`}>{on ? "✓" : "○"}</span>{label}
                            </button>
                          );
                        })}
                      </div>
                      <div className="mt-2 flex items-center justify-between">
                        <p className="text-[10px] text-slate-500">{configurado(a.id) ? "Ações personalizadas para este usuário." : "Todas as ações liberadas (padrão)."}</p>
                        {configurado(a.id) && <button onClick={() => resetarAcoes(a.id)} className="text-[10px] font-bold text-slate-400 underline hover:text-white">Restaurar padrão</button>}
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        {/* Rodapé */}
        <div className="shrink-0 border-t border-white/10 px-6 py-4 flex gap-3">
          <button onClick={() => setQrAberto(true)}
            className="flex-1 rounded-2xl border border-gold-400/30 bg-gold-500/15 py-3.5 text-sm font-black text-gold-200 hover:bg-gold-500/25 transition active:scale-95">
            🔐 QR de login
          </button>
          <button onClick={onFechar} className="flex-1 rounded-2xl bg-blue-500 py-3.5 text-sm font-black text-white hover:bg-blue-400 transition active:scale-95">Concluir</button>
        </div>
      </div>

      {qrAberto && (
        <QRLoginCardModal usuario={usuario} nomeEmpresa={usuario.superAdmin ? "Todas as empresas" : nomeLoja(usuario.lojaId)} onFechar={() => setQrAberto(false)} />
      )}
    </div>
  );
}

// ════════════════════════════════════════════════════════════
//  Cartão de QR de login (gerar / imprimir) — Usuário × Acesso
// ════════════════════════════════════════════════════════════
function QRLoginCardModal({ usuario, nomeEmpresa, onFechar }) {
  const [qrUrl, setQrUrl]   = useState("");
  const [imgUrl, setImgUrl] = useState("");   // imagem opcional (data URL ou link)
  const [erroImg, setErroImg] = useState("");
  const [urlInput, setUrlInput] = useState("");
  const payload = gerarLoginQRTexto(usuario);

  // Gera o QR (data URL) a partir do payload de login
  useEffect(() => {
    let vivo = true;
    (async () => {
      try {
        const QRCode = (await import("qrcode")).default;
        const url = await QRCode.toDataURL(payload, { width: 520, margin: 1, errorCorrectionLevel: "M", color: { dark: "#0f172a", light: "#ffffff" } });
        if (vivo) setQrUrl(url);
      } catch { /* ignora */ }
    })();
    return () => { vivo = false; };
  }, [payload]);

  // Upload de imagem local (PNG/JPEG, máx. 2MB) → data URL
  function aoEscolherArquivo(e) {
    const f = e.target.files?.[0];
    if (!f) return;
    setErroImg("");
    const tiposOk = ["image/png", "image/jpeg"];
    if (!tiposOk.includes(f.type)) { setErroImg("Use uma imagem PNG ou JPEG."); return; }
    if (f.size > 2 * 1024 * 1024) { setErroImg("A imagem deve ter no máximo 2 MB."); return; }
    const reader = new FileReader();
    reader.onload = () => setImgUrl(String(reader.result || ""));
    reader.readAsDataURL(f);
  }
  function aplicarUrl() {
    const u = urlInput.trim();
    if (!u) return;
    if (!/^https?:\/\//i.test(u)) { setErroImg("Informe uma URL http(s) válida."); return; }
    setErroImg(""); setImgUrl(u);
  }

  function imprimir() {
    const w = window.open("", "_blank", "width=420,height=640");
    if (!w) return;
    const imgHtml = imgUrl ? `<img src="${imgUrl}" alt="" style="width:84px;height:84px;border-radius:18px;object-fit:cover;border:1px solid #e2e8f0" />` : "";
    w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>QR de login — ${usuario.name}</title>
      <style>
        *{box-sizing:border-box;font-family:Arial,Helvetica,sans-serif}
        body{margin:0;padding:24px;color:#0f172a;display:flex;justify-content:center}
        .card{width:340px;border:1px solid #e2e8f0;border-radius:22px;padding:24px;text-align:center}
        .top{display:flex;align-items:center;gap:12px;justify-content:center;margin-bottom:14px}
        .nome{font-size:20px;font-weight:800;margin:0}
        .sub{margin:2px 0 0;color:#475569;font-size:13px;font-weight:700}
        .qr{margin:14px auto 6px;width:240px;height:240px}
        .qr img{width:100%;height:100%}
        .rodape{margin-top:8px;color:#667085;font-size:11px;font-weight:700}
        .marca{margin-top:4px;color:#94a3b8;font-size:10px}
      </style></head><body>
      <div class="card">
        <div class="top">${imgHtml}<div style="text-align:left">
          <p class="nome">${usuario.name}</p>
          <p class="sub">${nomeEmpresa || ""}</p>
          <p class="sub" style="color:#7c3aed">${usuario.role || "—"}</p>
        </div></div>
        <div class="qr"><img src="${qrUrl}" alt="QR de login" /></div>
        <p class="rodape">Aponte na tela de login → "Entrar com QR Code"</p>
        <p class="marca">Pedido Prime • Acesso por QR</p>
      </div>
      <script>window.onload=function(){setTimeout(function(){window.print()},250)}</script>
      </body></html>`);
    w.document.close();
  }

  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/80 backdrop-blur-sm p-4" onClick={onFechar}>
      <div onClick={(e) => e.stopPropagation()} className="flex w-full max-w-md flex-col overflow-hidden rounded-[2rem] border border-white/10 bg-slate-900 shadow-2xl max-h-[92vh]">
        <div className="flex items-center justify-between border-b border-white/10 px-6 py-4">
          <h2 className="text-lg font-black text-white">🔐 QR de login</h2>
          <button onClick={onFechar} className="rounded-2xl border border-white/10 bg-white/[0.08] px-4 py-2 text-sm font-black text-slate-300 hover:bg-white/20">✕</button>
        </div>

        <div className="flex-1 overflow-y-auto px-6 py-5 space-y-4">
          {/* Cartão de visualização */}
          <div className="rounded-3xl border border-white/10 bg-white p-5 text-center text-slate-900">
            <div className="flex items-center justify-center gap-3">
              {imgUrl
                ? <img src={imgUrl} alt="" className="h-16 w-16 rounded-2xl object-cover border border-slate-200" />
                : <span className="flex h-16 w-16 items-center justify-center rounded-2xl bg-slate-100 text-2xl">👤</span>}
              <div className="text-left">
                <p className="text-lg font-black leading-tight">{usuario.name}</p>
                <p className="text-xs font-bold text-slate-500">{nomeEmpresa}</p>
                <p className="text-xs font-bold text-gold-600">{usuario.role || "—"}</p>
              </div>
            </div>
            <div className="mx-auto mt-4 h-48 w-48">
              {qrUrl ? <img src={qrUrl} alt="QR de login" className="h-full w-full" /> : <div className="flex h-full w-full items-center justify-center text-xs text-slate-400">gerando QR…</div>}
            </div>
            <p className="mt-2 text-[11px] font-bold text-slate-500">Login rápido • aponte na tela de login</p>
          </div>

          {/* Imagem opcional (URL ou arquivo PNG/JPEG ≤ 2MB) */}
          <div className="space-y-2">
            <p className="text-[11px] font-bold uppercase tracking-widest text-slate-500">Imagem (opcional) — PNG/JPEG, máx. 2 MB</p>
            <div className="flex gap-2">
              <input value={urlInput} onChange={(e) => setUrlInput(e.target.value)} placeholder="Cole uma URL https://…"
                className="w-full rounded-2xl border border-white/10 bg-slate-950/70 px-3 py-2.5 text-xs text-white outline-none focus:border-gold-400/60 placeholder:text-slate-600" />
              <button onClick={aplicarUrl} className="shrink-0 rounded-2xl border border-white/10 bg-white/[0.06] px-3 py-2.5 text-xs font-black text-slate-200 hover:bg-white/10">Usar</button>
            </div>
            <label className="flex cursor-pointer items-center justify-center gap-2 rounded-2xl border border-blue-400/30 bg-blue-500/10 px-3 py-2.5 text-xs font-black text-blue-200 hover:bg-blue-500/20 transition">
              📁 Escolher arquivo do dispositivo
              <input type="file" accept="image/png,image/jpeg" onChange={aoEscolherArquivo} className="hidden" />
            </label>
            {imgUrl && <button onClick={() => { setImgUrl(""); setUrlInput(""); }} className="text-[11px] font-bold text-slate-500 hover:text-red-300">Remover imagem</button>}
            {erroImg && <p className="text-xs font-bold text-red-300">{erroImg}</p>}
          </div>
        </div>

        <div className="shrink-0 border-t border-white/10 px-6 py-4 flex gap-3">
          <button onClick={onFechar} className="flex-1 rounded-2xl border border-white/10 bg-white/[0.06] py-3.5 text-sm font-black text-slate-300 hover:bg-white/10">Fechar</button>
          <button onClick={imprimir} disabled={!qrUrl}
            className="flex-[1.5] rounded-2xl bg-blue-500 py-3.5 text-sm font-black text-white hover:bg-blue-400 transition active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed">
            🖨️ Imprimir QR de login
          </button>
        </div>
      </div>
    </div>
  );
}

// ════════════════════════════════════════════════════════════
//  Admin — Mesas (cadastro, edição, inativar, excluir)
// ════════════════════════════════════════════════════════════
function MesaAdmin({ mesas = [], addMesa, editarMesa, toggleMesa, removerMesa, orders = [] }) {
  const [editando, setEditando] = useState(null);
  const [excluir, setExcluir]   = useState(null);
  const [criando, setCriando]   = useState(false);
  const [busca, setBusca]       = useState("");

  const termo = busca.trim().toLowerCase();
  const filtradas = termo
    ? mesas.filter((m) => `${String(m.numero).padStart(2,"0")} ${m.nome}`.toLowerCase().includes(termo))
    : mesas;
  const mesasOrdenadas = [...filtradas].sort((a, b) => a.numero - b.numero);

  const abertosDaMesa = (mesa) => {
    const label = `Mesa ${String(mesa.numero).padStart(2, "0")}`;
    return orders.filter((o) => o.table === label && o.paymentStatus !== "paid" && o.status !== "cancelled");
  };
  const pedidosAbertos = (mesa) => abertosDaMesa(mesa).length;
  const valorMesa = (mesa) => abertosDaMesa(mesa).reduce((s, o) => s + orderTotal(o), 0);

  async function salvarNova(form) {
    const ok = await addMesa(form);
    if (ok) setCriando(false);
  }

  return (
    <main className="space-y-5">
      {/* ── Cabeçalho padronizado (PageHeader) ─────────────── */}
      <PageHeader
        icone={<IconMesas />}
        titulo="Mesas"
        descricao="Controle as mesas disponíveis, ocupadas, inativas e vinculadas ao tablet ou QR Code."
        indicadores={[
          { valor: mesas.length, rotulo: mesas.length === 1 ? "mesa" : "mesas" },
          { valor: mesas.filter((m) => m.active !== false && pedidosAbertos(m) === 0).length, rotulo: "disponíveis", tom: "ok" },
          { valor: mesas.filter((m) => m.active !== false && pedidosAbertos(m) > 0).length, rotulo: "ocupadas", tom: "alerta" },
          { valor: mesas.filter((m) => m.active === false).length, rotulo: mesas.filter((m) => m.active === false).length === 1 ? "inativa" : "inativas" },
        ]}
        acao={<PrimeButton onClick={() => setCriando(true)}><span className="text-lg leading-none">+</span> Cadastrar mesa</PrimeButton>}
      />

      {/* Cards de resumo */}
      <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
        {[
          { l: "Total de mesas", v: mesas.length, tom: "text-white" },
          { l: "Disponíveis", v: mesas.filter((m) => m.active !== false && pedidosAbertos(m) === 0).length, tom: "text-emerald-400" },
          { l: "Ocupadas", v: mesas.filter((m) => m.active !== false && pedidosAbertos(m) > 0).length, tom: "text-amber-400" },
          { l: "Inativas", v: mesas.filter((m) => m.active === false).length, tom: "text-slate-300" },
        ].map((c) => (
          <div key={c.l} className="rounded-2xl border border-white/10 bg-white/[0.04] p-4">
            <p className="text-[10px] font-bold uppercase tracking-widest text-slate-500">{c.l}</p>
            <p className={`page-title mt-1.5 text-2xl font-black ${c.tom}`}>{c.v}</p>
          </div>
        ))}
      </div>

      {/* Busca + lista */}
      <div className="rounded-[2rem] border border-white/10 bg-white/[0.04] p-5">
        <div className="relative mb-4">
          <span className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-slate-500"><IconBusca /></span>
          <input value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar por número ou nome..."
            className="w-full rounded-2xl border border-white/10 bg-slate-950/70 py-3 pl-11 pr-4 text-sm text-white outline-none focus:border-gold-400/60" />
        </div>
        <div className="space-y-2">
          {mesas.length === 0 && (
            <div className="py-10 text-center">
              <p className="text-sm text-slate-500">Nenhuma mesa cadastrada.</p>
              <button onClick={() => setCriando(true)} className="mt-3 rounded-2xl border border-blue-400/30 bg-blue-500/15 px-4 py-2 text-xs font-black text-blue-200 hover:bg-blue-500/25">+ Cadastrar mesa</button>
            </div>
          )}
          {mesas.length > 0 && mesasOrdenadas.length === 0 && <p className="py-6 text-center text-sm text-slate-500">Nenhuma mesa encontrada.</p>}
          {mesasOrdenadas.map((m) => {
            const abertos = pedidosAbertos(m);
            return (
              <div key={m.id} className="flex items-center gap-3 rounded-3xl border border-white/10 bg-slate-950/40 p-3">
                <span className="flex h-11 w-14 shrink-0 items-center justify-center rounded-2xl bg-white/[0.06] text-base font-black text-white">
                  {String(m.numero).padStart(2, "0")}
                </span>
                <div className="min-w-0 flex-1">
                  <p className="font-black text-white leading-tight">{m.nome || `Mesa ${String(m.numero).padStart(2, "0")}`}</p>
                  <p className="text-xs text-slate-400">
                    {m.capacidade ? `${m.capacidade} lugares` : "Capacidade não definida"}
                    {m.localizacao && <span className="text-slate-500"> · 📍 {m.localizacao}</span>}
                    {abertos > 0 && <span className="ml-2 rounded-full bg-amber-500/20 px-1.5 py-0.5 font-bold text-amber-300">{abertos} pedido(s) · {formatCurrency(valorMesa(m))}</span>}
                  </p>
                </div>
                {/* Status operacional (briefing item 16): ocupada > inativa > disponível */}
                <span className={`hidden shrink-0 rounded-full px-2.5 py-1 text-[10px] font-black sm:inline ${abertos > 0 ? "bg-amber-500/20 text-amber-300" : m.active === false ? "bg-slate-700 text-slate-300" : "bg-emerald-500/15 text-emerald-300"}`}>
                  {abertos > 0 ? "Ocupada" : m.active === false ? "Inativa" : "Disponível"}
                </span>
                <button onClick={() => toggleMesa(m.id)}
                  className={`shrink-0 rounded-full px-3 py-1.5 text-xs font-black transition ${m.active !== false ? "bg-emerald-500 text-white" : "bg-slate-700 text-slate-200"}`}>
                  {m.active !== false ? "Ativa" : "Inativa"}
                </button>
                <button onClick={() => setEditando(m)}
                  className="shrink-0 rounded-xl border border-white/10 bg-white/[0.06] px-3 py-1.5 text-xs font-black text-blue-300 hover:bg-white/10">✏️</button>
                <button onClick={() => setExcluir(m)}
                  disabled={abertos > 0}
                  title={abertos > 0 ? "Há pedidos em aberto — inative em vez de excluir" : "Excluir mesa"}
                  className="shrink-0 rounded-xl border border-red-400/20 bg-red-500/10 px-3 py-1.5 text-xs font-black text-red-300 hover:bg-red-500/20 disabled:opacity-30 disabled:cursor-not-allowed">🗑️</button>
              </div>
            );
          })}
        </div>
      </div>

      {criando && <MesaCadastroModal onSalvar={salvarNova} onFechar={() => setCriando(false)} />}
      {editando && <MesaEditModal mesa={editando} onSalvar={(d) => { editarMesa(editando.id, d); setEditando(null); }} onFechar={() => setEditando(null)} />}
      {excluir && (
        <ConfirmModal titulo="Excluir mesa?"
          mensagem={`Deseja excluir a Mesa ${String(excluir.numero).padStart(2, "0")}${excluir.nome ? ` (${excluir.nome})` : ""}? Esta ação não pode ser desfeita.`}
          confirmar="Sim, excluir"
          onConfirmar={() => { removerMesa(excluir.id); setExcluir(null); }}
          onCancelar={() => setExcluir(null)} />
      )}
    </main>
  );
}

function MesaCadastroModal({ onSalvar, onFechar }) {
  const [form, setForm] = useState({ numero: "", nome: "", capacidade: "", localizacao: "" });
  const inp = "w-full rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-3 text-white outline-none focus:border-gold-400/60 placeholder:text-slate-600";
  const lbl = "mb-1.5 block text-xs font-bold uppercase tracking-widest text-slate-500";
  const valido = parseInt(form.numero, 10) > 0;
  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/75 backdrop-blur-sm p-4" onClick={onFechar}>
      <div onClick={(e) => e.stopPropagation()} className="flex w-full max-w-md flex-col overflow-hidden rounded-[2rem] border border-white/10 bg-slate-900 shadow-2xl">
        <div className="flex items-center justify-between border-b border-white/10 px-6 py-4">
          <div className="flex items-center gap-2">
            <span className="flex h-9 w-9 items-center justify-center rounded-2xl bg-blue-500/15 text-lg">🪑</span>
            <h2 className="text-lg font-black text-white">Nova mesa</h2>
          </div>
          <button onClick={onFechar} className="rounded-2xl border border-white/10 bg-white/[0.08] px-4 py-2 text-sm font-black text-slate-300 hover:bg-white/20">✕</button>
        </div>
        <div className="px-6 py-5 space-y-3">
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className={lbl}>Número *</label>
              <input autoFocus value={form.numero}
                onChange={(e) => setForm({ ...form, numero: e.target.value.replace(/[^0-9]/g, "").slice(0, 3) })}
                onKeyDown={(e) => { if (e.key === "Enter" && valido) onSalvar(form); }}
                type="tel" inputMode="numeric" placeholder="Ex.: 1" className={inp} />
            </div>
            <div>
              <label className={lbl}>Capacidade</label>
              <input value={form.capacidade}
                onChange={(e) => setForm({ ...form, capacidade: e.target.value.replace(/[^0-9]/g, "").slice(0, 2) })}
                type="tel" inputMode="numeric" placeholder="Nº de lugares" className={inp} />
            </div>
          </div>
          <div>
            <label className={lbl}>Nome / Identificação</label>
            <input value={form.nome} onChange={(e) => setForm({ ...form, nome: e.target.value })}
              placeholder="Ex.: Varanda, VIP, Área externa" className={inp} />
          </div>
          <div>
            <label className={lbl}>Localização</label>
            <input value={form.localizacao} onChange={(e) => setForm({ ...form, localizacao: e.target.value })}
              placeholder="Ex.: Salão principal, 2º andar, próximo à janela" className={inp} />
          </div>
          <p className="text-xs text-slate-500">A mesa ficará disponível imediatamente no tablet do cliente.</p>
        </div>
        <div className="shrink-0 border-t border-white/10 px-6 py-4 flex gap-3">
          <button onClick={onFechar} className="flex-1 rounded-2xl border border-white/10 bg-white/[0.06] py-3.5 text-sm font-black text-slate-300 hover:bg-white/10">Cancelar</button>
          <button onClick={() => onSalvar(form)} disabled={!valido}
            className="flex-[2] rounded-2xl bg-blue-500 py-3.5 text-sm font-black text-white hover:bg-blue-400 transition active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed">
            + Cadastrar mesa
          </button>
        </div>
      </div>
    </div>
  );
}

function MesaEditModal({ mesa, onSalvar, onFechar }) {
  const [form, setForm] = useState({ numero: String(mesa.numero), nome: mesa.nome || "", capacidade: mesa.capacidade ? String(mesa.capacidade) : "" });
  const inp = "w-full rounded-2xl border border-white/10 bg-slate-950/70 px-4 py-3 text-white outline-none focus:border-gold-400/60 placeholder:text-slate-600";
  const lbl = "mb-1.5 block text-xs font-bold uppercase tracking-widest text-slate-500";
  const valido = parseInt(form.numero, 10) > 0;
  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/75 backdrop-blur-sm p-4" onClick={onFechar}>
      <div onClick={(e) => e.stopPropagation()} className="w-full max-w-md rounded-[2rem] border border-white/10 bg-slate-900 shadow-2xl">
        <div className="flex items-center justify-between border-b border-white/10 px-6 py-4">
          <h2 className="text-lg font-black text-white">✏️ Editar mesa {String(mesa.numero).padStart(2, "0")}</h2>
          <button onClick={onFechar} className="rounded-2xl border border-white/10 bg-white/[0.08] px-4 py-2 text-sm font-black text-slate-300 hover:bg-white/20">✕</button>
        </div>
        <div className="px-6 py-4 space-y-3">
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className={lbl}>Número *</label>
              <input autoFocus value={form.numero}
                onChange={(e) => setForm({ ...form, numero: e.target.value.replace(/[^0-9]/g, "").slice(0, 3) })}
                type="tel" inputMode="numeric" className={inp} />
            </div>
            <div>
              <label className={lbl}>Capacidade</label>
              <input value={form.capacidade}
                onChange={(e) => setForm({ ...form, capacidade: e.target.value.replace(/[^0-9]/g, "").slice(0, 2) })}
                type="tel" inputMode="numeric" placeholder="Nº de lugares" className={inp} />
            </div>
          </div>
          <div>
            <label className={lbl}>Nome / Identificação</label>
            <input value={form.nome} onChange={(e) => setForm({ ...form, nome: e.target.value })}
              placeholder="Ex.: Varanda, VIP, Área externa" className={inp} />
          </div>
          <button onClick={() => valido && onSalvar(form)} disabled={!valido}
            className="w-full rounded-2xl bg-emerald-500 py-4 text-sm font-black text-white hover:bg-emerald-400 disabled:opacity-50 transition">
            💾 Salvar alterações
          </button>
        </div>
      </div>
    </div>
  );
}
